/* ==========================================================================
   FAMILY DASHBOARD - APPLICATION BUNDLE
   Auto-generated by scripts/build.js from src/. Do not edit by hand.
   ========================================================================== */

(function() {
  'use strict';

// Event look: tint by the one attendee; several attendees stay neutral and show a dot per person.
  const memberColor = (id) => stateManager.data.members.find(m => m.id === id)?.color;
  const evIds = (evt) => (evt.memberIds && evt.memberIds.length > 1 ? evt.memberIds : [evt.memberId]);
  // Tints use rgba() from an "r,g,b" variable: color-mix() isn't supported on older iPadOS, where the cards lost their fill.
  const hexRgb = (hex) => { const m = /^#?([0-9a-f]{6})$/i.exec(hex || ''); return m ? [0, 2, 4].map(i => parseInt(m[1].slice(i, i + 2), 16)).join(',') : null; };
  function styleEvent(el, evt, ids = evIds(evt)) {
    const rgb = ids.length === 1 && hexRgb(memberColor(ids[0]));
    if (rgb) el.style.setProperty('--ev-rgb', rgb);
  }
  const evDots = (evt, ids = evIds(evt)) =>
    `<span class="ev-dots" aria-label="${esc(ids.map(id => stateManager.data.members.find(m => m.id === id)?.name || id).join(', '))}">${ids.map(id => `<i style="background:${memberColor(id) || 'var(--color-primary)'}"></i>`).join('')}</span>`;

  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

/* --------------------------------------------------------------------------
     1. WEATHER & CLOCK
     -------------------------------------------------------------------------- */
  function updateClock() {
    const now = new Date();
    let hours = now.getHours();
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;

    const clockEl = document.getElementById('clock');
    const clockText = `${hours}:${minutes} ${ampm}`;
    if (clockEl && clockEl.dataset.t !== clockText) {
      clockEl.dataset.t = clockText;
      clockEl.innerHTML = `${hours}:${minutes} <span class="ampm">${ampm}</span>`;
    }

    const dateEl = document.getElementById('current-date');
    if (dateEl) {
      const day = now.toLocaleDateString('en-US', { weekday: 'long' });
      const date = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
      const dateText = `${day}\n${date}`;
      if (dateEl.dataset.t !== dateText) {
        dateEl.dataset.t = dateText;
        dateEl.innerHTML = `<span>${day}</span><span>${date}</span>`;
      }
    }
  }

  /* --------------------------------------------------------------------------
     WEATHER & RADAR ENGINE (Live Open-Meteo & Windy.com Embed)
     -------------------------------------------------------------------------- */
  let weatherCache = {
    timestamp: 0,
    data: null
  };

  const DEFAULT_WEATHER_DATA = {
    locationName: 'Home',
    current: {
      temp: 74,
      feelsLike: 75,
      condition: 'Sunny & Clear',
      icon: 'fa-sun text-amber',
      hilo: 'H: 78° • L: 58°',
      rainProb: 0,
      windSpeed: 6,
      windDir: 'NW',
      humidity: 45,
      aqi: 32,
      uv: 5
    },
    forecast: [
      { day: 'Today', dateStr: 'Oct 3', isToday: true, icon: 'fa-sun text-amber', desc: 'Sunny & Clear', tempHigh: 78, tempLow: 58, precipProb: 0, windSpeed: 6, humidity: 45, aqi: 32 },
      { day: 'Sun', dateStr: 'Oct 4', isToday: false, icon: 'fa-cloud-sun text-amber', desc: 'Partly Cloudy', tempHigh: 76, tempLow: 57, precipProb: 10, windSpeed: 8, humidity: 52, aqi: 38 },
      { day: 'Mon', dateStr: 'Oct 5', isToday: false, icon: 'fa-cloud-rain text-sky', desc: 'Light Rain', tempHigh: 70, tempLow: 54, precipProb: 65, windSpeed: 12, humidity: 75, aqi: 24 },
      { day: 'Tue', dateStr: 'Oct 6', isToday: false, icon: 'fa-cloud text-secondary', desc: 'Mostly Cloudy', tempHigh: 73, tempLow: 56, precipProb: 20, windSpeed: 9, humidity: 60, aqi: 29 },
      { day: 'Wed', dateStr: 'Oct 7', isToday: false, icon: 'fa-sun text-amber', desc: 'Clear Skies', tempHigh: 79, tempLow: 60, precipProb: 5, windSpeed: 7, humidity: 46, aqi: 35 }
    ]
  };

  // Older versions saved these defaults into settings, so they can't be told apart from "never set".
  const isDefaultLocation = (w) => !w?.lat || (w.lat === 37.7749 && w.lon === -122.4194 && (!w.locationName || w.locationName === 'Home'));

  // Home Assistant only knows its home as "Home"; turn the coordinates into a city name (cached per place).
  const cityCache = {};
  async function lookupCityName(lat, lon) {
    const key = `${lat},${lon}`;
    if (!(key in cityCache)) {
      cityCache[key] = null;
      try {
        const res = await fetch(`https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${lat}&longitude=${lon}&localityLanguage=en`);
        const g = res.ok ? await res.json() : {};
        const city = g.city || g.locality;
        cityCache[key] = city ? [city, g.principalSubdivision].filter(Boolean).join(', ') : null;
      } catch (_) {}
    }
    return cityCache[key];
  }

  function getWeatherCoordinates() {
    const s = (typeof stateManager !== 'undefined' && stateManager?.data?.settings) || {};
    const cfg = window.FAMILY_DASHBOARD_CONFIG || {};

    let lat = s.weather?.lat ?? cfg.weather?.latitude ?? 37.7749;
    let lon = s.weather?.lon ?? cfg.weather?.longitude ?? -122.4194;
    let locationName = s.weather?.locationName || cfg.weather?.locationName || 'Home';

    return { lat, lon, locationName };
  }

  function getWmoCondition(code) {
    if (code === 0) return { desc: 'Clear Sky', icon: 'fa-sun text-amber' };
    if (code === 1) return { desc: 'Mainly Clear', icon: 'fa-sun text-amber' };
    if (code === 2) return { desc: 'Partly Cloudy', icon: 'fa-cloud-sun text-amber' };
    if (code === 3) return { desc: 'Overcast', icon: 'fa-cloud text-secondary' };
    if (code === 45 || code === 48) return { desc: 'Foggy', icon: 'fa-smog text-secondary' };
    if (code >= 51 && code <= 55) return { desc: 'Drizzle', icon: 'fa-cloud-rain text-sky' };
    if (code === 56 || code === 57) return { desc: 'Freezing Drizzle', icon: 'fa-snowflake text-sky' };
    if (code === 61 || code === 63) return { desc: 'Rain', icon: 'fa-cloud-rain text-sky' };
    if (code === 65) return { desc: 'Heavy Rain', icon: 'fa-cloud-showers-heavy text-sky' };
    if (code === 66 || code === 67) return { desc: 'Freezing Rain', icon: 'fa-snowflake text-sky' };
    if (code >= 71 && code <= 77) return { desc: 'Snowfall', icon: 'fa-snowflake text-sky' };
    if (code === 80 || code === 81) return { desc: 'Rain Showers', icon: 'fa-cloud-rain text-sky' };
    if (code === 82) return { desc: 'Heavy Showers', icon: 'fa-cloud-showers-heavy text-sky' };
    if (code === 85 || code === 86) return { desc: 'Snow Showers', icon: 'fa-snowflake text-sky' };
    if (code === 95) return { desc: 'Thunderstorm', icon: 'fa-cloud-bolt text-amber' };
    if (code >= 96) return { desc: 'Severe Storm', icon: 'fa-cloud-bolt text-danger' };
    return { desc: 'Partly Cloudy', icon: 'fa-cloud-sun text-amber' };
  }

  function getAqiCategory(aqi) {
    if (aqi <= 50) return { text: 'Good', className: 'aqi-good', iconColor: 'text-success' };
    if (aqi <= 100) return { text: 'Moderate', className: 'aqi-moderate', iconColor: 'text-amber' };
    if (aqi <= 150) return { text: 'Sensitive', className: 'aqi-sensitive', iconColor: 'text-rose' };
    if (aqi <= 200) return { text: 'Unhealthy', className: 'aqi-unhealthy', iconColor: 'text-danger' };
    return { text: 'Hazardous', className: 'aqi-hazardous', iconColor: 'text-purple' };
  }

  function degToCompass(deg) {
    const compass = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
    const idx = Math.round(deg / 45) % 8;
    return compass[idx] || 'N';
  }

  async function fetchLiveWeatherData(force = false) {
    const now = Date.now();
    if (!force && weatherCache.data && (now - weatherCache.timestamp < 15 * 60 * 1000)) {
      return weatherCache.data;
    }

    const { lat, lon, locationName: savedName } = getWeatherCoordinates();
    const locationName = savedName === 'Home' ? (await lookupCityName(lat, lon)) || savedName : savedName;

    try {
      const weatherUrl = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,wind_direction_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max,uv_index_max,sunrise,sunset&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch&timezone=auto&forecast_days=5`;
      const aqiUrl = `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${lat}&longitude=${lon}&current=us_aqi,pm2_5&hourly=us_aqi&timezone=auto&forecast_days=5`;

      const [wRes, aRes] = await Promise.all([
        fetch(weatherUrl).catch(() => null),
        fetch(aqiUrl).catch(() => null)
      ]);

      if (!wRes || !wRes.ok) {
        throw new Error('Weather API request failed');
      }

      const wData = await wRes.json();
      const aData = aRes && aRes.ok ? await aRes.json() : null;

      const current = wData.current || {};
      const daily = wData.daily || {};
      const currentCode = current.weather_code ?? 0;
      const currentCond = getWmoCondition(currentCode);
      const currentWindDir = degToCompass(current.wind_direction_10m || 0);
      const currentAqiVal = Math.round(aData?.current?.us_aqi || 32);

      const daysOfWeek = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

      const forecastList = [];
      const times = daily.time || [];

      for (let i = 0; i < Math.min(5, times.length); i++) {
        const dateParts = times[i].split('-');
        const dateObj = new Date(parseInt(dateParts[0]), parseInt(dateParts[1]) - 1, parseInt(dateParts[2]));
        const isToday = i === 0;
        const dayLabel = isToday ? 'Today' : daysOfWeek[dateObj.getDay()];
        const dateLabel = `${months[dateObj.getMonth()]} ${dateObj.getDate()}`;
        const code = daily.weather_code ? daily.weather_code[i] : 0;
        const cond = isToday ? currentCond : getWmoCondition(code); // today's card matches the header

        let dayAqi = currentAqiVal;
        if (aData?.hourly?.us_aqi && aData.hourly.us_aqi.length >= (i + 1) * 24) {
          const slice = aData.hourly.us_aqi.slice(i * 24, (i + 1) * 24).filter(v => v !== null);
          if (slice.length > 0) {
            dayAqi = Math.round(slice.reduce((acc, v) => acc + v, 0) / slice.length);
          }
        }

        forecastList.push({
          day: dayLabel,
          dateStr: dateLabel,
          isToday: isToday,
          icon: cond.icon,
          desc: cond.desc,
          tempHigh: Math.round(daily.temperature_2m_max ? daily.temperature_2m_max[i] : 75),
          tempLow: Math.round(daily.temperature_2m_min ? daily.temperature_2m_min[i] : 55),
          precipProb: Math.round(daily.precipitation_probability_max ? daily.precipitation_probability_max[i] : 0),
          windSpeed: Math.round(daily.wind_speed_10m_max ? daily.wind_speed_10m_max[i] : 7),
          humidity: Math.round(current.relative_humidity_2m || 50),
          aqi: dayAqi,
          uv: daily.uv_index_max ? Math.round(daily.uv_index_max[i]) : 5
        });
      }

      const todayHigh = forecastList[0]?.tempHigh ?? 78;
      const todayLow = forecastList[0]?.tempLow ?? 58;

      const parsedData = {
        locationName: locationName,
        sun: { sunrise: daily.sunrise?.[0], sunset: daily.sunset?.[0] },
        current: {
          temp: Math.round(current.temperature_2m ?? 74),
          feelsLike: Math.round(current.apparent_temperature ?? current.temperature_2m ?? 74),
          condition: currentCond.desc,
          icon: currentCond.icon,
          hilo: `H: ${todayHigh}° • L: ${todayLow}°`,
          rainProb: forecastList[0]?.precipProb ?? 0,
          windSpeed: Math.round(current.wind_speed_10m ?? 6),
          windDir: currentWindDir,
          humidity: Math.round(current.relative_humidity_2m ?? 45),
          aqi: currentAqiVal,
          uv: forecastList[0]?.uv ?? 5
        },
        forecast: forecastList
      };

      weatherCache = {
        timestamp: Date.now(),
        data: parsedData
      };

      return parsedData;
    } catch (err) {
      console.warn('Weather fetch fallback triggered:', err);
      return weatherCache.data || { ...DEFAULT_WEATHER_DATA, offline: true };
    }
  }

  function renderWeatherUI(data) {
    if (!data) return;

    // 1. Update Header Weather Widget
    const weatherIcon = document.getElementById('weather-icon');
    const weatherTemp = document.getElementById('weather-temp');
    const weatherDesc = document.getElementById('weather-desc');
    const weatherHilo = document.getElementById('weather-hilo');
    const rainVal = document.getElementById('header-rain-val');
    const aqiVal = document.getElementById('header-aqi-val');

    if (weatherIcon) weatherIcon.className = `fa-solid weather-icon ${data.current.icon}`;
    if (weatherTemp) weatherTemp.textContent = data.offline ? '--' : `${data.current.temp}°F`;
    if (weatherDesc) weatherDesc.textContent = data.offline ? 'Weather unavailable' : data.current.condition;
    if (weatherHilo) weatherHilo.textContent = data.current.hilo;
    if (rainVal) rainVal.textContent = `${data.current.rainProb}%`;
    if (aqiVal) aqiVal.textContent = `${data.current.aqi}`;

    // Screensaver weather (under the date)
    const pw = document.getElementById('photo-weather');
    if (pw) {
      pw.hidden = !!data.offline;
      document.getElementById('photo-weather-icon').className = `fa-solid ${data.current.icon}`;
      document.getElementById('photo-weather-temp').textContent = `${data.current.temp}°F`;
      document.getElementById('photo-weather-aqi').textContent = data.current.aqi;
    }

    // 2. Update Weather Modal Hero
    const heroIcon = document.getElementById('hero-weather-icon');
    const heroTemp = document.getElementById('hero-weather-temp');
    const heroDesc = document.getElementById('hero-weather-desc');
    const heroLocation = document.getElementById('hero-weather-location');
    const heroHilo = document.getElementById('hero-weather-hilo');
    const heroFeels = document.getElementById('hero-weather-feels');

    if (heroIcon) heroIcon.className = `fa-solid hero-icon ${data.current.icon}`;
    if (heroTemp) heroTemp.textContent = `${data.current.temp}°F`;
    if (heroDesc) heroDesc.textContent = data.current.condition;
    if (heroLocation) heroLocation.innerHTML = `<i class="fa-solid fa-location-dot text-rose"></i> ${esc(data.locationName || 'Home')}`;
    if (heroHilo) heroHilo.textContent = data.current.hilo;
    if (heroFeels) heroFeels.textContent = `Feels like ${data.current.feelsLike}°F`;

    // 3. Extended Metric Pills
    const metricRain = document.getElementById('metric-rain');
    const metricWind = document.getElementById('metric-wind');
    const metricHumidity = document.getElementById('metric-humidity');
    const metricAqi = document.getElementById('metric-aqi');
    const metricAqiIcon = document.getElementById('metric-aqi-icon');
    const metricUv = document.getElementById('metric-uv');

    if (metricRain) metricRain.textContent = `${data.current.rainProb}%`;
    if (metricWind) metricWind.textContent = `${data.current.windSpeed} mph ${data.current.windDir}`;
    if (metricHumidity) metricHumidity.textContent = `${data.current.humidity}%`;
    if (metricAqi) {
      const aqiCat = getAqiCategory(data.current.aqi);
      metricAqi.textContent = `AQI ${data.current.aqi} (${aqiCat.text})`;
      if (metricAqiIcon) metricAqiIcon.className = `fa-solid fa-leaf ${aqiCat.iconColor}`;
    }
    if (metricUv) {
      let uvLabel = 'Low';
      if (data.current.uv >= 3) uvLabel = 'Mod';
      if (data.current.uv >= 6) uvLabel = 'High';
      if (data.current.uv >= 8) uvLabel = 'Very High';
      metricUv.textContent = `${data.current.uv} (${uvLabel})`;
    }

    // 4. Horizontal 5-Day Forecast Grid
    const container = document.getElementById('forecast-grid-container');
    if (container && data.forecast && data.forecast.length) {
      container.innerHTML = data.forecast.map(f => {
        const aqiInfo = getAqiCategory(f.aqi);
        const rainHighlight = f.precipProb >= 30 ? 'high-precip' : '';
        return `
          <div class="forecast-day-card glass-card ${f.isToday ? 'is-today' : ''}">
            <div class="forecast-day-header">
              <span class="forecast-day-name">${f.day}</span>
              <span class="forecast-day-date">${f.dateStr}</span>
            </div>
            <div class="forecast-day-icon-wrap">
              <i class="fa-solid ${f.icon} forecast-day-icon"></i>
              <span class="forecast-day-desc">${f.desc}</span>
            </div>
            <div class="forecast-day-temps">
              <span class="temp-high">${f.tempHigh}°</span>
              <span class="temp-separator">/</span>
              <span class="temp-low">${f.tempLow}°</span>
            </div>
            <div class="forecast-day-details">
              <div class="forecast-detail-row" title="Chance of Precipitation">
                <span><i class="fa-solid fa-droplet text-sky"></i> Rain</span>
                <span class="detail-val ${rainHighlight}">${f.precipProb}%</span>
              </div>
              <div class="forecast-detail-row" title="Peak wind speed for the day">
                <span><i class="fa-solid fa-wind text-sky"></i> Peak wind</span>
                <span class="detail-val">${f.windSpeed} mph</span>
              </div>
              <div class="forecast-detail-row" title="Relative Humidity">
                <span><i class="fa-solid fa-water text-sky"></i> Humidity</span>
                <span class="detail-val">${f.humidity}%</span>
              </div>
              <div class="forecast-detail-row" title="Air Quality Index">
                <span><i class="fa-solid fa-leaf ${aqiInfo.iconColor}"></i> AQI</span>
                <span class="detail-val aqi-val ${aqiInfo.className}">${f.aqi}</span>
              </div>
            </div>
          </div>
        `;
      }).join('');
    }
  }

  // Windy Radar Modal Manager
  function openWindyRadarModal(layer = 'radar') {
    const modal = document.getElementById('windy-radar-modal');
    const iframe = document.getElementById('windy-iframe');
    const spinner = document.getElementById('windy-spinner');
    const extLink = document.getElementById('windy-external-link');
    if (!modal || !iframe) return;

    const { lat, lon } = getWeatherCoordinates();

    document.querySelectorAll('.layer-toggle-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.layer === layer);
    });

    if (extLink) {
      extLink.href = `https://www.windy.com/?${layer},${lat},${lon},8`;
    }

    // Show the modal before loading: Windy sizes/centers its map from the iframe's viewport, which is 0x0 while hidden.
    modal.classList.add('active');

    if (spinner) spinner.classList.remove('loaded');
    const product = layer === 'radar' ? 'radar' : 'ecmwf';
    const targetSrc = `https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=in&metricTemp=%C2%B0F&metricWind=mph&zoom=8&overlay=${layer}&product=${product}&level=surface&lat=${lat}&lon=${lon}&detailLat=${lat}&detailLon=${lon}&marker=true`;

    if (iframe.src !== targetSrc) {
      iframe.onload = () => {
        if (spinner) spinner.classList.add('loaded');
      };
      iframe.src = targetSrc;
    } else {
      if (spinner) spinner.classList.add('loaded');
    }
  }

  // Click the location name in the weather popup to search for another place
  function initLocationPicker() {
    const btn = document.getElementById('hero-weather-location');
    const box = document.getElementById('weather-location-picker');
    const input = document.getElementById('weather-location-search');
    const list = document.getElementById('weather-location-results');
    if (!btn || !box || !input || !list) return;

    let places = [];
    let timer;

    btn.addEventListener('click', () => {
      box.hidden = !box.hidden;
      if (!box.hidden) input.focus();
    });

    input.addEventListener('input', () => {
      clearTimeout(timer);
      timer = setTimeout(async () => {
        const q = input.value.trim();
        if (q.length < 2) { list.innerHTML = ''; return; }
        try {
          const res = await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=5&language=en&format=json`);
          places = (await res.json()).results || [];
          list.innerHTML = places.length
            ? places.map((p, i) => `<li><button type="button" data-i="${i}">${esc([p.name, p.admin1, p.country_code].filter(Boolean).join(', '))}</button></li>`).join('')
            : '<li class="muted">No matches</li>';
        } catch (_) {
          list.innerHTML = '<li class="muted">Search unavailable offline</li>';
        }
      }, 300);
    });

    list.addEventListener('click', (e) => {
      const p = places[e.target.closest('button[data-i]')?.dataset.i];
      if (!p) return;
      const s = stateManager.data.settings;
      s.weather = { ...s.weather, lat: p.latitude, lon: p.longitude, locationName: [p.name, p.admin1].filter(Boolean).join(', ') };
      stateManager.save();
      box.hidden = true;
      input.value = '';
      list.innerHTML = '';
      fetchLiveWeatherData(true).then(renderWeatherUI);
    });
  }

  function initWindyRadar() {
    const radarBtn = document.getElementById('open-windy-radar-btn');
    const modal = document.getElementById('windy-radar-modal');
    const closeBtn = document.getElementById('windy-radar-modal-close');

    if (radarBtn) {
      radarBtn.addEventListener('click', () => openWindyRadarModal('radar'));
    }
    if (closeBtn && modal) {
      closeBtn.addEventListener('click', () => modal.classList.remove('active'));
    }
    if (modal) {
      modal.addEventListener('click', (e) => {
        if (e.target === modal) modal.classList.remove('active');
      });
    }

    document.querySelectorAll('.layer-toggle-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const layer = btn.dataset.layer;
        if (layer) openWindyRadarModal(layer);
      });
    });
  }

  async function checkHomeAssistantCoordinates() {
    try {
      const s = (typeof stateManager !== 'undefined' && stateManager?.data?.settings) || {};
      const haUrl = s.haUrl || window.FAMILY_DASHBOARD_CONFIG?.homeAssistant?.url;
      const haToken = s.haToken || window.FAMILY_DASHBOARD_CONFIG?.homeAssistant?.token;

      if ((haWS?.isNative?.() || (haUrl && haToken)) && isDefaultLocation(s.weather)) {
        let cfg = null;
        try {
          cfg = await haWS.send({ type: 'get_config' });
        } catch (_) {}
        if (!cfg && haUrl && haToken) {
          const res = await fetch(`${haUrl}/api/config`, {
            headers: { 'Authorization': `Bearer ${haToken}` }
          });
          if (res.ok) cfg = await res.json();
        }
        if (cfg && cfg.latitude && cfg.longitude) {
          if (!s.weather) s.weather = {};
          s.weather.lat = cfg.latitude;
          s.weather.lon = cfg.longitude;
          s.weather.locationName = cfg.location_name || 'Home';
          if (typeof stateManager !== 'undefined') stateManager.save();
          fetchLiveWeatherData(true).then(renderWeatherUI);
        }
      }
    } catch (e) {
      // HA unreachable or offline
    }
  }

  function initClockAndWeather(toast) {
    updateClock();
    setInterval(updateClock, 1000);

    const weatherCard = document.getElementById('weather-card');
    const weatherModal = document.getElementById('weather-modal');
    const weatherModalClose = document.getElementById('weather-modal-close');
    const weatherRefreshBtn = document.getElementById('weather-refresh-btn');

    renderWeatherUI({ ...DEFAULT_WEATHER_DATA, offline: true });
    fetchLiveWeatherData().then(renderWeatherUI);

    setTimeout(checkHomeAssistantCoordinates, 2000);

    setInterval(() => {
      fetchLiveWeatherData(true).then(renderWeatherUI);
    }, 15 * 60 * 1000);

    if (weatherCard && weatherModal) {
      weatherCard.addEventListener('click', () => {
        fetchLiveWeatherData().then(renderWeatherUI);
        weatherModal.classList.add('active');
      });

      if (weatherModalClose) {
        weatherModalClose.addEventListener('click', () => {
          weatherModal.classList.remove('active');
        });
      }

      weatherModal.addEventListener('click', (e) => {
        if (e.target === weatherModal) weatherModal.classList.remove('active');
      });
    }

    if (weatherRefreshBtn) {
      weatherRefreshBtn.addEventListener('click', async () => {
        const icon = weatherRefreshBtn.querySelector('i');
        if (icon) icon.classList.add('fa-spin');
        try {
          const data = await fetchLiveWeatherData(true);
          renderWeatherUI(data);
          toast?.('🌤️ Weather forecast updated!');
        } finally {
          setTimeout(() => {
            if (icon) icon.classList.remove('fa-spin');
          }, 600);
        }
      });
    }

    initWindyRadar();
    initLocationPicker();
  }

/* --------------------------------------------------------------------------
     NIGHT MODE RULES
     -------------------------------------------------------------------------- */
  const NightMode = {
    // settings: nightMode ('off' | 'schedule' | 'sun'), nightStart, nightStop ('HH:MM').
    // sun: today's { sunrise, sunset } as 'YYYY-MM-DDTHH:MM', or nothing when the weather has not loaded (set times apply).
    isNight(settings, now, sun) {
      if (settings.nightMode !== 'sun' && settings.nightMode !== 'schedule') return false;
      const useSun = settings.nightMode === 'sun' && sun?.sunset && sun?.sunrise;
      const start = useSun ? sun.sunset.slice(11) : settings.nightStart;
      const stop = useSun ? sun.sunrise.slice(11) : settings.nightStop;
      const minutes = (hhmm) => {
        const [h, m] = String(hhmm).split(':').map(Number);
        return h * 60 + m;
      };
      const from = minutes(start);
      const to = minutes(stop);
      const at = now.getHours() * 60 + now.getMinutes();
      if (from === to || Number.isNaN(from) || Number.isNaN(to)) return false; // an empty window or a malformed saved time
      return from < to ? at >= from && at < to : at >= from || at < to; // usually crosses midnight
    }
  };

/* --------------------------------------------------------------------------
     2. STATE MANAGEMENT & LOCAL STORAGE
     -------------------------------------------------------------------------- */
  const STORAGE_KEY = 'family_dashboard_state_v1';
  const SCHEMA_VERSION = 1;
  const REMOTE_KEY = 'family_dashboard_state';

  // Every setting once: its starting value, the config.js key that seeds it, the form field that edits it and how far
  // it may travel. scope: 'device' stays on this tablet (tokens); 'private' is shared between tablets but never
  // exported (the parent PIN); anything else is household data. blank: what an empty form field means ('keep' the
  // saved value, use the 'default', or leave it empty). min: the smallest number the form accepts.
  const SETTINGS = [
    { key: 'haUrl', def: 'http://homeassistant.local:8123', config: 'homeAssistant.url', field: 'ha-url-input', blank: 'keep' },
    { key: 'haToken', def: '', config: 'homeAssistant.token', field: 'ha-token-input', blank: 'keep', scope: 'device' },
    { key: 'haKioskMode', def: false, config: 'haKioskMode', field: 'ha-kiosk-mode-toggle', type: 'boolean', scope: 'device' },
    { key: 'googleKeepUrl', def: 'https://keep.google.com', config: 'googleKeepUrl', field: 'keep-url-input', blank: 'keep' },
    { key: 'haGroceryTodoEntity', def: '', config: 'haGroceryTodoEntity', field: 'grocery-entity-input' },
    { key: 'haMealIdeasEntity', def: 'todo.meal_ideas', config: 'haMealIdeasEntity', field: 'meal-ideas-entity-input', blank: 'default' },
    { key: 'haMealPlanEntity', def: 'todo.weekly_meal_plan', config: 'haMealPlanEntity', field: 'meal-plan-entity-input', blank: 'default' },
    { key: 'photoEntity', def: 'image.immich_random_favorite_image', config: 'photoEntity', field: 'photo-entity-input', blank: 'default' }, // image.* entity that serves the screensaver photo
    { key: 'immichUrl', def: 'http://homeassistant.local:2283', config: 'immich.url' },
    { key: 'immichApiKey', def: '', config: 'immich.apiKey', scope: 'device' },
    { key: 'idleSaverMinutes', def: 2, field: 'idle-minutes-input', min: 1 },
    { key: 'photoIntervalSeconds', def: 30, field: 'photo-interval-input', min: 10 },
    { key: 'nightMode', def: 'off', field: 'night-mode-select', blank: 'default' }, // 'off', 'schedule' or 'sun'
    { key: 'nightStart', def: '21:00', field: 'night-start-input', blank: 'default' },
    { key: 'nightStop', def: '07:00', field: 'night-stop-input', blank: 'default' },
    { key: 'nightBrightness', def: 15, field: 'night-brightness-input', min: 5 }, // percent left showing
    { key: 'doorbellEntity', def: '', config: 'doorbell.entity', field: 'doorbell-entity-input' }, // event.* or binary_sensor.* that fires on a doorbell press
    { key: 'doorbellCamera', def: '', config: 'doorbell.camera', field: 'doorbell-camera-input' }, // camera.* shown in the popup
    { key: 'doorbellSeconds', def: 30, config: 'doorbell.seconds', field: 'doorbell-seconds-input', min: 5 },
    { key: 'parentPin', scope: 'private' }, // unset until a parent sets one; the PIN gate falls back to '1234'
    // No defaults: unset means "use the Home Assistant home location" (weather.js falls back to a built-in default)
    { key: 'weather.lat', config: 'weather.latitude' },
    { key: 'weather.lon', config: 'weather.longitude' },
    { key: 'weather.locationName', config: 'weather.locationName' }
  ];

  const settingAt = (obj, path) => path.split('.').reduce((o, k) => o?.[k], obj);
  const putSetting = (obj, path, value) => {
    const keys = path.split('.');
    const last = keys.pop();
    keys.reduce((o, k) => (o[k] ||= {}), obj)[last] = value;
  };

  const SettingsSchema = {
    defaults() {
      const settings = {};
      SETTINGS.filter(e => 'def' in e).forEach(e => putSetting(settings, e.key, e.def));
      return settings;
    },

    // config.js wins over a saved value wherever it sets one.
    applyConfig(settings, cfg) {
      if (!cfg) return;
      SETTINGS.filter(e => e.config).forEach(e => {
        const value = settingAt(cfg, e.config);
        if (e.type === 'boolean') {
          if (typeof value === 'boolean') putSetting(settings, e.key, value);
        } else if (value) {
          putSetting(settings, e.key, value);
        }
      });
    },

    // A blank saved where a blank is not allowed means "never set": use the default.
    normalize(settings) {
      SETTINGS.filter(e => e.blank === 'default').forEach(e => { if (!settings[e.key]) settings[e.key] = e.def; });
      if (typeof settings.haKioskMode !== 'boolean') settings.haKioskMode = false;
    },

    without(settings, scopes) {
      const out = { ...settings };
      SETTINGS.filter(e => scopes.includes(e.scope)).forEach(e => { delete out[e.key]; });
      return out;
    },

    pick(settings, scopes) {
      const out = {};
      SETTINGS.filter(e => scopes.includes(e.scope) && e.key in settings).forEach(e => { out[e.key] = settings[e.key]; });
      return out;
    },

    fields() { return SETTINGS.filter(e => e.field).map(e => e.field); },

    // { field id: text to show } for the settings form.
    toForm(settings) {
      const form = {};
      SETTINGS.filter(e => e.field).forEach(e => {
        if (e.type === 'boolean') {
          form[e.field] = settings[e.key] ? 'true' : 'false';
        } else {
          form[e.field] = String(settings[e.key] || (e.min !== undefined || e.blank === 'default' ? e.def : ''));
        }
      });
      return form;
    },

    // What was typed ({ field id: text }, missing fields left out) -> the settings to change.
    fromForm(values) {
      const patch = {};
      SETTINGS.filter(e => e.field && values[e.field] !== undefined).forEach(e => {
        const raw = values[e.field];
        if (e.type === 'boolean') {
          patch[e.key] = raw === 'true' || raw === 'on' || raw === true;
        } else if (e.min !== undefined) {
          const n = parseInt(raw, 10);
          if (n >= e.min) patch[e.key] = n;
        } else if (e.blank === 'keep') {
          if (raw) patch[e.key] = raw;
        } else {
          patch[e.key] = e.blank === 'default' ? (raw || e.def) : raw;
        }
      });
      return patch;
    }
  };

  // Schema skeleton only. Household seed data lives in data/dashboard-data.json.
  const defaultState = () => ({
    schemaVersion: SCHEMA_VERSION,
    activeMemberId: 'all', // which member this tablet is showing; never shared with other tablets
    themeMode: 'auto',
    members: [],
    events: [], // your own events; Home Assistant's are kept apart by the calendar feed
    routines: [],
    chores: [],
    rewards: [], // prize store: { id, title, cost }
    parentTasks: [],
    kidAchievements: {},
    groceries: [],
    mealIdeas: [],
    settings: SettingsSchema.defaults()
  });

  // Parent "reminders" and "tasks" are one thing: a task that may repeat.
  function unifyTasks(state) {
    if (!state.recurringReminders) return state;
    state.parentTasks = [...(state.parentTasks || []), ...state.recurringReminders.map(r => ({
      id: r.id, memberId: r.memberId === 'both' ? 'shared' : r.memberId, title: r.title, notes: r.notes || '',
      priority: 'medium', category: r.category === 'routine' ? 'home' : (r.category || 'home'),
      dueDate: r.nextDueDate || '', frequency: r.frequency || 'none', lastCompletedDate: r.lastCompletedDate || null,
      showOnCalendar: !!r.showOnCalendar, completed: false
    }))];
    delete state.recurringReminders;
    return state;
  }

  // What a member keeps from the saved copy when config.js is applied: earned stars and goals, and what Settings edits.
  const MEMBER_EDITS = ['stars', 'targetReward', 'targetStars', 'goalDoneFor', 'avatar', 'haCalendarEntity'];

  // The household document: where it is kept (this tablet, and Home Assistant so every tablet shares it), how a saved
  // copy, config.js and the defaults combine, and which copy wins when tablets disagree (the newest edit).
  class StateManager {
    constructor({ local, remote, baseline, config, now = () => Date.now(), pushDelay = 1500 }) {
      this.local = local;       // { get(key) -> string | null, set(key, string) }: this tablet's storage
      this.remote = remote;     // { ready() -> bool, get() -> document | null, set(document) }: the copy tablets share
      this.baseline = baseline; // async () -> seed document | null: data/dashboard-data.json
      this.config = config;     // window.FAMILY_DASHBOARD_CONFIG
      this.now = now;
      this.pushDelay = pushDelay;
      this.listeners = [];
      this.pushTimer = null;
      this.data = this.loadState();
    }

    subscribe(fn) {
      this.listeners.push(fn);
      return () => { this.listeners = this.listeners.filter(l => l !== fn); };
    }

    // The defaults, then the document, then config.js where it sets something (members keep what was saved for them).
    hydrate(doc) {
      const base = defaultState();
      const state = { ...base, ...doc, settings: { ...base.settings, ...(doc.settings || {}) } };
      unifyTasks(state);
      ['theme', 'meals'].forEach(k => { delete state[k]; });                                  // no longer used
      ['haConnected', 'immichEnabled', 'haTasksTodoEntity'].forEach(k => { delete state.settings[k]; });
      SettingsSchema.normalize(state.settings);
      SettingsSchema.applyConfig(state.settings, this.config);
      this.applyConfigMembers(state);
      state.schemaVersion = SCHEMA_VERSION; // ponytail: no migrations yet; branch on doc.schemaVersion here when the shape changes
      return state;
    }

    applyConfigMembers(state) {
      const configured = this.config?.members;
      if (!Array.isArray(configured) || !configured.length) return;
      state.members = configured.map(cm => {
        const saved = (state.members || []).find(m => m.id === cm.id) || {};
        const kept = {};
        MEMBER_EDITS.filter(k => saved[k] != null).forEach(k => { kept[k] = saved[k]; });
        return { ...cm, stars: cm.stars || 0, ...kept };
      });
    }

    loadState() {
      let doc = {};
      try {
        const saved = this.local.get(STORAGE_KEY);
        if (saved) doc = JSON.parse(saved);
      } catch (e) {
        console.warn('Error loading saved state:', e);
      }
      return this.hydrate(doc);
    }

    async loadBaselineIfEmpty() {
      if (this.local.get(STORAGE_KEY)) return false;
      try {
        const seed = await this.baseline();
        if (seed) {
          this.data = this.hydrate(seed);
          this.save({ stamp: false, push: false });
          return true;
        }
      } catch (e) {
        console.warn('Could not load data/dashboard-data.json on first run:', e);
      }
      return false;
    }

    async resetToBaseline() {
      try {
        const seed = await this.baseline();
        if (seed) {
          this.data = this.hydrate(seed);
          this.save();
          return true;
        }
      } catch (err) {
        console.warn('Could not fetch data/dashboard-data.json:', err);
      }
      return false; // keep existing data rather than wiping it
    }

    // ---- backup ----
    // Never tokens, the PIN, or which member this tablet is showing.
    exportJson() {
      const { activeMemberId, ...doc } = this.data;
      return JSON.stringify({ ...doc, settings: SettingsSchema.without(doc.settings, ['device', 'private']) }, null, 2);
    }

    exportData() {
      const blob = new Blob([this.exportJson()], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'dashboard-data.json';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

    importData(jsonString) {
      try {
        const imported = JSON.parse(jsonString);
        if (!imported || typeof imported !== 'object') {
          throw new Error('Invalid JSON format: root must be an object.');
        }
        if (!imported.members && !imported.chores && !imported.settings) {
          throw new Error('Unrecognized format: Missing essential dashboard collections.');
        }
        const settings = { ...SettingsSchema.without(imported.settings || {}, ['device', 'private']), ...SettingsSchema.pick(this.data.settings, ['device', 'private']) };
        this.data = { ...this.hydrate({ ...imported, settings }), activeMemberId: this.data.activeMemberId };
        this.save();
        return { success: true };
      } catch (err) {
        console.error('Import error:', err);
        return { success: false, error: err.message };
      }
    }

    // ---- saving and sharing ----
    // opts.stamp:false / opts.push:false for loads that must not look like a fresh local edit.
    save({ stamp = true, push = true } = {}) {
      if (stamp) this.data.updatedAt = this.now();
      this.local.set(STORAGE_KEY, JSON.stringify(this.data));
      if (push) this.schedulePush();
      this.listeners.forEach(fn => fn(this.data));
    }

    // Choosing which member to show is this tablet's own business: saved here, never stamped or shared.
    setActiveMember(memberId) {
      this.data.activeMemberId = memberId;
      this.save({ stamp: false, push: false });
    }

    /* The whole household document lives in Home Assistant's per-user storage, so every tablet using the same
       account shares it and it survives cleared browsers. Last write wins on `updatedAt`. */
    schedulePush() {
      if (!this.remote.ready()) return;
      clearTimeout(this.pushTimer);
      this.pushTimer = setTimeout(() => { this.pushTimer = null; this.pushRemote(); }, this.pushDelay);
    }

    // Tokens stay on their tablet, and so does the member it is showing.
    sharedDocument() {
      const { activeMemberId, ...doc } = this.data;
      return { ...doc, settings: SettingsSchema.without(doc.settings, ['device']) };
    }

    async pushRemote() {
      if (!this.remote.ready()) return;
      try {
        await this.remote.set(this.sharedDocument());
      } catch (e) {
        console.warn('HA state push failed:', e);
      }
    }

    // Adopt the shared copy if newer; push ours if there is none or ours is newer.
    async syncRemote() {
      if (!this.remote.ready() || this.pushTimer) return; // a pending local edit wins; it pushes itself
      try {
        const remote = await this.remote.get();
        const mine = this.data.updatedAt || 0;
        if (remote && (remote.updatedAt || 0) > mine) {
          const own = SettingsSchema.pick(this.data.settings, ['device']);
          const view = this.data.activeMemberId;
          this.data = this.hydrate(remote);
          Object.entries(own).forEach(([key, value]) => { if (value !== undefined && value !== '') this.data.settings[key] = value; });
          this.data.activeMemberId = view;
          this.data.updatedAt = remote.updatedAt;
          this.save({ stamp: false, push: false });
        } else if (!remote || mine > (remote.updatedAt || 0)) {
          await this.pushRemote();
        }
      } catch (e) {
        console.warn('HA state sync failed:', e);
      }
    }
  }

  // This tablet's storage; a full or blocked store only costs persistence.
  const browserStorage = {
    get(key) { try { return localStorage.getItem(key); } catch (_) { return null; } },
    set(key, value) { try { localStorage.setItem(key, value); } catch (e) { console.error('Error saving state:', e); } }
  };

// Finds Home Assistant document across same-origin parent/top frame boundaries.
  const getHaDocument = () => {
    if (typeof window === 'undefined') return null;
    try {
      if (window.parent && window.parent !== window && window.parent.document && window.parent.document.querySelector('home-assistant')) {
        return window.parent.document;
      }
    } catch (_) {}
    try {
      if (window.top && window.top !== window && window.top.document && window.top.document.querySelector('home-assistant')) {
        return window.top.document;
      }
    } catch (_) {}
    try {
      if (typeof document !== 'undefined' && document.querySelector('home-assistant')) {
        return document;
      }
    } catch (_) {}
    return null;
  };

  // Kiosk mode is the WallPanel integration (https://github.com/j-a-n/lovelace-wallpanel) switched on per device:
  // it reads wp_* URL parameters over the dashboard's own wallpanel: YAML, so the page URL is the toggle.
  const KIOSK_PARAMS = { wp_enabled: 'true', wp_hide_toolbar: 'true', wp_hide_sidebar: 'true', wp_idle_time: '0' };

  const isKioskEscape = (haDoc) => {
    try {
      const searches = [typeof window !== 'undefined' && window.location && window.location.search, haDoc?.defaultView?.location?.search];
      return searches.some(search => /[?&](disable_kiosk|disable_km)(=[^&]*)?(&|$)/i.test(search || '') || /[?&]kiosk=(0|false|off)(&|$)/i.test(search || ''));
    } catch (_) {
      return false;
    }
  };

  // The query string the page should have with kiosk on or off, or null when it already does.
  const kioskSearch = (search, enable) => {
    const params = new URLSearchParams(search);
    const on = Object.entries(KIOSK_PARAMS).every(([k, v]) => params.get(k) === v);
    const any = Object.keys(KIOSK_PARAMS).some(k => params.has(k));
    if (enable ? on : !any) return null;
    Object.keys(KIOSK_PARAMS).forEach(k => params.delete(k));
    if (enable) Object.entries(KIOSK_PARAMS).forEach(([k, v]) => params.set(k, v));
    const query = params.toString();
    return query ? `?${query}` : '';
  };

  // Reloads the Home Assistant page with kiosk on or off. Does nothing outside Home Assistant or when already right.
  const setHaKioskMode = (enable, haDocOverride = null) => {
    const haDoc = haDocOverride || getHaDocument();
    const loc = haDoc?.defaultView?.location;
    if (!loc) return;
    const next = kioskSearch(loc.search, !!enable && !isKioskEscape(haDoc));
    if (next !== null) loc.replace(loc.pathname + next + (loc.hash || ''));
  };

  // The dashboard's iframe can end up taller than what Home Assistant shows (its header, space a hidden toolbar leaves
  // behind, 100vh on a tablet), which pushes the bottom of the app off screen. Keep its bottom edge on the screen's.
  const fitToHaViewport = (haDoc = getHaDocument()) => {
    try {
      const frame = window.frameElement;
      const view = haDoc?.defaultView;
      if (!frame || !view) return;
      const rect = frame.getBoundingClientRect();
      const height = Math.max(240, Math.floor(view.innerHeight - rect.top));
      if (Math.abs(rect.height - height) < 2) return;
      frame.style.setProperty('height', `${height}px`, 'important');
      frame.style.setProperty('min-height', '0', 'important');
    } catch (_) {}
  };

  const watchHaViewport = () => {
    if (!getHaDocument()) return;
    fitToHaViewport();
    [1000, 3000, 8000].forEach(ms => setTimeout(fitToHaViewport, ms)); // WallPanel hides the toolbar a moment after load
    try { window.parent.addEventListener('resize', () => fitToHaViewport()); } catch (_) {}
    // Home Assistant can also move the frame without a window resize: its container resizes then.
    try {
      const container = window.frameElement?.parentElement;
      if (container && typeof ResizeObserver !== 'undefined') new ResizeObserver(() => fitToHaViewport()).observe(container);
    } catch (_) {}
  };

/* --------------------------------------------------------------------------
     HOME ASSISTANT SESSION & THE SHARED DOCUMENT
     Whether we run inside HA (reuse its login) or standalone (token), and the
     StateManager that keeps household data on this tablet and in HA user data.
     -------------------------------------------------------------------------- */
  // True when running inside the Home Assistant frontend (card iframe or same-origin panel): its session is reused.
  const inHA = () => {
    try {
      if (window.hassConnection || (window.parent && window.parent !== window && window.parent.hassConnection)) return true;
      if (getHaDocument()) return true;
      return false;
    } catch (_) { return false; } // cross-origin parent
  };
  // Base URL for plain HTTP assets (camera, photos): the HA page's own origin when embedded, else the configured URL.
  const haBase = () => {
    if (inHA()) { try { return window.parent !== window ? window.parent.location.origin : window.location.origin; } catch (_) {} }
    return stateManager.data.settings.haUrl || 'http://homeassistant.local:8123';
  };

  // The shared copy: Home Assistant's per-user storage (frontend/set_user_data).
  const haUserData = (ha, settings) => ({
    ready() {
      const h = ha();
      if (h && typeof h.isNative === 'function' && h.isNative()) return true;
      if (inHA()) return true;
      const { haUrl, haToken } = settings();
      return !!(haUrl && haToken);
    },
    async get() { const res = await ha().send({ type: 'frontend/get_user_data', key: REMOTE_KEY }); return (res && res.value) || null; },
    set(doc) { return ha().send({ type: 'frontend/set_user_data', key: REMOTE_KEY, value: doc }); }
  });

  const stateManager = new StateManager({
    local: browserStorage,
    remote: haUserData(() => haWS, () => stateManager.data.settings),
    baseline: async () => { if (window.__FD_SEED__) return window.__FD_SEED__; const res = await fetch('./data/dashboard-data.json?t=' + Date.now()); return res.ok ? res.json() : null; },
    config: window.FAMILY_DASHBOARD_CONFIG
  });
  window.stateManager = stateManager;

/* --------------------------------------------------------------------------
     2b. HOME ASSISTANT WEBSOCKET HELPER
     -------------------------------------------------------------------------- */
  class HAWebSocket {
    // connection() -> { url, token }, read each time it connects. timeout: how long a request may wait for its answer.
    constructor(connection, { timeout = 10000 } = {}) {
      this.connection = connection;
      this.timeout = timeout;
      this.ws = null;
      this.msgId = 1;
      this.pending = {}; // id -> { resolve, reject, timer }
      this.authenticated = false;
      this.connectPromise = null;
      this.subs = []; // { type, cb, id } — re-established after reconnect
      this.nativeConn = null;
    }

    isNative() {
      return !!this.nativeConn || inHA();
    }

    setNativeConnection(conn) {
      this.nativeConn = conn;
      this.authenticated = true;
    }

    async _getNative() {
      if (this.nativeConn) return this.nativeConn;
      if (typeof window !== 'undefined') {
        try {
          const hc = inHA() && (window.hassConnection || window.parent.hassConnection);
          if (hc && typeof hc.then === 'function') {
            const resolved = await hc;
            if (resolved && resolved.conn) {
              this.nativeConn = resolved.conn;
              this.authenticated = true;
              return this.nativeConn;
            }
          }
        } catch (_) {}
      }
      return null;
    }

    _wsUrl() {
      const url = this.connection().url || 'http://homeassistant.local:8123';
      return url.replace(/^http:/, 'ws:').replace(/^https:/, 'wss:') + '/api/websocket';
    }

    async connect() {
      const native = await this._getNative();
      if (native) {
        this.authenticated = true;
        return;
      }
      if (this.ws && this.ws.readyState === WebSocket.OPEN && this.authenticated) {
        return Promise.resolve();
      }
      if (this.connectPromise) return this.connectPromise;

      this.connectPromise = new Promise((resolve, reject) => {
        this.ws = new WebSocket(this._wsUrl());
        this.ws.onmessage = (e) => {
          const msg = JSON.parse(e.data);
          if (msg.type === 'auth_required') {
            this.ws?.send(JSON.stringify({ type: 'auth', access_token: this.connection().token }));
          } else if (msg.type === 'auth_ok') {
            this.authenticated = true;
            this.connectPromise = null;
            resolve();
            this.subs.forEach(sub => this._subscribe(sub));
          } else if (msg.type === 'auth_invalid') {
            this.connectPromise = null;
            reject(new Error('HA token invalid'));
          } else if (msg.type === 'event') {
            this.subs.find(sub => sub.id === msg.id)?.cb(msg.event);
          } else if (msg.id && this.pending[msg.id]) {
            const request = this.pending[msg.id];
            delete this.pending[msg.id];
            clearTimeout(request.timer);
            if (msg.success) request.resolve(msg.result); else request.reject(new Error(msg.error?.message));
          }
        };
        this.ws.onerror = () => { this.connectPromise = null; reject(new Error('WS error')); };
        this.ws.onclose = () => {
          this.authenticated = false; this.ws = null; this.connectPromise = null;
          reject(new Error('Home Assistant connection closed')); // no effect once connected
          Object.values(this.pending).forEach((request) => { clearTimeout(request.timer); request.reject(new Error('Home Assistant connection closed')); });
          this.pending = {};
          if (this.subs.length) setTimeout(() => this.connect().catch(() => {}), 5000);
        };
      });
      return this.connectPromise;
    }

    // Live event stream (e.g. 'state_changed'); survives reconnects.
    subscribe(eventType, cb) {
      this._getNative().then((native) => {
        if (native) {
          if (typeof native.subscribeEvents === 'function') {
            return native.subscribeEvents(cb, eventType);
          }
          if (typeof native.subscribeMessage === 'function') {
            return native.subscribeMessage(cb, { type: 'subscribe_events', event_type: eventType });
          }
        }
        const sub = { type: eventType, cb, id: null };
        this.subs.push(sub);
        this.connect()
          // Already-open socket: auth_ok won't fire again, so register this sub now (id is set if auth_ok got there first).
          .then(() => { if (sub.id === null) this._subscribe(sub); })
          .catch(() => { setTimeout(() => this.connect().catch(() => {}), 5000); });
      });
    }

    _subscribe(sub) {
      sub.id = this.msgId++;
      this.ws.send(JSON.stringify({ id: sub.id, type: 'subscribe_events', event_type: sub.type }));
    }

    async send(payload, timeout = this.timeout) {
      const native = await this._getNative();
      if (native) {
        if (typeof native.sendMessagePromise === 'function') {
          return native.sendMessagePromise(payload);
        }
      }
      await this.connect();
      const id = this.msgId++;
      payload.id = id;
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => { delete this.pending[id]; reject(new Error('Home Assistant did not answer')); }, timeout);
        this.pending[id] = { resolve, reject, timer };
        this.ws.send(JSON.stringify(payload));
      });
    }

    async getEntityState(entityId) {
      const states = await this.send({ type: 'get_states' });
      return Array.isArray(states) ? states.find(s => s.entity_id === entityId) : null;
    }

    async updateEntity(entityId) {
      await this.send({
        type: 'call_service', domain: 'homeassistant', service: 'update_entity',
        service_data: { entity_id: entityId }
      });
    }

    async getTodoItems(entityId) {
      const result = await this.send({ type: 'todo/item/list', entity_id: entityId });
      return (result?.items || []).map(item => ({
        id: item.uid,
        name: item.summary,
        bought: item.status === 'completed'
      }));
    }

    async addTodoItem(entityId, name) {
      await this.send({ type: 'call_service', domain: 'todo', service: 'add_item',
        service_data: { entity_id: entityId, item: name } });
    }

    async updateTodoItem(entityId, uid, completed) {
      await this.send({ type: 'call_service', domain: 'todo', service: 'update_item',
        service_data: { entity_id: entityId, item: uid, status: completed ? 'completed' : 'needs_action' } });
    }

    async updateTodoItemName(entityId, uid, newName) {
      await this.send({ type: 'call_service', domain: 'todo', service: 'update_item',
        service_data: { entity_id: entityId, item: uid, rename: newName } });
    }

    async removeTodoItem(entityId, uid) {
      await this.send({ type: 'call_service', domain: 'todo', service: 'remove_item',
        service_data: { entity_id: entityId, item: uid } });
    }

    async getCalendarEvents(entityIds, startIso, endIso) {
      const ids = Array.isArray(entityIds) ? entityIds : [entityIds];
      // Several Google calendars over three months can be slow to answer, so this one waits three times as long.
      const result = await this.send({
        type: 'call_service',
        domain: 'calendar',
        service: 'get_events',
        service_data: { entity_id: ids, start_date_time: startIso, end_date_time: endIso },
        return_response: true
      }, this.timeout * 3);
      // result.response is keyed by entity_id, each has an `events` array
      // Events use flat string start/end rather than {dateTime:...} objects
      return result?.response || {};
    }
  }

  const haWS = new HAWebSocket(() => ({ url: stateManager.data.settings.haUrl, token: stateManager.data.settings.haToken }));
  window.haWS = haWS;

/* --------------------------------------------------------------------------
     2c. PARENT TASKS
     -------------------------------------------------------------------------- */
  const PRIORITY_LABEL = { high: 'High', medium: 'Medium', low: 'Low' };
  const CATEGORY_LABEL = { general: 'General', home: 'Home', vehicle: 'Vehicle', finance: 'Finance', errands: 'Errands', work: 'Work', health: 'Health', family: 'Family' };
  const PRIORITY_RANK = { high: 0, medium: 1, low: 2 };

  // Parent tasks (a task may repeat): add, edit, tick, remove with undo, the board's bucket / group / drop rules,
  // and the projection onto the calendar. Views draw; this decides.
  class ParentTasks {
    constructor(store, now = () => new Date()) {
      this.store = store;
      this.now = now;
    }

    get all() { return this.store.data.parentTasks || (this.store.data.parentTasks = []); }
    today() { return toLocalYMD(this.now()); }
    find(id) { return this.all.find(t => t.id === id); }
    mine(memberId) { return this.all.filter(t => t.memberId === memberId || t.memberId === 'shared'); }

    static repeats(t) { return !!t.frequency && t.frequency !== 'none'; }
    static daysUntil(ymd, todayYMD) { return Math.round((new Date(ymd) - new Date(todayYMD)) / 86400000); }
    static order(a, b) {
      return (a.dueDate || '9999').localeCompare(b.dueDate || '9999') || (PRIORITY_RANK[a.priority || 'medium'] - PRIORITY_RANK[b.priority || 'medium']);
    }

    // Next due date of a repeating task, counted from its due date (or from today when that is past).
    static nextDue(frequency, dueYMD, now = new Date()) {
      const d = dueYMD ? new Date(dueYMD + 'T12:00:00') : new Date(now);
      const from = d < now ? new Date(now) : d;
      if (frequency === 'daily') from.setDate(from.getDate() + 1);
      else if (frequency === 'weekly') from.setDate(from.getDate() + 7);
      else if (frequency === 'monthly') from.setMonth(from.getMonth() + 1);
      else if (frequency === 'annually') from.setFullYear(from.getFullYear() + 1);
      return toLocalYMD(from);
    }

    add(fields) {
      let id = 'pt-' + Date.now();
      for (let n = 1; this.find(id); n++) id = `pt-${Date.now()}-${n}`;
      const task = { ...fields, id, completed: false };
      this.all.unshift(task);
      this.store.save();
      return task;
    }

    update(id, fields) {
      const t = this.find(id);
      if (!t) return null;
      Object.assign(t, fields);
      this.store.save();
      return t;
    }

    // Repeating tasks advance to their next due date; one-off tasks toggle done. undo() puts the task back as it was.
    toggle(id) {
      const t = this.find(id);
      if (!t) return null;
      const before = { dueDate: t.dueDate, lastCompletedDate: t.lastCompletedDate, completed: t.completed };
      if (ParentTasks.repeats(t)) {
        t.lastCompletedDate = this.today();
        t.dueDate = ParentTasks.nextDue(t.frequency, t.dueDate, this.now());
      } else {
        t.completed = !t.completed;
      }
      this.store.save();
      return { task: t, undo: () => this.update(id, before) };
    }

    // Returns an undo, or null when there was no such task.
    remove(id) { return this.withdraw(new Set([id])); }

    // Removes this parent's finished one-off tasks (and shared ones). undo is null when nothing was removed.
    clearDone(memberId) {
      const ids = new Set(this.mine(memberId).filter(t => !ParentTasks.repeats(t) && t.completed).map(t => t.id));
      return { count: ids.size, undo: this.withdraw(ids) };
    }

    // Removes tasks by id; the undo puts each back after the task that preceded it (or at its old position).
    withdraw(ids) {
      const before = this.all.map(t => t.id);
      const gone = before.map((id, index) => ({ id, index })).filter(({ id }) => ids.has(id));
      if (!gone.length) return null;
      const removed = new Map(this.all.filter(t => ids.has(t.id)).map(t => [t.id, t]));
      this.store.data.parentTasks = this.all.filter(t => !ids.has(t.id));
      this.store.save();
      return () => {
        for (const { id, index } of gone) {
          const list = this.all;
          const after = list.findIndex(t => t.id === before[index - 1]);
          list.splice(after >= 0 ? after + 1 : Math.min(index, list.length), 0, removed.get(id));
        }
        this.store.save();
      };
    }

    // Each grouping of the board: its columns, how a task maps to one, what dropping on a column does, and which tag
    // would be redundant. Time buckets: this week runs through Saturday, soon is the next 30 days, the rest is later.
    groups(open, today) {
      const plusDays = (n) => { const d = this.now(); d.setDate(d.getDate() + n); return toLocalYMD(d); };
      const weekEnd = (() => { const d = this.now(); d.setDate(d.getDate() + 6 - d.getDay()); return toLocalYMD(d); })();
      const soonEnd = plusDays(30);
      const bucket = (t) => t.dueDate && t.dueDate < today ? 'overdue' : !t.dueDate ? 'later' : t.dueDate <= weekEnd ? 'week' : t.dueDate <= soonEnd ? 'soon' : 'later';
      return {
        priority: { key: 'priority', label: 'Priority', cols: [['high', 'High'], ['medium', 'Medium'], ['low', 'Low']], of: t => t.priority || 'medium', set: (t, k) => { t.priority = k; }, hide: 'priority' },
        theme: { key: 'theme', label: 'Theme', cols: Object.entries(CATEGORY_LABEL).filter(([k]) => open.some(t => (t.category || 'general') === k)), of: t => t.category || 'general', set: (t, k) => { t.category = k; }, hide: 'category' },
        time: {
          key: 'time', label: 'Time', cols: [...(open.some(t => bucket(t) === 'overdue') ? [['overdue', 'Overdue']] : []), ['week', 'This week'], ['soon', 'Soon'], ['later', 'Later']],
          of: bucket, noDrop: ['overdue'], hide: 'due',
          set: (t, k) => { if (bucket(t) !== k) t.dueDate = { week: weekEnd, soon: plusDays(14), later: '' }[k]; }
        }
      };
    }

    // What the parent page shows for one parent: the board columns for a grouping, finished and repeating tasks,
    // and the month calendar's data (tasks by due date, plus the open ones without a date).
    board(memberId, groupKey) {
      const mine = this.mine(memberId);
      const oneOff = mine.filter(t => !ParentTasks.repeats(t));
      const open = oneOff.filter(t => !t.completed);
      const groups = this.groups(open, this.today());
      const g = groups[groupKey] || groups.priority;
      const scheduled = {};
      mine.filter(t => t.dueDate && !t.completed).sort(ParentTasks.order).forEach(t => { (scheduled[t.dueDate] = scheduled[t.dueDate] || []).push(t); });
      return {
        open,
        done: oneOff.filter(t => t.completed).sort(ParentTasks.order),
        recurring: mine.filter(ParentTasks.repeats).sort((a, b) => (a.dueDate || '9999').localeCompare(b.dueDate || '9999')),
        group: { key: g.key, label: g.label, hide: g.hide },
        groups: Object.values(groups).map(({ key, label }) => ({ key, label })),
        columns: g.cols.map(([key, label]) => ({ key, label, droppable: !(g.noDrop || []).includes(key), tasks: open.filter(t => g.of(t) === key).sort(ParentTasks.order) })),
        scheduled,
        undated: open.filter(t => !t.dueDate).sort(ParentTasks.order)
      };
    }

    // Dropping a card on a board column sets what the board is grouped by; "done" completes it. False when refused.
    dropOnColumn(id, groupKey, colKey) {
      const t = this.find(id);
      const groups = this.groups([], this.today());
      const g = groups[groupKey] || groups.priority;
      if (!t || (g.noDrop || []).includes(colKey)) return false;
      if (colKey === 'done') t.completed = true;
      else { t.completed = false; g.set(t, colKey); }
      this.store.save();
      return true;
    }

    schedule(id, ymd) { return !!this.update(id, { dueDate: ymd }); }

    // Tasks marked "show on calendar" as all-day events; a finished one-off task drops off.
    asCalendarEvents() {
      return this.all.filter(t => t.showOnCalendar && t.dueDate && (!t.completed || ParentTasks.repeats(t))).map(t => ({
        id: 'task-' + t.id, title: t.title, memberId: t.memberId, category: 'family', date: t.dueDate, time: 'All Day',
        frequency: t.frequency, location: ParentTasks.repeats(t) ? `Repeats ${t.frequency}` : '', notes: t.notes || ''
      }));
    }
  }

  const parentTasks = new ParentTasks(stateManager);

/* --------------------------------------------------------------------------
     2d. MISSION LEDGER (chores, routines, wildcards, stars, prizes)
     -------------------------------------------------------------------------- */
  // The rules of the Mission board: who earns what and when, how a star balance changes and is logged, what a prize
  // costs, and when missions reset. Views draw and ask; this decides.
  class MissionLedger {
    constructor(store, { now = () => new Date(), addTask = () => {}, onPrize = () => {} } = {}) {
      this.store = store;
      this.now = now;
      this.addTask = addTask;   // files a to-do for the parents when a prize is bought
      this.onPrize = onPrize;   // told when a prize is bought, to celebrate
      this.seq = 0;
    }

    get d() { return this.store.data; }
    today() { return toLocalYMD(this.now()); }
    member(id) { return this.d.members.find(m => m.id === id); }
    kids() { return this.d.members.filter(m => m.role === 'kid'); }
    newId(prefix) { return `${prefix}-${this.now().getTime()}-${this.seq++}`; }

    // Prize store. First use seeds it from the old per-kid goals so nothing is lost.
    init() {
      if (this.d.rewardsSeeded) return;
      this.d.rewardsSeeded = true;
      const rewards = (this.d.rewards ||= []);
      const seen = new Set(rewards.map(r => `${r.title}|${r.cost}`));
      this.kids().filter(m => m.targetReward && m.targetStars).forEach(m => {
        const key = `${m.targetReward}|${m.targetStars}`;
        if (!seen.has(key)) { seen.add(key); rewards.push({ id: this.newId('rw'), title: m.targetReward, cost: m.targetStars }); }
      });
      this.store.save();
    }

    // ---- reading ----
    find(id) {
      const chore = this.d.chores.find(c => c.id === id);
      if (chore) return { item: chore, list: this.d.chores, kind: 'chore' };
      const routine = (this.d.routines || []).find(r => r.id === id);
      return routine ? { item: routine, list: this.d.routines, kind: 'routine' } : null;
    }

    // One kid's routines and chores, grouped for display. Routines are copies flagged `_routine`.
    itemsFor(kidId) {
      const routines = (this.d.routines || []).filter(r => r.memberId === kidId).map(r => ({ ...r, _routine: true }));
      const chores = (this.d.chores || []).filter(c => c.memberId === kidId);
      const byRoutine = { morning: [], afterschool: [], bedtime: [] };
      routines.forEach(r => byRoutine[r.routineType]?.push(r));
      chores.filter(c => c.routineType && c.routineType !== 'general').forEach(c => byRoutine[c.routineType]?.push(c));
      const isDaily = c => !c.frequency || c.frequency === 'daily';
      return {
        byRoutine,
        daily: chores.filter(c => (!c.routineType || c.routineType === 'general') && isDaily(c)),
        weekly: chores.filter(c => c.frequency === 'weekly'),
        monthly: chores.filter(c => c.frequency === 'monthly')
      };
    }

    wildcards() { return (this.d.chores || []).filter(c => c.memberId === 'either'); }
    activity(memberId) { return this.d.kidAchievements?.[memberId]?.activityLog || []; }
    rewards() { return (this.d.rewards || []).slice().sort((a, b) => a.cost - b.cost); }

    // What the star meter aims at: the cheapest prize not yet affordable (else the priciest one).
    nextPrize(member) {
      const rewards = this.rewards();
      return rewards.find(r => r.cost > member.stars) || rewards[rewards.length - 1] || null;
    }

    starPct(member) {
      const prize = this.nextPrize(member);
      return prize ? Math.min(100, Math.round((member.stars / prize.cost) * 100)) : 0;
    }

    // ---- earning ----
    // Ticks a routine (toggles; one star per routine per day) or a chore (completes once). Returns the stars earned.
    tick(id) {
      const found = this.find(id);
      if (!found) return null;
      const { item, kind } = found;
      let stars = 0;
      if (kind === 'routine') {
        item.completedToday = !item.completedToday;
        if (item.completedToday && item.starDay !== this.today()) {
          item.starDay = this.today();
          stars = this.award(item.memberId, 1, item.title);
        }
      } else if (item.memberId === 'either' || item.status === 'completed') {
        return null;   // wildcards are claimed; a finished chore stays finished
      } else {
        item.status = 'completed';
        stars = this.award(item.memberId, item.points, item.title);
      }
      this.store.save();
      return { item, stars };
    }

    claim(choreId, kidId) {
      const chore = this.d.chores.find(c => c.id === choreId && c.memberId === 'either');
      if (!chore || chore.status === 'completed') return null;
      chore.status = 'completed';
      chore.completedBy = kidId;
      const member = this.member(kidId);
      if (member) this.award(kidId, chore.points, `${chore.title} (Wildcard Bonus)`);
      this.store.save();
      return { chore, member };
    }

    award(memberId, points, title) {
      const member = this.member(memberId);
      if (!member) return 0;
      member.stars += points;
      this.log(memberId, title, points);
      return points;
    }

    log(memberId, title, points, kind = 'stars') {
      const entry = ((this.d.kidAchievements ||= {})[memberId] ||= {});
      const list = (entry.activityLog ||= []);
      const at = this.now();
      list.unshift({
        id: `act-${at.getTime()}-${this.seq++}`, title, points, kind, at: at.getTime(),
        time: at.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) + ' Today'
      });
      if (list.length > 20) list.pop();
    }

    // A parent changes a balance by hand; it never goes below zero. It is not an entry in the activity log (it never was).
    adjustStars(memberId, delta) {
      const member = this.member(memberId);
      if (!member) return null;
      member.stars = Math.max(0, member.stars + delta);
      this.store.save();
      return member.stars;
    }

    // ---- managing missions ----
    // kid: a kid id, 'both' (one independent chore each) or 'either' (a wildcard).
    add({ title, kid, points = 3, routineType = 'general', frequency = 'daily' }) {
      const owners = kid === 'both' ? this.kids().map(k => k.id) : [kid];
      const made = owners.map(memberId => ({ id: this.newId('ch'), title, memberId, points, status: 'pending', routineType, frequency }));
      this.d.chores.push(...made);
      this.store.save();
      return made;
    }

    edit(id, fields) {
      const found = this.find(id);
      if (!found) return null;
      const allowed = found.kind === 'routine' ? ['title', 'memberId', 'routineType'] : ['title', 'memberId', 'points', 'routineType', 'frequency'];
      allowed.filter(k => k in fields).forEach(k => { found.item[k] = fields[k]; });
      this.store.save();
      return found.item;
    }

    remove(id) {
      const found = this.find(id);
      if (!found) return null;
      found.list.splice(found.list.indexOf(found.item), 1);
      this.store.save();
      return found.item;
    }

    // Drag and drop: to a kid's routine section ({ kid, routine }) or weekly / monthly section ({ kid, freq }),
    // placed before another item when given.
    move(id, { kid, routine, freq, beforeId } = {}) {
      const found = this.find(id);
      if (!found || (freq && found.kind === 'routine')) return false;   // routines are daily by nature
      const { item, list, kind } = found;
      item.memberId = kid;
      if (routine) {
        item.routineType = routine;
        if (kind === 'chore' && item.frequency && item.frequency !== 'daily') item.frequency = 'daily';
      }
      if (freq) { item.frequency = freq; item.routineType = 'general'; }
      list.splice(list.indexOf(item), 1);
      const before = beforeId && list.find(c => c.id === beforeId);
      if (before) list.splice(list.indexOf(before), 0, item); else list.push(item);
      this.store.save();
      return true;
    }

    reset(id) {
      const chore = this.d.chores.find(c => c.id === id);
      if (!chore) return false;
      chore.status = 'pending';
      chore.completedBy = null;
      this.store.save();
      return true;
    }

    // Routines reset daily; chores reset by `frequency` (daily default, weekly from Sunday, monthly).
    resetPeriodic() {
      const d = this.now();
      const day = toLocalYMD(d);
      const last = this.d.lastReset || {};
      if (last.day === day) return false;
      const week = toLocalYMD(new Date(d.getFullYear(), d.getMonth(), d.getDate() - d.getDay()));
      const month = day.slice(0, 7);
      const due = { daily: true, weekly: last.week !== week, monthly: last.month !== month };
      (this.d.routines || []).forEach(r => { r.completedToday = false; });
      (this.d.chores || []).forEach(c => {
        if (c.status === 'completed' && due[c.frequency || 'daily']) { c.status = 'pending'; c.completedBy = null; }
      });
      this.d.lastReset = { day, week, month };
      this.store.save();
      return true;
    }

    // ---- the prize store ----
    // Spends a kid's stars on a prize; the parents get a to-do to hand it over. Null when it cannot be bought.
    buy(memberId, rewardId) {
      const member = this.member(memberId);
      const reward = (this.d.rewards || []).find(r => r.id === rewardId);
      if (!member || !reward || member.stars < reward.cost) return null;
      member.stars -= reward.cost;
      this.log(memberId, `Bought: ${reward.title}`, -reward.cost, 'spend');
      this.addTask({ title: `Give ${member.name}: ${reward.title}`, memberId: 'shared', priority: 'high', category: 'family', dueDate: this.today() });
      this.store.save();
      this.onPrize({ memberId, title: reward.title, cost: reward.cost });
      return reward;
    }

    addReward({ title, cost }) {
      title = String(title || '').trim();
      cost = parseInt(cost, 10);
      if (!title || !(cost > 0)) return null;
      const reward = { id: this.newId('rw'), title, cost };
      (this.d.rewards ||= []).push(reward);
      this.store.save();
      return reward;
    }

    // Blank titles and non-numbers are ignored; a prize costs at least one star.
    editReward(id, { title, cost } = {}) {
      const reward = (this.d.rewards || []).find(r => r.id === id);
      if (!reward) return null;
      if (title !== undefined) reward.title = String(title).trim() || reward.title;
      if (cost !== undefined) reward.cost = Math.max(1, parseInt(cost, 10) || reward.cost);
      this.store.save();
      return reward;
    }

    removeReward(id) {
      this.d.rewards = (this.d.rewards || []).filter(r => r.id !== id);
      this.store.save();
    }
  }

  const ledger = new MissionLedger(stateManager, { addTask: (task) => parentTasks.add(task) });

/* --------------------------------------------------------------------------
     2e. HOME ASSISTANT LISTS
     -------------------------------------------------------------------------- */
  // The shopping list, the meal ideas and the dinner plan are Home Assistant to-do entities. HaList is one such list
  // with a local copy to fall back on; items are { id, name, bought } and callers never see which store answered.
  // With an entity configured and Home Assistant reachable, the entity is the truth. Otherwise the local copy is:
  // changes made then stay on this device and are replaced by the entity's list at the next load.
  class HaList {
    constructor({ ha, entity, local, addAt = 'end', onError = () => {} }) {
      this.ha = ha;            // { getTodoItems, addTodoItem, updateTodoItem, updateTodoItemName, removeTodoItem }
      this.entity = entity;    // () => entity id ('' when none)
      this.local = local;      // { read() -> items, write(items, mirror) }; mirror: the copy of the entity's list
      this.addAt = addAt;      // where a new local item goes: 'end' or 'start'
      this.onError = onError;  // (error, what) when Home Assistant could not be reached
      this.listeners = [];
      this.seq = 0;
      this.fromHa = null;      // the entity's list as Home Assistant last answered it
      this.unsent = false;     // a change is held in the local copy because Home Assistant did not take it
      this.failed = false;     // the last read of the entity's list failed
    }

    // The entity's list while Home Assistant answers, otherwise the local copy. The copy is read fresh each time:
    // a sync can replace the household data underneath it.
    get items() { return (this.entity() && this.fromHa) || this.local.read(); }

    get configured() { return !!this.entity(); }

    // How far the list can be trusted. 'connected' means Home Assistant answered, not that Google Keep is in step:
    // Home Assistant keeps serving its copy of the list while the Keep integration is failing.
    get status() {
      if (!this.entity()) return 'local';
      if (this.unsent) return 'unsent';
      if (this.fromHa) return 'connected';
      return this.failed ? 'offline' : 'connecting';
    }

    subscribe(fn) {
      this.listeners.push(fn);
      return () => { this.listeners = this.listeners.filter(l => l !== fn); };
    }

    emit() { this.listeners.forEach(fn => fn(this.items)); }

    // Fetches the entity's list. False when there is no entity or it cannot be reached.
    async refresh() {
      const entity = this.entity();
      if (!entity) return false;
      try {
        this.fromHa = await this.ha.getTodoItems(entity);
        this.unsent = false;
        this.failed = false;
        this.local.write(this.fromHa, true);
        this.emit();
        return true;
      } catch (e) {
        this.fromHa = null;
        this.failed = true;
        this.onError(e, 'load');
        return false;
      }
    }

    async load() {
      if (!(await this.refresh())) this.emit();
      return this.items;
    }

    // The periodic re-read that shows changes made elsewhere. It waits while a change could not be sent, or the
    // re-read would wipe that change within the minute; a later change that gets through, or a reload, resumes it.
    async poll() {
      if (this.unsent) return false;
      const fresh = await this.refresh();
      if (!fresh) this.emit(); // so what is showing can say the connection was lost
      return fresh;
    }

    // Returns the new item, or null for a blank name.
    async add(name) {
      name = String(name || '').trim();
      if (!name) return null;
      const known = new Set(this.items.map(i => i.id));
      let created = null;
      await this.change('add', (entity) => this.ha.addTodoItem(entity, name), (items) => {
        created = { id: `li-${Date.now()}-${this.seq++}`, name, bought: false };
        return this.addAt === 'start' ? [created, ...items] : [...items, created];
      });
      return created || this.items.find(i => !known.has(i.id) && i.name === name) || this.items.find(i => i.name === name) || null;
    }

    async rename(id, name) {
      name = String(name || '').trim();
      if (!name || !this.items.some(i => i.id === id)) return;
      await this.change('rename', (entity) => this.ha.updateTodoItemName(entity, id, name), (items) => items.map(i => i.id === id ? { ...i, name } : i));
    }

    async toggle(id) {
      const item = this.items.find(i => i.id === id);
      if (!item) return;
      await this.change('toggle', (entity) => this.ha.updateTodoItem(entity, id, !item.bought), (items) => items.map(i => i.id === id ? { ...i, bought: !i.bought } : i));
    }

    async remove(id) {
      if (!this.items.some(i => i.id === id)) return;
      await this.change('remove', (entity) => this.ha.removeTodoItem(entity, id), (items) => items.filter(i => i.id !== id));
    }

    // Sends a change to Home Assistant and shows the list it answers with. With no entity, or when Home Assistant
    // fails, the change is applied to the local copy instead.
    async change(what, viaHa, viaLocal) {
      const entity = this.entity();
      let sent = false;
      if (entity) {
        try { await viaHa(entity); sent = true; } catch (e) { this.onError(e, what); }
      }
      if (sent && await this.refresh()) return;
      this.unsent = !!entity && !sent;
      const next = viaLocal(this.items);
      this.fromHa = null;
      this.local.write(next, !!entity);
      this.emit();
    }
  }

  // The dinner plan: a list whose items read "Mon|Taco Night" (a weekday, a bar, the meal).
  class MealPlan {
    constructor(list) { this.list = list; }

    get configured() { return this.list.configured; }
    subscribe(fn) { return this.list.subscribe(fn); }
    load() { return this.list.load(); }
    entry(day) { return this.list.items.find(i => i.name.startsWith(`${day}|`)); }

    get byDay() {
      const plan = {};
      this.list.items.forEach(i => {
        const bar = i.name.indexOf('|');
        if (bar > 0) plan[i.name.slice(0, bar)] = i.name.slice(bar + 1);
      });
      return plan;
    }

    set(day, meal) {
      const entry = this.entry(day);
      return entry ? this.list.rename(entry.id, `${day}|${meal}`) : this.list.add(`${day}|${meal}`);
    }

    clear(day) {
      const entry = this.entry(day);
      return entry ? this.list.remove(entry.id) : Promise.resolve();
    }

    // The plan covers the next seven days: that weekday's meal if the date falls inside them.
    dinnerOn(date, today) {
      const ahead = ParentTasks.daysUntil(date, today);
      if (ahead < 0 || ahead > 6) return undefined;
      const [y, m, d] = date.split('-').map(Number);
      return this.byDay[['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][new Date(y, m - 1, d).getDay()]];
    }
  }

  // Where a list keeps its local copy: a collection in the household document (a Home Assistant mirror is not a
  // household change), or only in memory.
  const storeList = (store, key) => ({
    read: () => store.data[key] || [],
    write(items, mirror) {
      store.data[key] = items.map(({ id, name, bought }) => ({ id, name, bought }));
      store.save(mirror ? { stamp: false, push: false } : undefined);
    }
  });
  const memoryList = () => {
    let items = [];
    return { read: () => items, write: (next) => { items = next; } };
  };

/* --------------------------------------------------------------------------
     3. CALENDAR MODULE
     -------------------------------------------------------------------------- */
  function toLocalYMD(dateObj) {
    if (!(dateObj instanceof Date) || isNaN(dateObj.getTime())) {
      dateObj = new Date();
    }
    const y = dateObj.getFullYear();
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const d = String(dateObj.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  /* --------------------------------------------------------------------------
     3a. CALENDAR FEED
     -------------------------------------------------------------------------- */
  // Small storage for data that must stay on this device (a cache, a preference): one JSON value under one key.
  function localCache(key) {
    return {
      read() { try { return JSON.parse(localStorage.getItem(key))?.events || []; } catch (_) { return []; } },
      write(events) { try { localStorage.setItem(key, JSON.stringify({ events })); } catch (_) { /* full or private mode: next sync refills it */ } }
    };
  }

  const isHaEvent = (e) => String(e.id).startsWith('ha-');

  // Which events exist and how they are read: your own events, the Home Assistant calendars (a cache, kept out of the
  // household document) and tasks marked for the calendar. Times travel as display strings ("9:00 AM - 10:00 AM",
  // "All Day") and are parsed here, once. Views draw what this returns.
  class CalendarFeed {
    constructor({ store, tasks, cache, ha, now = () => new Date() }) {
      this.store = store;
      this.tasks = tasks;
      this.cache = cache;   // { read() -> events, write(events) }
      this.ha = ha;         // { getCalendarEvents(entityIds, fromIso, toIso) }
      this.now = now;
      this.onChange = null; // told when a sync brought events
      this.haEvents = cache.read();
      this.adoptLegacyEvents();
    }

    // Older documents carried the Home Assistant events (and some sample events) inside the household document.
    adoptLegacyEvents() {
      const events = this.store.data.events || [];
      const sample = (e) => /^evt-[1-8]$/.test(e.id);
      const legacy = events.filter(isHaEvent);
      if (!legacy.length && !events.some(sample)) return;
      if (legacy.length && !this.haEvents.length) { this.haEvents = legacy; this.cache.write(legacy); }
      this.store.data.events = events.filter(e => !isHaEvent(e) && !sample(e));
      this.store.save({ stamp: false, push: false });
    }

    stored() { return [...(this.store.data.events || []).filter(e => !isHaEvent(e)), ...this.haEvents]; }
    all() { return [...this.stored(), ...this.tasks.asCalendarEvents()]; }

    // ---- your own events ----
    // A Home Assistant event is not yours to save: it would be filtered out of stored() and the edit would vanish.
    save(event) {
      if (isHaEvent(event)) throw new Error('Events from Home Assistant calendars cannot be edited');
      const events = (this.store.data.events ||= []);
      if (!event.id) {
        let id = 'evt-' + this.now().getTime();
        for (let n = 1; events.some(e => e.id === id); n++) id = `evt-${this.now().getTime()}-${n}`;
        event = { ...event, id };
      }
      const i = events.findIndex(e => e.id === event.id);
      if (i >= 0) events[i] = event; else events.push(event);
      this.store.save();
      return event;
    }

    // A Home Assistant event is only hidden until the next sync brings it back.
    remove(id) {
      this.store.data.events = (this.store.data.events || []).filter(e => e.id !== id);
      if (this.haEvents.some(e => e.id === id)) {
        this.haEvents = this.haEvents.filter(e => e.id !== id);
        this.cache.write(this.haEvents);
      }
      this.store.save();
    }

    // ---- Home Assistant ----
    // Replaces the cached events (a month back, two months ahead). Resolves how many arrived; keeps what it had
    // when Home Assistant fails or returns nothing.
    async sync() {
      const members = this.store.data.members;
      const entityIds = members.map(m => m.haCalendarEntity).filter(Boolean);
      if (!entityIds.length) return 0;
      const from = this.now(); from.setDate(from.getDate() - 30);
      const to = this.now(); to.setDate(to.getDate() + 60);
      let results;
      try {
        results = await this.ha.getCalendarEvents(entityIds, from.toISOString(), to.toISOString());
      } catch (err) {
        console.warn('Failed syncing HA calendars via WebSocket:', err);
        return 0;
      }
      const fetched = members.filter(m => m.haCalendarEntity).flatMap(m => CalendarFeed.fromHa(m, results[m.haCalendarEntity]?.events || []));
      if (!fetched.length) return 0;
      this.haEvents = fetched;
      this.cache.write(fetched);
      this.onChange?.();
      return fetched.length;
    }

    // ---- reading ----
    // Everything on one date that this member can see (everyone, by default), with copies on several calendars merged.
    day(date, memberId = 'all') {
      let events = this.all().filter(e => e.date === date);
      if (memberId !== 'all') events = events.filter(e => e.memberId === memberId || e.memberId === 'shared');
      return CalendarFeed.merge(events);
    }

    // One member's upcoming events grouped by date: [{ date, events }]. With nothing ahead, whatever they have.
    agenda(memberId, today) {
      const mine = this.all().filter(e => e.memberId === memberId || e.memberId === 'shared');
      let upcoming = mine.filter(e => e.date >= today);
      if (!upcoming.length && mine.length) upcoming = mine;
      upcoming.sort((a, b) => a.date.localeCompare(b.date) || CalendarFeed.parseTime(a.time).startMinutes - CalendarFeed.parseTime(b.time).startMinutes);
      const days = [];
      upcoming.forEach(e => {
        let day = days[days.length - 1];
        if (!day || day.date !== e.date) days.push(day = { date: e.date, events: [] });
        day.events.push(e);
      });
      return days;
    }

    // Today's timed events that are not over yet, soonest first (the screensaver's list).
    remaining(now) {
      const nowMinutes = now.getHours() * 60 + now.getMinutes();
      return this.day(toLocalYMD(now))
        .map(e => ({ e, t: CalendarFeed.parseTime(e.time) }))
        .filter(({ t }) => !t.isAllDay && t.endMinutes > nowMinutes)
        .sort((a, b) => a.t.startMinutes - b.t.startMinutes)
        .map(({ e }) => e);
    }

    // The same event on several calendars, gathered: every attendee, and any location or notes one copy has.
    copiesOf(evt) {
      const copies = this.stored().filter(e => CalendarFeed.key(e) === CalendarFeed.key(evt));
      if (!copies.some(e => e.id === evt.id)) copies.unshift(evt);
      return {
        ...evt,
        memberIds: [...new Set(copies.map(e => e.memberId))],
        location: copies.map(e => e.location).find(l => l && l.trim()) || '',
        notes: copies.map(e => e.notes).find(n => n && n.trim()) || ''
      };
    }

    // ---- rules that need no data ----
    static key(e) { return `${(e.title || '').toLowerCase().trim()}|${e.date}|${e.time || 'allday'}`; }

    static merge(events) {
      const groups = new Map();
      for (const e of events) {
        const k = CalendarFeed.key(e);
        if (!groups.has(k)) groups.set(k, []);
        groups.get(k).push(e);
      }
      return [...groups.values()].map(group => {
        if (group.length === 1) return group[0];
        const memberIds = [...new Set(group.map(e => e.memberId))];
        return { ...group[0], memberIds, memberId: memberIds[0] };
      });
    }

    // "9:00 AM - 10:30 AM" -> minutes from midnight. No end: an hour. At least 30 minutes. Unreadable: all day.
    static parseTime(timeStr) {
      const allDay = { isAllDay: true, startMinutes: 0, endMinutes: 1440, duration: 1440 };
      if (!timeStr || /all[-\s]?day/i.test(timeStr)) return allDay;
      const minutes = (text) => {
        let str = (text || '').trim();
        const meridiem = str.match(/(am|pm)/i);
        if (meridiem) str = str.replace(/(am|pm)/i, '').trim();
        const [hh, mm] = str.split(':');
        let h = parseInt(hh, 10);
        let m = mm ? parseInt(mm, 10) : 0;
        if (isNaN(h)) return null;
        if (isNaN(m)) m = 0;
        if (meridiem && /pm/i.test(meridiem[0]) && h < 12) h += 12;
        if (meridiem && /am/i.test(meridiem[0]) && h === 12) h = 0;
        return h * 60 + m;
      };
      const [from, to] = timeStr.split(/\s*-\s*/);
      const startMinutes = minutes(from);
      if (startMinutes === null) return allDay;
      let endMinutes = to ? minutes(to) : null;
      if (endMinutes === null || endMinutes <= startMinutes) endMinutes = Math.min(1440, startMinutes + 60);
      const duration = Math.max(30, endMinutes - startMinutes);
      return { isAllDay: false, startMinutes, endMinutes: startMinutes + duration, duration };
    }

    // "09:00 AM - 10:30 AM" -> "9:00 AM". All-day and unreadable times have no start to show.
    static startTime(timeStr) {
      if (CalendarFeed.parseTime(timeStr).isAllDay) return '';
      return timeStr.split(/\s*-\s*/)[0].trim().replace(/^0/, '');
    }

    // The time field of the event dialog ("14:05") <-> the stored display time ("2:05 PM").
    static to24(timeStr) {
      if (/^\d{2}:\d{2}$/.test((timeStr || '').trim())) return timeStr.trim();
      const t = CalendarFeed.parseTime(timeStr);
      if (t.isAllDay) return '09:00';
      return `${String(Math.floor(t.startMinutes / 60)).padStart(2, '0')}:${String(t.startMinutes % 60).padStart(2, '0')}`;
    }

    // The event dialog's fields <-> the stored display time.
    static timeFields(timeStr) {
      if (CalendarFeed.parseTime(timeStr).isAllDay) return { allDay: true, start: '09:00', end: '' };
      const [from, to] = timeStr.split(/\s*-\s*/);
      return { allDay: false, start: CalendarFeed.to24(from), end: to ? CalendarFeed.to24(to) : '' };
    }

    static timeFromFields({ allDay, start, end }) {
      if (allDay) return 'All Day';
      return end ? `${CalendarFeed.from24(start)} - ${CalendarFeed.from24(end)}` : CalendarFeed.from24(start);
    }

    static from24(time24) {
      if (!time24) return '09:00 AM';
      const [hh, mm] = time24.split(':');
      const h = parseInt(hh, 10);
      if (isNaN(h)) return time24;
      return `${h % 12 || 12}:${mm || '00'} ${h >= 12 ? 'PM' : 'AM'}`;
    }

    // Lays one day's events out for a time grid: overlapping events share the width in columns.
    static layout(events, hourHeight) {
      const allDay = [];
      const timed = [];
      for (const e of events) {
        const t = CalendarFeed.parseTime(e.time);
        if (t.isAllDay) allDay.push(e); else timed.push({ ...e, _times: t });
      }
      timed.sort((a, b) => a._times.startMinutes - b._times.startMinutes || b._times.duration - a._times.duration);

      const clusters = [];
      let cluster = [];
      let clusterEnd = -1;
      for (const item of timed) {
        if (cluster.length && item._times.startMinutes >= clusterEnd) { clusters.push(cluster); cluster = []; }
        cluster.push(item);
        clusterEnd = cluster.length === 1 ? item._times.endMinutes : Math.max(clusterEnd, item._times.endMinutes);
      }
      if (cluster.length) clusters.push(cluster);

      const placed = [];
      for (const group of clusters) {
        const columns = [];
        for (const item of group) {
          let col = columns.findIndex(c => c[c.length - 1]._times.endMinutes <= item._times.startMinutes);
          if (col < 0) { col = columns.length; columns.push([]); }
          columns[col].push(item);
          item._col = col;
        }
        for (const item of group) {
          const widthPct = 100 / columns.length;
          placed.push({
            event: item,
            topPx: (item._times.startMinutes / 60) * hourHeight,
            heightPx: Math.max(26, (item._times.duration / 60) * hourHeight) - 2,
            leftPct: item._col * widthPct,
            widthPct
          });
        }
      }
      return { timed: placed, allDay };
    }

    // Home Assistant events -> dashboard events for one member.
    static fromHa(member, haEvents) {
      return haEvents.map(he => {
        const { dateStr, timeStr } = CalendarFeed.dateAndTime(he.start, he.end);
        const key = he.uid ? `${he.uid}-${he.recurrence_id || dateStr}` : `${he.summary || 'event'}-${dateStr}-${timeStr}`;
        return {
          id: `ha-${member.id}-${key.replace(/[^a-zA-Z0-9_-]/g, '_')}`,
          title: he.summary || 'Untitled Event',
          memberId: member.id,
          category: member.role === 'kid' ? 'school' : 'family',
          date: dateStr,
          time: timeStr,
          location: he.location || '',
          notes: he.description || ''
        };
      });
    }

    // Home Assistant start / end ("2026-10-14T16:00:00", "2026-10-14 16:00:00" or a bare date) -> { dateStr, timeStr }.
    static dateAndTime(startObj, endObj) {
      const raw = (v, k) => typeof v === 'string' ? v.trim() : (v && typeof v === 'object' ? (v.dateTime || v.date || v[k] || '').trim() : '');
      const parse = (text) => new Date(text.includes(' ') && !text.includes('T') ? text.replace(' ', 'T') : text);
      const clock = (d) => d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
      const startRaw = raw(startObj, 'start');
      if (!startRaw) return { dateStr: toLocalYMD(new Date()), timeStr: 'All Day' };
      if (/^\d{4}-\d{2}-\d{2}$/.test(startRaw)) return { dateStr: startRaw, timeStr: 'All Day' };
      const start = parse(startRaw);
      if (isNaN(start.getTime())) return { dateStr: toLocalYMD(new Date()), timeStr: 'All Day' };
      let timeStr = clock(start);
      const endRaw = raw(endObj, 'end');
      if (endRaw && !/^\d{4}-\d{2}-\d{2}$/.test(endRaw)) {
        const end = parse(endRaw);
        if (!isNaN(end.getTime()) && clock(end) !== timeStr) timeStr = `${timeStr} - ${clock(end)}`;
      }
      return { dateStr: toLocalYMD(start), timeStr };
    }
  }

class CalendarModule {
    constructor({ feed, mealPlan }) {
      this.feed = feed;
      this.mealPlan = mealPlan;
      this.currentDate = new Date();
      this.activeView = 'week';
      this.selectedEvent = null;
      this.HOUR_HEIGHT = 54;
      // Phones can't fit a week grid: open on the agenda.
      if (matchMedia('(max-width: 600px)').matches) this.activeView = 'agenda';
      this.initUI();
      if (this.activeView === 'agenda') {
        document.querySelectorAll('.switch-btn').forEach(b => b.classList.toggle('active', b.dataset.calView === 'agenda'));
        document.querySelectorAll('.cal-grid-view, .cal-timeline-view, .cal-agenda-view').forEach(v => v.classList.remove('active'));
        document.getElementById('cal-view-agenda')?.classList.add('active');
      }
      // A member filter someone left on shouldn't hide everyone else's events for good.
      let filterTimer;
      const armFilterReset = () => {
        clearTimeout(filterTimer);
        filterTimer = setTimeout(() => {
          const f = stateManager.data.activeMemberId;
          if (f && f !== 'all') stateManager.setActiveMember('all');
        }, 2 * 60 * 1000);
      };
      ['pointerdown', 'keydown'].forEach(evt => window.addEventListener(evt, armFilterReset, { passive: true }));
      this.syncViewPicker();
      this.render();
    }

    // The dropdown shows the active view; opening one calendar dropdown closes the other.
    syncViewPicker() {
      const label = document.getElementById('cal-view-current-label');
      const active = document.querySelector('.switch-btn.active');
      if (label && active) label.textContent = active.textContent;
    }

    initUI() {
      const viewPicker = document.getElementById('cal-view-picker');
      const viewCurrent = document.getElementById('cal-view-current');
      viewCurrent?.addEventListener('click', (e) => {
        e.stopPropagation();
        document.getElementById('cal-member-picker')?.classList.remove('open');
        viewCurrent.setAttribute('aria-expanded', viewPicker.classList.toggle('open'));
      });
      document.addEventListener('click', () => {
        viewPicker?.classList.remove('open');
        viewCurrent?.setAttribute('aria-expanded', 'false');
      });

      // Navigation buttons
      document.getElementById('cal-today-btn')?.addEventListener('click', () => {
        this.currentDate = new Date();
        this.render();
      });

      document.getElementById('cal-prev-btn')?.addEventListener('click', () => {
        if (this.activeView === 'month') {
          this.currentDate.setMonth(this.currentDate.getMonth() - 1);
        } else if (this.activeView === 'week') {
          this.currentDate.setDate(this.currentDate.getDate() - 7);
        } else if (this.activeView === '3day') {
          this.currentDate.setDate(this.currentDate.getDate() - 3);
        } else if (this.activeView === 'agenda') {
          this.currentDate.setDate(this.currentDate.getDate() - 7);
        }
        this.render();
      });

      document.getElementById('cal-next-btn')?.addEventListener('click', () => {
        if (this.activeView === 'month') {
          this.currentDate.setMonth(this.currentDate.getMonth() + 1);
        } else if (this.activeView === 'week') {
          this.currentDate.setDate(this.currentDate.getDate() + 7);
        } else if (this.activeView === '3day') {
          this.currentDate.setDate(this.currentDate.getDate() + 3);
        } else if (this.activeView === 'agenda') {
          this.currentDate.setDate(this.currentDate.getDate() + 7);
        }
        this.render();
      });

      // View Switcher Buttons
      document.querySelectorAll('.switch-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          document.querySelectorAll('.switch-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          this.activeView = btn.dataset.calView;
          
          document.querySelectorAll('.cal-grid-view, .cal-timeline-view, .cal-agenda-view').forEach(v => v.classList.remove('active'));
          document.getElementById(`cal-view-${this.activeView}`)?.classList.add('active');
          this.syncViewPicker();

          // A hidden grid loses its scroll position, so coming back to it has to scroll again.
          this._scrolledKey = null;
          this.render();
        });
      });

      // Event Details Popover buttons & dismiss listeners
      document.getElementById('popover-close-btn')?.addEventListener('click', () => {
        this.closeEventPopover();
      });

      document.getElementById('popover-edit-btn')?.addEventListener('click', () => {
        if (this.selectedEvent) {
          const evt = this.selectedEvent;
          this.closeEventPopover();
          this.openEventModal(evt);
        }
      });

      document.getElementById('popover-delete-btn')?.addEventListener('click', () => {
        if (this.selectedEvent) {
          this.feed.remove(this.selectedEvent.id);
          this.closeEventPopover();
          this.render();
        }
      });

      // Light dismiss when clicking outside popover
      document.addEventListener('pointerdown', (e) => {
        const popover = document.getElementById('event-details-popover');
        if (!popover || !popover.classList.contains('active')) return;
        if (!popover.contains(e.target) && !e.target.closest('.timeline-event-card, .event-chip, .agenda-card-item, .allday-chip')) {
          this.closeEventPopover();
        }
      });

      // Escape key to dismiss popover
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          this.closeEventPopover();
        }
      });

      // Add Event Modal Listeners
      document.getElementById('add-event-btn')?.addEventListener('click', () => {
        this.openEventModal();
      });

      document.getElementById('event-modal-close')?.addEventListener('click', () => {
        this.closeEventModal();
      });

      document.getElementById('event-modal-cancel')?.addEventListener('click', () => {
        this.closeEventModal();
      });

      document.getElementById('event-allday-check')?.addEventListener('change', () => this.syncEventTimeFields());
      document.getElementById('event-time-input')?.addEventListener('input', () => this.syncEventTimeFields());

      document.getElementById('event-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        this.handleSaveEvent();
      });

      document.getElementById('event-delete-btn')?.addEventListener('click', () => {
        const eventId = document.getElementById('event-id').value;
        if (eventId) {
          this.feed.remove(eventId);
          this.closeEventModal();
          this.render();
        }
      });

    }

    // Open the time grid an hour before now, once per visible period, so today's events aren't below the fold.
    scrollTimelineToNow(containerId, key) {
      if (this._scrolledKey === key) return;
      const box = document.getElementById(containerId);
      if (!box) return;
      this._scrolledKey = key;
      const now = new Date();
      box.scrollTop = Math.max(0, ((now.getHours() * 60 + now.getMinutes()) / 60 - 1) * this.HOUR_HEIGHT);
    }

    render() {
      if (this.activeView === 'month') {
        this.renderMonthView();
      } else if (this.activeView === 'week') {
        const startOfWeek = new Date(this.currentDate);
        startOfWeek.setDate(this.currentDate.getDate() - this.currentDate.getDay());
        this.renderTimelineView(7, startOfWeek, 'week');
        this.scrollTimelineToNow('week-scroll-container', `w${toLocalYMD(startOfWeek)}`);
      } else if (this.activeView === '3day') {
        const startOf3Day = new Date(this.currentDate);
        this.renderTimelineView(3, startOf3Day, 'threeday');
        this.scrollTimelineToNow('threeday-scroll-container', `d${toLocalYMD(startOf3Day)}`);
      } else if (this.activeView === 'agenda') {
        this.renderAgendaView();
      }
    }

    // HOURLY TIMELINE ENGINE (Week & 3-Day Views)
    renderTimelineView(numDays, startDate, prefix) {
      const titleEl = document.getElementById('cal-current-label');
      if (titleEl) {
        if (numDays === 7) {
          const endWeek = new Date(startDate);
          endWeek.setDate(endWeek.getDate() + 6);
          titleEl.textContent = `${startDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${endWeek.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;
        } else if (numDays === 3) {
          const end3Day = new Date(startDate);
          end3Day.setDate(end3Day.getDate() + 2);
          titleEl.textContent = `${startDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${end3Day.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;
        }
      }

      const headerRow = document.getElementById(`${prefix}-header-row`);
      const alldayRow = document.getElementById(`${prefix}-allday-row`);
      const timeScale = document.getElementById(`${prefix}-time-scale`);
      const daysGrid = document.getElementById(`${prefix}-days-container`);

      if (!headerRow || !alldayRow || !timeScale || !daysGrid) return;

      headerRow.innerHTML = '';
      alldayRow.innerHTML = '';
      timeScale.innerHTML = '';
      daysGrid.innerHTML = '';

      // Render 24-hour time scale
      for (let h = 0; h < 24; h++) {
        const slot = document.createElement('div');
        slot.className = 'time-scale-slot';
        let label = '12 AM';
        if (h === 0) label = '12 AM';
        else if (h < 12) label = `${h} AM`;
        else if (h === 12) label = '12 PM';
        else label = `${h - 12} PM`;
        slot.textContent = label;
        timeScale.appendChild(slot);
      }

      const todayStr = toLocalYMD(new Date());
      const activeMemberId = stateManager.data.activeMemberId;

      for (let i = 0; i < numDays; i++) {
        const d = new Date(startDate);
        d.setDate(startDate.getDate() + i);
        const dateStr = toLocalYMD(d);
        const isToday = dateStr === todayStr;

        // 1. Day Header Cell
        const hCell = document.createElement('div');
        hCell.className = `timeline-day-header-cell ${isToday ? 'today' : ''}`;
        hCell.innerHTML = `
          <div class="timeline-day-name">${d.toLocaleDateString('en-US', { weekday: 'short' })}</div>
          <div class="timeline-day-num">${d.getDate()}</div>
        `;
        headerRow.appendChild(hCell);

        // 2. All-Day Row Column
        const adCol = document.createElement('div');
        adCol.className = 'allday-day-col';

        const { timed, allDay } = CalendarFeed.layout(this.feed.day(dateStr, activeMemberId), this.HOUR_HEIGHT);

        allDay.forEach(adEvt => {
          const chip = document.createElement('div');
          chip.className = 'allday-chip';
          chip.tabIndex = 0;
          chip.setAttribute('role', 'button');
          styleEvent(chip, adEvt);
          chip.innerHTML = `
            ${evDots(adEvt)}
            <div class="event-card-title">${esc(adEvt.title)}</div>`;
          chip.title = `${esc(adEvt.title)} (${adEvt.time || 'All Day'})`;
          chip.addEventListener('click', (e) => {
            e.stopPropagation();
            this.openEventPopover(adEvt, chip, e);
          });
          adCol.appendChild(chip);
        });
        alldayRow.appendChild(adCol);

        // 3. Timeline Day Column in Grid
        const dayCol = document.createElement('div');
        dayCol.className = `timeline-day-col ${isToday ? 'today' : ''}`;

        // Dinner stays pinned to the bottom of the visible day, whatever the scroll position
        const dayMeal = this.mealPlan.dinnerOn(dateStr, todayStr);
        const mealPin = document.createElement('div');
        mealPin.className = dayMeal ? 'meal-pin has-meal' : 'meal-pin';
        if (dayMeal) mealPin.innerHTML = `<div class="timeline-meal-footer" title="${esc(dayMeal)}">Dinner: ${esc(dayMeal)}</div>`;

        // 24 Hour Slots
        for (let h = 0; h < 24; h++) {
          const hourSlot = document.createElement('div');
          hourSlot.className = 'timeline-hour-slot';
          hourSlot.dataset.hour = h;
          hourSlot.addEventListener('click', (e) => {
            if (e.target === hourSlot) {
              const hourStr = `${String(h).padStart(2, '0')}:00`;
              this.openEventModal(null, dateStr, hourStr);
            }
          });
          dayCol.appendChild(hourSlot);
        }
        dayCol.appendChild(mealPin);

        // Render Timed Event Cards
        timed.forEach(item => {
          const evt = item.event;

          const card = document.createElement('div');
          card.className = 'timeline-event-card';
          card.tabIndex = 0;
          card.setAttribute('role', 'button');
          card.style.top = `${item.topPx}px`;
          card.style.height = `${item.heightPx}px`;
          card.style.left = `calc(${item.leftPct}% + 1px)`;
          card.style.width = `calc(${item.widthPct}% - 3px)`;
          styleEvent(card, evt);
          if (item.heightPx < 40) card.classList.add('compact'); // under ~45 min: time and title share one line
          else if (item.heightPx < 80) card.classList.add('short'); // under 1.5 h: no room for the location

          card.innerHTML = `
            <div class="event-card-time">${evDots(evt)}${esc(item.heightPx < 80 ? CalendarFeed.startTime(evt.time) : evt.time || '')}</div>
            <div class="event-card-title">${esc(evt.title)}</div>
            ${evt.location ? `<div class="event-card-loc"><i class="fa-solid fa-location-dot"></i> ${esc(evt.location)}</div>` : ''}
          `;

          card.addEventListener('click', (e) => {
            e.stopPropagation();
            this.openEventPopover(evt, card, e);
          });

          dayCol.appendChild(card);
        });

        daysGrid.appendChild(dayCol);
      }

      this.placeTimeLine();
    }

    // The "now" line across today's column; redrawn each minute.
    placeTimeLine() {
      document.querySelectorAll('.current-time-line').forEach(el => el.remove());
      const todayCol = document.querySelector('.cal-timeline-view.active .timeline-day-col.today');
      if (!todayCol) return;
      const now = new Date();
      const line = document.createElement('div');
      line.className = 'current-time-line';
      line.style.top = `${((now.getHours() * 60 + now.getMinutes()) / 60) * this.HOUR_HEIGHT}px`;
      line.innerHTML = '<span class="current-time-dot"></span>';
      todayCol.appendChild(line);
    }

    // MONTH GRID VIEW
    renderMonthView() {
      const year = this.currentDate.getFullYear();
      const month = this.currentDate.getMonth();

      const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
      const titleEl = document.getElementById('cal-current-label');
      if (titleEl) titleEl.textContent = `${monthNames[month]} ${year}`;

      const container = document.getElementById('month-days-container');
      if (!container) return;
      container.innerHTML = '';

      const firstDayIndex = new Date(year, month, 1).getDay();
      const totalDays = new Date(year, month + 1, 0).getDate();
      const prevMonthDays = new Date(year, month, 0).getDate();

      const activeMemberId = stateManager.data.activeMemberId;
      const todayStr = toLocalYMD(new Date());

      // Previous Month Days Padding
      for (let i = firstDayIndex; i > 0; i--) {
        const prevDay = prevMonthDays - i + 1;
        const cell = document.createElement('div');
        cell.className = 'day-cell other-month';
        cell.innerHTML = `<span class="day-number">${prevDay}</span>`;
        container.appendChild(cell);
      }

      // Current Month Days
      for (let day = 1; day <= totalDays; day++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        const isToday = dateStr === todayStr;

        const cell = document.createElement('div');
        cell.className = `day-cell ${isToday ? 'today' : ''}`;
        cell.innerHTML = `<span class="day-number">${day}</span>`;

        const dayEvents = this.feed.day(dateStr, activeMemberId);

        const eventsList = document.createElement('div');
        eventsList.className = 'day-events-list';

        dayEvents.forEach(evt => {
          const chip = document.createElement('div');
          chip.className = 'event-chip';
          chip.tabIndex = 0;
          chip.setAttribute('role', 'button');
          styleEvent(chip, evt);
          const start = CalendarFeed.startTime(evt.time);
          chip.innerHTML = `${evDots(evt)}<strong class="event-chip-title">${esc(evt.title)}</strong>${start ? `<span class="event-chip-time">${esc(start)}</span>` : ''}`;

          chip.addEventListener('click', (e) => {
            e.stopPropagation();
            this.openEventPopover(evt, chip, e);
          });

          eventsList.appendChild(chip);
        });

        cell.appendChild(eventsList);

        // Click cell to add event for that date
        cell.addEventListener('click', () => {
          this.openEventModal(null, dateStr);
        });

        container.appendChild(cell);
      }
    }

    // MULTI-COLUMN FAMILY AGENDA VIEW
    renderAgendaView() {
      const titleEl = document.getElementById('cal-current-label');
      if (titleEl) titleEl.textContent = 'Family Agenda';

      const container = document.getElementById('agenda-members-container');
      if (!container) return;
      container.innerHTML = '';

      const activeMemberId = stateManager.data.activeMemberId;
      const members = stateManager.data.members;
      const todayStr = toLocalYMD(new Date());

      const formatAgendaHeading = (dateStr) => {
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        const tomorrowStr = toLocalYMD(tomorrow);

        try {
          const [y, m, d] = dateStr.split('-').map(Number);
          const dateObj = new Date(y, m - 1, d);
          const dayName = dateObj.toLocaleDateString('en-US', { weekday: 'short' });
          const monthDay = dateObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

          if (dateStr === todayStr) return `TODAY • ${dayName}, ${monthDay}`;
          if (dateStr === tomorrowStr) return `TOMORROW • ${dayName}, ${monthDay}`;
          return `${dayName}, ${monthDay}`;
        } catch (_) {
          return dateStr;
        }
      };

      const membersToRender = activeMemberId === 'all' 
        ? members 
        : members.filter(m => m.id === activeMemberId);

      if (activeMemberId !== 'all') {
        container.style.gridTemplateColumns = 'minmax(320px, 640px)';
        container.style.justifyContent = 'center';
      } else {
        container.style.gridTemplateColumns = '';
        container.style.justifyContent = '';
      }

      membersToRender.forEach(m => {
        const col = document.createElement('div');
        col.className = 'agenda-member-col';

        col.innerHTML = `
          <div class="agenda-col-header" style="color: ${m.color};">
            <div class="agenda-member-profile">
              <span class="agenda-avatar">${esc(m.avatar)}</span>
              <div>
                <div class="agenda-member-name">${esc(m.name)}</div>
                <div class="agenda-member-role">${m.role === 'kid' ? 'Kid' : 'Parent'}</div>
              </div>
            </div>
            ${m.role === 'kid' ? `<div class="agenda-member-stars">
              <i class="fa-solid fa-star"></i> ${m.stars || 0} stars
            </div>` : ''}
          </div>
          <div class="agenda-col-body" id="agenda-col-body-${m.id}"></div>
        `;

        const colBody = col.querySelector(`#agenda-col-body-${m.id}`);

        const days = this.feed.agenda(m.id, todayStr);
        if (days.length === 0) {
          colBody.innerHTML = `<div class="agenda-empty-state">No upcoming events scheduled for ${esc(m.name)}</div>`;
        } else {
          days.forEach(({ date: dStr, events }) => {
            const divider = document.createElement('div');
            divider.className = 'agenda-date-divider';
            divider.textContent = formatAgendaHeading(dStr);
            colBody.appendChild(divider);

            events.forEach(evt => {
              const card = document.createElement('div');
              card.className = 'agenda-card-item';
          card.tabIndex = 0;
          card.setAttribute('role', 'button');
              styleEvent(card, evt, [m.id]);

              card.innerHTML = `
                <div class="agenda-card-time">${evt.time || 'All Day'}</div>
                <div class="agenda-card-title">${esc(evt.title)}</div>
                ${evt.location ? `<div class="agenda-card-loc"><i class="fa-solid fa-location-dot"></i> ${esc(evt.location)}</div>` : ''}
              `;

              card.addEventListener('click', (e) => {
                e.stopPropagation();
                this.openEventPopover(evt, card, e);
              });

              colBody.appendChild(card);
            });
          });
        }

        container.appendChild(col);
      });
    }

    // EVENT DETAILS POPOVER
    openEventPopover(evt, anchorEl, mouseEvt = null) {
      const popover = document.getElementById('event-details-popover');
      if (!popover) return;

      evt = this.feed.copiesOf(evt); // same event on several calendars: every attendee, any location or notes
      this.selectedEvent = evt;

      const member = stateManager.data.members.find(m => m.id === evt.memberId);

      const memberTag = document.getElementById('popover-member-tag');
      if (memberTag) {
        const ids = evt.memberIds && evt.memberIds.length > 1 ? evt.memberIds : [evt.memberId];
        memberTag.innerHTML = ids.map(mid => {
          const m = mid === 'shared'
            ? { name: 'Shared', color: 'var(--color-shared)' }
            : stateManager.data.members.find(x => x.id === mid);
          return `<span style="display:inline-flex;align-items:center;padding:2px 10px;border-radius:12px;background:${m?.color || 'var(--color-primary)'}22;font-size:12px;font-weight:600;">${esc(m?.name || mid)}</span>`;
        }).join('');
      }

      const titleEl = document.getElementById('popover-title');
      if (titleEl) titleEl.textContent = evt.title || 'Untitled Event';

      const timeTextEl = document.getElementById('popover-time-text');
      if (timeTextEl) {
        let datePart = evt.date || '';
        try {
          const [y, m, d] = evt.date.split('-').map(Number);
          const dObj = new Date(y, m - 1, d);
          datePart = dObj.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
        } catch (_) {}
        timeTextEl.textContent = `${datePart} • ${evt.time || 'All Day'}`;
      }

      const locRow = document.getElementById('popover-location-row');
      const locText = document.getElementById('popover-location-text');
      if (locRow && locText) {
        if (evt.location && evt.location.trim()) {
          locRow.style.display = 'flex';
          locText.textContent = evt.location.trim();
        } else {
          locRow.style.display = 'none';
        }
      }

      const notesRow = document.getElementById('popover-notes-row');
      const notesText = document.getElementById('popover-notes-text');
      if (notesRow && notesText) {
        if (evt.notes && evt.notes.trim()) {
          notesRow.style.display = 'flex';
          notesText.textContent = evt.notes.trim();
        } else {
          notesRow.style.display = 'none';
        }
      }

      // Events from Home Assistant's calendars belong to those calendars: they can be hidden here, not changed.
      const editBtn = document.getElementById('popover-edit-btn');
      if (editBtn) editBtn.style.display = isHaEvent(evt) ? 'none' : '';

      popover.classList.add('active');
      const popoverWidth = popover.offsetWidth || 320;
      const popoverHeight = popover.offsetHeight || 220;

      let left = 20;
      let top = 100;

      if (anchorEl && typeof anchorEl.getBoundingClientRect === 'function') {
        const rect = anchorEl.getBoundingClientRect();
        left = rect.left;
        top = rect.bottom + 8;

        if (left + popoverWidth > window.innerWidth - 16) {
          left = Math.max(16, window.innerWidth - popoverWidth - 16);
        }
        if (top + popoverHeight > window.innerHeight - 16) {
          top = Math.max(16, rect.top - popoverHeight - 8);
        }
      } else if (mouseEvt) {
        left = Math.min(window.innerWidth - popoverWidth - 16, Math.max(16, mouseEvt.clientX));
        top = Math.min(window.innerHeight - popoverHeight - 16, Math.max(16, mouseEvt.clientY + 8));
      }

      popover.style.left = `${Math.round(left)}px`;
      popover.style.top = `${Math.round(top)}px`;
    }

    closeEventPopover() {
      this.selectedEvent = null;
      const popover = document.getElementById('event-details-popover');
      if (popover) {
        popover.classList.remove('active');
      }
    }

    // MODAL HANDLERS
    openEventModal(event = null, defaultDate = null, defaultTime = null) {
      const modal = document.getElementById('event-modal');
      const memberSelect = document.getElementById('event-member-select');
      if (!modal || !memberSelect) return;

      // Populate Member dropdown
      memberSelect.innerHTML = stateManager.data.members.map(m => `
        <option value="${m.id}">${esc(m.avatar)} ${esc(m.name)}</option>
      `).join('') + `<option value="shared">Shared</option>`;

      if (event) {
        document.getElementById('event-modal-title').textContent = 'Edit Family Event';
        document.getElementById('event-id').value = event.id;
        document.getElementById('event-title-input').value = event.title;
        document.getElementById('event-member-select').value = event.memberId;
        document.getElementById('event-category-select').value = event.category || 'family';
        document.getElementById('event-date-input').value = event.date;
        const fields = CalendarFeed.timeFields(event.time);
        document.getElementById('event-allday-check').checked = fields.allDay;
        document.getElementById('event-time-input').value = fields.start;
        document.getElementById('event-end-input').value = fields.end;
        document.getElementById('event-location-input').value = event.location || '';
        document.getElementById('event-delete-btn').classList.remove('hidden');
      } else {
        document.getElementById('event-modal-title').textContent = 'Add Family Event';
        document.getElementById('event-id').value = '';
        document.getElementById('event-title-input').value = '';
        document.getElementById('event-member-select').value = stateManager.data.activeMemberId !== 'all' ? stateManager.data.activeMemberId : stateManager.data.members[0].id;
        document.getElementById('event-date-input').value = defaultDate || toLocalYMD(new Date());
        document.getElementById('event-allday-check').checked = false;
        document.getElementById('event-time-input').value = defaultTime || '09:00';
        document.getElementById('event-end-input').value = '';
        document.getElementById('event-location-input').value = '';
        document.getElementById('event-delete-btn').classList.add('hidden');
      }

      this.syncEventTimeFields();
      modal.classList.add('active');
    }

    // All day hides the times (disabled fields skip validation); an end time can't precede the start.
    syncEventTimeFields() {
      const allDay = document.getElementById('event-allday-check').checked;
      const start = document.getElementById('event-time-input');
      const end = document.getElementById('event-end-input');
      document.getElementById('event-time-row').classList.toggle('hidden', allDay);
      start.disabled = allDay;
      end.disabled = allDay;
      end.min = start.value;
    }

    closeEventModal() {
      document.getElementById('event-modal')?.classList.remove('active');
    }

    handleSaveEvent() {
      const formattedTime = CalendarFeed.timeFromFields({
        allDay: document.getElementById('event-allday-check').checked,
        start: document.getElementById('event-time-input').value,
        end: document.getElementById('event-end-input').value
      });

      const eventObj = {
        id: document.getElementById('event-id').value,
        title: document.getElementById('event-title-input').value,
        memberId: document.getElementById('event-member-select').value,
        category: document.getElementById('event-category-select').value,
        date: document.getElementById('event-date-input').value,
        time: formattedTime,
        location: document.getElementById('event-location-input').value
      };

      this.feed.save(eventObj);
      this.closeEventModal();
      this.render();
    }

  }

/* --------------------------------------------------------------------------
     4. CHORES & ROUTINES MODULE
     -------------------------------------------------------------------------- */
  // Confetti cannons from both bottom corners (canvas, no library); skipped for reduced-motion users.
  function launchConfetti() {
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const canvas = document.createElement('canvas');
    canvas.className = 'confetti-canvas';
    canvas.width = innerWidth;
    canvas.height = innerHeight;
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    const colors = ['#f59e0b', '#fbbf24', '#2563eb', '#38bdf8', '#e11d48', '#fb7185', '#10b981', '#a78bfa'];
    const bits = [];
    const start = performance.now();
    const fire = (count) => {
      for (const side of [-1, 1]) {
        const x = side < 0 ? 0 : canvas.width;
        for (let i = 0; i < count; i++) {
          const angle = (Math.PI / 180) * (50 + Math.random() * 35);   // degrees above the horizon, aimed inward
          const speed = (canvas.height / 26) * (0.65 + Math.random() * 0.6) + 8;
          bits.push({
            x, y: canvas.height, vx: -side * Math.cos(angle) * speed, vy: -Math.sin(angle) * speed,
            w: 6 + Math.random() * 7, h: 9 + Math.random() * 8, round: Math.random() < 0.25,
            rot: Math.random() * 6.28, vr: -0.3 + Math.random() * 0.6, tilt: Math.random() * 6.28,
            c: colors[(Math.random() * colors.length) | 0], life: 1
          });
        }
      }
    };
    fire(90);
    setTimeout(() => fire(60), 220);
    setTimeout(() => fire(45), 520);
    let last = start;
    (function frame(now) {
      const dt = Math.min(3, (now - last) / 16.67); // frame-rate independent (a slow tablet shouldn't run in slow motion)
      last = now;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (const b of bits) {
        b.vx *= 0.985 ** dt; b.vy = b.vy * 0.985 ** dt + 0.38 * dt;   // drag + gravity
        b.x += b.vx * dt; b.y += b.vy * dt; b.rot += b.vr * dt; b.tilt += 0.12 * dt;
        if (b.vy > 0 && b.y > canvas.height * 0.55) b.life -= 0.012 * dt;
        ctx.save();
        ctx.globalAlpha = Math.max(0, b.life);
        ctx.translate(b.x, b.y);
        ctx.rotate(b.rot);
        ctx.scale(1, Math.cos(b.tilt));                    // flutter
        ctx.fillStyle = b.c;
        if (b.round) { ctx.beginPath(); ctx.arc(0, 0, b.w / 2, 0, 6.28); ctx.fill(); } else ctx.fillRect(-b.w / 2, -b.h / 2, b.w, b.h);
        ctx.restore();
      }
      const elapsed = now - start;
      if (elapsed < 7000 && (elapsed < 700 || bits.some(b => b.life > 0 && b.y < canvas.height + 40))) requestAnimationFrame(frame);
      else canvas.remove();
    })(start);
  }

  /* --- Chores page view helpers: one vocabulary of rows, cards, tags and meters --- */
  const icon = (name, cls = '') => `<i class="${name.includes(' ') ? name : 'fa-solid ' + name} ${cls}" aria-hidden="true"></i>`;
  const ROUTINE_ORDER = ['morning', 'afterschool', 'bedtime', 'general'];
  const ROUTINE_META = {
    morning: { label: 'Morning', icon: 'fa-sun' },
    afterschool: { label: 'After school', icon: 'fa-school' },
    bedtime: { label: 'Bedtime', icon: 'fa-moon' },
    general: { label: 'Daily chores', icon: 'fa-list-check' }
  };
  const FREQ_LABEL = { daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', annually: 'Yearly' };
  // Entries store a timestamp; older seed entries only have a text label.
  const logTime = (a) => {
    if (!a.at) return a.time;
    const d = new Date(a.at), days = Math.round((new Date().setHours(0, 0, 0, 0) - new Date(d).setHours(0, 0, 0, 0)) / 86400000);
    const clock = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    return days === 0 ? clock : days === 1 ? `Yesterday ${clock}` : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };
  const ptsHtml = (n) => `<span class="pts">${n < 0 ? '−' : '+'}${Math.abs(n)} ${icon('fa-star')}</span>`;
  const avatarHtml = (m, cls = '') => `<span class="avatar ${cls}" aria-hidden="true">${esc(m.avatar)}</span>`;
  const meterHtml = (pct) => `<div class="meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div>`;
  const emptyHtml = (ic, text) => `<div class="empty-state">${icon(ic)}<span>${text}</span></div>`;
  const sectionHtml = (label, ic, body, aside = '') => `<section class="section"><h4 class="section-label">${icon(ic)} <span>${label}</span>${aside ? `<span class="tag">${aside}</span>` : ''}</h4>${body}</section>`;
  const itemRow = (item, { meta = '', edit = false } = {}) => {
    const routine = !!item._routine;
    const done = routine ? item.completedToday : item.status === 'completed';
    const type = routine ? 'routine' : 'chore';
    if (edit) return `<div class="check-row edit" data-item-id="${item.id}" data-item-type="${type}">
      <span class="drag-handle" data-drag role="button" aria-label="Drag ${esc(item.title)} to move">${icon('fa-grip-vertical')}</span>
      <span class="check-main"><span class="check-title">${esc(item.title)}</span><span class="check-meta">${ptsHtml(routine ? 1 : item.points)}</span></span>
      <button type="button" class="icon-quiet" data-edit-item aria-label="Edit ${esc(item.title)}">${icon('fa-pen')}</button>
      <button type="button" class="icon-quiet" data-delete-item aria-label="Delete ${esc(item.title)}">${icon('fa-trash')}</button>
    </div>`;
    return `<div class="check-row${done ? ' done' : ''}" data-item-id="${item.id}" data-item-type="${type}" role="checkbox" aria-checked="${!!done}" tabindex="0">
      <span class="check-box">${icon('fa-check')}</span>
      <span class="check-main"><span class="check-title">${esc(item.title)}</span>${meta ? `<span class="check-meta">${meta}</span>` : ''}</span>
      ${ptsHtml(routine ? 1 : item.points)}
    </div>`;
  };

  // 'both' assigns one independent chore to each kid; it only makes sense with two or more.
  const everyKidOption = (n) => n < 2 ? '' : `<option value="both">👫 ${n === 2 ? 'Both' : 'All'} kids</option>`;

  class ChoresModule {
    constructor({ gate, tasks, ledger, toast }) {
      this.gate = gate;
      this.tasks = tasks;
      this.ledger = ledger;
      this.toast = toast;
      this.activeTab = 'both'; // 'both' (Kids Dashboard) | a member id
      const saved = (k, d) => { try { return localStorage.getItem(k) || d; } catch (_) { return d; } };
      this.taskGroup = saved('taskGroup', 'priority'); // board columns: 'priority' | 'theme' | 'time'
      this.taskView = saved('taskView', 'board');      // 'board' | 'calendar'
      this.taskMonth = new Date(new Date().getFullYear(), new Date().getMonth(), 1);
      this.initUI();
      this.render();
    }

    initUI() {
      // Header Add Item button (prompts PIN for kids' chores)
      document.getElementById('todos-add-item-btn')?.addEventListener('click', async () => {
        if (this.roleOf(this.activeTab) === 'parent') {
          this.openParentTaskModal(this.activeTab);
        } else if (await this.gate.ask('Add Chore', 'Enter 4-digit parent PIN to add a chore')) {
          this.openChoreModal();
        }
      });

      // Wildcard Header Add button (PIN-gated, opens the chore dialog on "Wildcard")
      document.getElementById('btn-add-wildcard-header')?.addEventListener('click', async () => {
        if (await this.gate.ask('Add wildcard', 'Enter your 4-digit parent PIN to add a wildcard.')) this.openChoreModal('either', null, { freq: 'weekly' });
      });
      this.bindToolbar(document.getElementById('view-chores') || document);
      document.getElementById('chore-member-select')?.addEventListener('change', (e) => {
        // Wildcards reset weekly by default, kid chores daily.
        if (!this.editingChoreId) document.getElementById('chore-frequency-select').value = e.target.value === 'either' ? 'weekly' : 'daily';
      });
      this.initStore();

      // Kid Chore Modal listeners
      document.getElementById('chore-modal-close')?.addEventListener('click', () => this.closeChoreModal());
      document.getElementById('chore-modal-cancel')?.addEventListener('click', () => this.closeChoreModal());
      document.getElementById('chore-modal-delete')?.addEventListener('click', () => {
        if (!this.editingChoreId) return;
        this.ledger.remove(this.editingChoreId);
        this.closeChoreModal();
        this.render();
        this.toast('Chore deleted');
      });
      document.getElementById('chore-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        this.handleCreateChore();
      });

      // Parent Task Modal listeners
      document.getElementById('parent-task-modal-close')?.addEventListener('click', () => this.closeParentTaskModal());
      document.getElementById('parent-task-modal-cancel')?.addEventListener('click', () => this.closeParentTaskModal());
      document.getElementById('parent-task-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        this.handleCreateParentTask();
      });

      this.ledger.onPrize = (prize) => this.celebratePurchase(prize);
      document.getElementById('goal-banner-close')?.addEventListener('click', () => document.getElementById('goal-banner').classList.remove('active'));
    }

    // Banner + confetti when a kid buys a prize.
    celebratePurchase({ memberId, title, cost }) {
      const member = stateManager.data.members.find(m => m.id === memberId);
      const banner = document.getElementById('goal-banner');
      if (!member || !banner) return;
      document.getElementById('goal-banner-title').textContent = `${member.name} got a prize!`;
      document.getElementById('goal-banner-name').textContent = title;
      document.getElementById('goal-banner-sub').textContent = `Spent ${cost} stars. A to-do was added for Mom and Dad.`;
      banner.classList.add('active');
      this.playChime();
      launchConfetti();
    }

    playChime() {
      try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = (this.audioCtx = this.audioCtx || new AudioCtx());
        if (ctx.state === 'suspended') ctx.resume();
        const notes = [523.25, 659.25, 783.99, 1046.50];
        notes.forEach((freq, idx) => {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0.12, ctx.currentTime + idx * 0.07);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.07 + 0.25);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(ctx.currentTime + idx * 0.07);
          osc.stop(ctx.currentTime + idx * 0.07 + 0.25);
        });
      } catch (_) {}
    }

    triggerStarPop(element, text = `${icon('fa-star')} +1`) {
      this.playChime();
      const star = document.createElement('div');
      star.innerHTML = text;
      star.style.position = 'fixed';
      const rect = element.getBoundingClientRect();
      star.style.left = `${rect.left + rect.width / 2}px`;
      star.style.top = `${rect.top}px`;
      star.style.color = 'var(--color-amber)';
      star.style.fontWeight = 'bold';
      star.style.fontSize = 'var(--text-lg)';
      star.style.zIndex = '9999';
      star.className = 'star-celebrate';
      document.body.appendChild(star);
      setTimeout(() => star.remove(), 750);
    }

    render() {
      // Synchronize with activeMemberId from stateManager
      const activeMem = stateManager.data.activeMemberId;
      if (activeMem === 'all' || !activeMem) {
        this.activeTab = 'both';
      } else if (this.roleOf(activeMem)) {
        this.activeTab = activeMem;
      }

      this.updateHeaderInfo();

      const kidsMainEl = document.getElementById('todos-kids-main-container');
      const kidPageEl = document.getElementById('todos-kid-page-container');
      const parentPageEl = document.getElementById('todos-parent-page-container');

      // Side-by-side kids boards & right wildcard panel (See ADR 0001 in family-dashboard-docs/adr/)
      if (this.activeTab === 'both') {
        if (kidsMainEl) kidsMainEl.style.display = '';
        if (kidPageEl) kidPageEl.style.display = 'none';
        if (parentPageEl) parentPageEl.style.display = 'none';

        this.syncKidCharts();
        this.renderWildcardChores();
      } else if (this.roleOf(this.activeTab) === 'kid') {
        if (kidsMainEl) kidsMainEl.style.display = 'none';
        if (kidPageEl) kidPageEl.style.display = 'flex';
        if (parentPageEl) parentPageEl.style.display = 'none';

        this.renderKidAchievementsPage(this.activeTab);
      } else if (this.roleOf(this.activeTab) === 'parent') {
        if (kidsMainEl) kidsMainEl.style.display = 'none';
        if (kidPageEl) kidPageEl.style.display = 'none';
        if (parentPageEl) parentPageEl.style.display = 'flex';

        this.renderParentTacticalPage(this.activeTab);
      }

    }

    roleOf(memberId) { return stateManager.data.members.find(m => m.id === memberId)?.role; }

    // One chart per kid, in member order, in a horizontally scrolling row beside the wildcard column.
    syncKidCharts() {
      const grid = document.getElementById('todos-kids-main-container');
      if (!grid) return;
      let row = document.getElementById('kid-charts-row');
      if (!row) {
        row = document.createElement('div');
        row.id = 'kid-charts-row';
        row.className = 'kid-charts-row';
        grid.insertBefore(row, grid.firstChild);
      }
      const kids = stateManager.data.members.filter(m => m.role === 'kid');
      const wanted = new Set(kids.map(k => `${k.id}-chore-chart`));
      row.querySelectorAll('.kid-chore-chart').forEach(el => { if (!wanted.has(el.id)) el.remove(); });
      kids.forEach(k => {
        const id = `${k.id}-chore-chart`;
        let el = document.getElementById(id);
        if (!el) {
          el = document.createElement('div');
          el.className = 'kid-chore-chart glass-panel';
          el.id = id;
        }
        row.appendChild(el); // keeps member order
        this.renderKidChart(k.id);
      });
    }

    updateHeaderInfo() {
      const actions = document.getElementById('todos-header-actions');
      const addBtnText = document.getElementById('todos-add-item-text');

      document.getElementById('view-chores')?.classList.toggle('edit-mode', !!this.editMode);
      document.querySelectorAll('#todos-header-actions [data-toggle-edit]').forEach(b => {
        b.innerHTML = `${icon(this.editMode ? 'fa-check' : 'fa-pen')} ${this.editMode ? 'Done' : 'Edit'}`;
        b.classList.toggle('btn-primary', !!this.editMode);
        b.classList.toggle('btn-secondary', !this.editMode);
      });
      if (this.activeTab === 'both') {
        if (actions) actions.style.display = '';
        if (addBtnText) addBtnText.textContent = 'Add chore';
      } else {
        // Individual task dashboards (kids or parents) carry their own actions in the hero header.
        if (actions) actions.style.display = 'none';
      }
    }

    renderKidChart(memberId) {
      const el = document.getElementById(`${memberId}-chore-chart`);
      if (!el) return;

      const member = stateManager.data.members.find(m => m.id === memberId);
      if (!member) return;

      const pct = this.ledger.starPct(member);
      const next = this.ledger.nextPrize(member);
      const { byRoutine, daily } = this.ledger.itemsFor(memberId);
      const body = ROUTINE_ORDER.map(t => this.routineSection(t, t === 'general' ? daily : byRoutine[t], memberId)).join('');

      el.style.setProperty('--member-color', member.color);
      el.innerHTML = `
        <button type="button" class="card-head card-head--link" data-open-member="${member.id}" aria-label="Open ${esc(member.name)}'s page">
          ${avatarHtml(member)}
          <span class="card-head-main">
            <span class="card-title">${esc(member.name)}</span>
            <span class="stars">${icon('fa-star')} ${member.stars}${next && member.stars < next.cost ? ` / ${next.cost}` : ''}</span>
          </span>
          ${icon('fa-chevron-right', 'card-head-chevron')}
        </button>
        <div class="card-meter">
          ${meterHtml(pct)}
          ${next && member.stars >= next.cost ? `<p class="card-meta">${esc(this.prizeLine(member))}</p>` : ''}
        </div>
        <div class="card-body">
          ${body || emptyHtml('fa-list-check', 'No daily chores yet.')}
        </div>
      `;

      this.bindChecks(el);
      el.querySelector('[data-open-member]')?.addEventListener('click', () => this.openMember(member.id));
    }

    // In edit mode every section shows (even empty) as a drop target with an Add button.
    routineSection(type, items, kidId, edit = this.editMode) {
      items = items || [];
      if (!items.length && !edit) return '';
      const { label, icon: ic } = ROUTINE_META[type];
      const done = items.filter(i => i._routine ? i.completedToday : i.status === 'completed').length;
      return this.dropSection(label, ic, items, edit, done, { kid: kidId, routine: type });
    }

    // Section body; `where` = { kid, routine } or { kid, freq } describes what a drop or an Add here means.
    dropSection(label, ic, items, edit, done, where) {
      const attrs = Object.entries(where).map(([k, v]) => `data-${k}="${v}"`).join(' ');
      const rows = items.map(i => itemRow(i, { edit })).join('');
      if (!edit) return sectionHtml(label, ic, `<div class="stack">${rows}</div>`, `${done}/${items.length}`);
      return sectionHtml(label, ic, `<div class="stack drop-zone" data-drop ${attrs}>${rows}</div>
        <button type="button" class="btn-secondary btn-sm add-here" data-add-chore ${attrs}>${icon('fa-plus')} Add</button>`);
    }

    // One click handler for every check row (routines toggle; chores complete once). Edit mode: rows don't check off.
    bindChecks(root) {
      this.bindEdit(root);
      root.querySelectorAll('.check-row[data-item-id]:not(.edit)').forEach(row => {
        row.addEventListener('click', () => {
          const earned = this.ledger.tick(row.dataset.itemId);
          if (earned?.stars) this.triggerStarPop(row, `${icon('fa-star')} +${earned.stars}`);
          this.render();
        });
      });
    }

    async toggleEdit() {
      if (this.editMode) { this.editMode = false; this.render(); return; }
      if (await this.gate.ask('Edit chores', 'Enter your 4-digit parent PIN to edit chores.')) { this.editMode = true; this.render(); }
    }

    // Header/hero buttons: Prize store and Edit toggle.
    bindToolbar(root) {
      root.querySelectorAll('[data-open-store]').forEach(b => b.addEventListener('click', () => this.openStore()));
      root.querySelectorAll('[data-toggle-edit]').forEach(b => b.addEventListener('click', () => this.toggleEdit()));
    }

    // Edit-mode controls inside a rendered root: edit, delete, add-here, drag to move.
    bindEdit(root) {
      if (!this.editMode) return;
      root.querySelectorAll('[data-edit-item]').forEach(b => b.addEventListener('click', () =>
        this.openChoreModal(null, b.closest('[data-item-id]').dataset.itemId)));
      root.querySelectorAll('[data-delete-item]').forEach(b => b.addEventListener('click', () => {
        const id = b.closest('[data-item-id]').dataset.itemId;
        const found = this.ledger.find(id);
        if (!found || !confirm(`Delete "${found.item.title}"?`)) return;
        this.ledger.remove(id);
        this.render();
      }));
      root.querySelectorAll('[data-add-chore]').forEach(b => b.addEventListener('click', () =>
        this.openChoreModal(b.dataset.kid, null, { routine: b.dataset.routine, freq: b.dataset.freq })));
      root.querySelectorAll('[data-drag]').forEach(h => h.addEventListener('pointerdown', (e) => this.startDrag(e, h.closest('.check-row'))));
    }

    // Pointer-based drag (works for touch, pen and mouse): drop on any section to move the item there.
    startDrag(e, row) {
      if (e.button) return;
      e.preventDefault();
      const ghost = row.cloneNode(true);
      const rect = row.getBoundingClientRect();
      Object.assign(ghost.style, { position: 'fixed', left: rect.left + 'px', top: rect.top + 'px', width: rect.width + 'px', margin: 0, zIndex: 3000, pointerEvents: 'none', opacity: 0.9, boxShadow: '0 10px 28px rgba(0,0,0,.25)' });
      document.body.appendChild(ghost);
      row.classList.add('dragging');
      const dx = e.clientX - rect.left, dy = e.clientY - rect.top;
      let zone = null;
      const targetAt = (x, y) => document.elementFromPoint(x, y)?.closest('[data-drop]');
      const move = (ev) => {
        ghost.style.left = ev.clientX - dx + 'px';
        ghost.style.top = ev.clientY - dy + 'px';
        const z = targetAt(ev.clientX, ev.clientY);
        if (z !== zone) { zone?.classList.remove('drop-over'); zone = z; zone?.classList.add('drop-over'); }
      };
      const end = (ev) => {
        window.removeEventListener('pointermove', move);
        window.removeEventListener('pointerup', end);
        window.removeEventListener('pointercancel', end);
        ghost.remove();
        row.classList.remove('dragging');
        zone?.classList.remove('drop-over');
        const z = ev.type === 'pointerup' ? targetAt(ev.clientX, ev.clientY) : null;
        if (z) this.dropItem(row.dataset.itemId, z, ev.clientY);
      };
      window.addEventListener('pointermove', move);
      window.addEventListener('pointerup', end);
      window.addEventListener('pointercancel', end);
    }

    dropItem(id, zone, y) {
      const found = this.ledger.find(id);
      if (!found) return;
      const { kid, routine, freq } = zone.dataset;
      // Position: before the first row of this kind that sits below the drop point, else last.
      const rows = [...zone.querySelectorAll('.check-row:not(.dragging)')].filter(r => r.dataset.itemType === found.kind);
      const below = rows.find(r => r.getBoundingClientRect().top + r.offsetHeight / 2 > y);
      this.ledger.move(id, { kid, routine, freq, beforeId: below?.dataset.itemId });
      this.render();
    }

    remember(key, value) {
      try { localStorage.setItem(key, value); } catch (_) { /* private mode: just don't persist */ }
    }

    openMember(id) {
      this.activeTab = id;
      stateManager.setActiveMember(id);
      this.render();
    }

    renderWildcardChores() {
      const container = document.getElementById('wildcard-chores-container');
      if (!container) return;

      const wildcards = this.ledger.wildcards();
      const kids = this.ledger.kids();

      if (!wildcards.length) {
        container.innerHTML = emptyHtml('fa-bolt', 'No wildcard chores right now.');
        return;
      }

      container.innerHTML = wildcards.map(c => {
        const claimedBy = c.completedBy && stateManager.data.members.find(m => m.id === c.completedBy);
        const edit = this.editMode;
        const action = edit ? `<div class="item-actions">
            <button type="button" class="btn-secondary btn-sm" data-edit-item>${icon('fa-pen')} Edit</button>
            <button type="button" class="btn-secondary btn-sm" data-delete-item>${icon('fa-trash')} Delete</button>
          </div>`
          : c.status === 'completed'
          ? `<span class="tag tag--done">${icon('fa-circle-check')} Claimed by ${esc(claimedBy ? claimedBy.name : 'a kid')}</span>`
          : `<div class="item-actions">${kids.map(k => `
              <button type="button" class="btn-secondary btn-sm" data-claim="${c.id}" data-member-id="${k.id}">${esc(k.avatar)} ${esc(k.name)}</button>`).join('')}
            </div>`;
        return `
          <div class="item-card${c.status === 'completed' && !edit ? ' done' : ''}" data-item-id="${c.id}">
            <div class="item-head"><span class="check-title">${esc(c.title)}</span>${ptsHtml(c.points)}</div>
            ${action}
          </div>`;
      }).join('');

      this.bindEdit(container);
      container.querySelectorAll('[data-claim]').forEach(btn => {
        btn.addEventListener('click', () => {
          const r = this.ledger.claim(btn.dataset.claim, btn.dataset.memberId);
          if (r) this.triggerStarPop(btn, `${icon('fa-star')} +${r.chore.points}`);
          this.render();
        });
      });
    }

    /* ---- Prize store: kids spend stars; the parents get a to-do ---- */
    initStore() {
      document.getElementById('store-modal-close')?.addEventListener('click', () => this.closeStore());
      document.getElementById('store-modal')?.addEventListener('click', (e) => { if (e.target.id === 'store-modal') this.closeStore(); });
    }

    openStore() {
      this.storeEdit = false;
      this.armed = null;
      this.renderStore();
      document.getElementById('store-modal')?.classList.add('active');
    }

    closeStore() { document.getElementById('store-modal')?.classList.remove('active'); }

    renderStore() {
      const body = document.getElementById('store-body');
      if (!body) return;
      const kids = this.ledger.kids();
      const rewards = this.ledger.rewards();
      const edit = this.storeEdit;

      const bal = kids.map(k => `<span class="store-bal" style="--member-color:${k.color}">${avatarHtml(k)} <b>${esc(k.name)}</b> ${icon('fa-star')} ${k.stars}</span>`).join('');
      const rows = rewards.map(w => edit ? `
        <div class="store-item" data-reward="${w.id}">
          <input type="text" class="store-title-input" value="${esc(w.title)}" maxlength="40" aria-label="Prize name" />
          <input type="number" class="store-cost-input" value="${w.cost}" min="1" max="999" aria-label="Star cost" />
          <button type="button" class="icon-quiet" data-del-reward aria-label="Delete ${esc(w.title)}">${icon('fa-trash')}</button>
        </div>` : `
        <div class="store-item" data-reward="${w.id}">
          <span class="store-item-title">${icon('fa-gift')} ${esc(w.title)}</span>
          <span class="pts">${w.cost} ${icon('fa-star')}</span>
          <span class="store-buy">${kids.map(k => {
            const can = k.stars >= w.cost, armed = this.armed === `${k.id}|${w.id}`;
            return `<button type="button" class="btn-${armed ? 'primary' : 'secondary'} btn-sm" data-buy="${w.id}" data-kid="${k.id}" ${can ? '' : 'disabled'}>${armed ? 'Tap to confirm' : `${esc(k.avatar)} ${esc(k.name)}`}</button>`;
          }).join('')}</span>
        </div>`).join('') || emptyHtml('fa-gift', 'No prizes yet. Tap Edit prizes to add some.');

      body.innerHTML = `
        <div class="store-balances">${bal}</div>
        <div class="stack">${rows}</div>
        ${edit ? `<div class="store-item store-add">
          <input type="text" id="store-new-title" class="store-title-input" placeholder="New prize…" maxlength="40" />
          <input type="number" id="store-new-cost" class="store-cost-input" placeholder="Stars" min="1" max="999" />
          <button type="button" class="btn-primary btn-sm" id="store-add-btn">${icon('fa-plus')} Add</button>
        </div>` : ''}
        <div class="store-foot">
          <button type="button" class="btn-secondary btn-sm" id="store-edit-toggle">${icon(edit ? 'fa-check' : 'fa-pen')} ${edit ? 'Done' : 'Edit prizes'}</button>
        </div>`;

      body.querySelector('#store-edit-toggle').addEventListener('click', async () => {
        if (this.storeEdit) { this.storeEdit = false; this.renderStore(); return; }
        if (await this.gate.ask('Edit prizes', 'Enter your 4-digit parent PIN to edit the prize store.')) { this.storeEdit = true; this.renderStore(); }
      });
      body.querySelectorAll('[data-buy]').forEach(b => b.addEventListener('click', () => {
        const key = `${b.dataset.kid}|${b.dataset.buy}`;
        if (this.armed !== key) { // two taps so a stray touch can't spend stars
          this.armed = key; this.renderStore();
          clearTimeout(this.armTimer); this.armTimer = setTimeout(() => { this.armed = null; this.renderStore(); }, 4000);
          return;
        }
        this.armed = null;
        if (this.ledger.buy(b.dataset.kid, b.dataset.buy)) { this.closeStore(); this.render(); }
      }));
      body.querySelectorAll('.store-item[data-reward]').forEach(row => {
        const id = row.dataset.reward;
        row.querySelector('.store-title-input')?.addEventListener('change', (e) => this.ledger.editReward(id, { title: e.target.value }));
        row.querySelector('.store-cost-input')?.addEventListener('change', (e) => this.ledger.editReward(id, { cost: e.target.value }));
        row.querySelector('[data-del-reward]')?.addEventListener('click', () => {
          const reward = this.ledger.rewards().find(r => r.id === id);
          if (reward && confirm(`Delete prize "${reward.title}"?`)) this.ledger.removeReward(id);
        });
      });
      body.querySelector('#store-add-btn')?.addEventListener('click', () => {
        this.ledger.addReward({ title: document.getElementById('store-new-title').value, cost: document.getElementById('store-new-cost').value });
      });
    }

    prizeLine(member) {
      const prize = this.ledger.nextPrize(member);
      return !prize ? 'No prizes yet' : member.stars >= prize.cost ? `Ready to buy: ${prize.title}` : `${prize.cost - member.stars} more stars for ${prize.title}`;
    }

    renderKidAchievementsPage(kidId) {
      const container = document.getElementById('todos-kid-page-container');
      const member = stateManager.data.members.find(m => m.id === kidId);
      if (!container || !member) return;

      const pct = this.ledger.starPct(member);
      const { byRoutine, daily, weekly, monthly } = this.ledger.itemsFor(kidId);
      const wildcards = this.ledger.wildcards().filter(c => c.status === 'pending');

      const missions = ROUTINE_ORDER.map(t => this.routineSection(t, t === 'general' ? daily : byRoutine[t], kidId)).join('');
      const wildcardSection = wildcards.length ? sectionHtml('Bonus wildcards', 'fa-bolt', `<div class="stack">${wildcards.map(w => `
        <div class="item-card">
          <div class="item-head"><span class="check-title">${esc(w.title)}</span>${ptsHtml(w.points)}</div>
          <button type="button" class="btn-primary btn-sm" data-claim="${w.id}">Claim</button>
        </div>`).join('')}</div>`) : '';

      const cadence = (label, ic, items, freq) => this.dropSection(label, ic, items, this.editMode,
        items.filter(c => c.status === 'completed').length, { kid: kidId, freq });

      const log = this.ledger.activity(kidId).map(a => `
        <div class="log-row"><span>${esc(a.title)}</span><span class="log-meta">${a.kind === 'goal' ? `<span class="tag tag--done">${icon('fa-trophy')} Goal</span>` : a.points ? ptsHtml(a.points) : ''} <span>${esc(logTime(a))}</span></span></div>`).join('')
        || emptyHtml('fa-clock-rotate-left', 'No stars earned yet today.');

      container.style.setProperty('--member-color', member.color);
      container.innerHTML = `
        <div class="kid-hero-card glass-panel">
          <div class="hero-main">
            ${avatarHtml(member, 'avatar--lg')}
            <h3 class="hero-title">${esc(member.name)}'s stars</h3>
          </div>
          <div class="hero-stat">
            <div class="hero-stat-row">
              <div class="hero-count">${member.stars}<span class="card-meta"> stars</span></div>
            </div>
            ${meterHtml(pct)}
            <p class="card-meta">${esc(this.prizeLine(member))}</p>
          </div>
          <div class="hero-actions">
            <button type="button" class="btn-primary" data-open-store>${icon('fa-gift')} Prize store</button>
            <button type="button" class="btn-secondary" data-toggle-edit>${icon(this.editMode ? 'fa-check' : 'fa-pen')} ${this.editMode ? 'Done' : 'Edit'}</button>
          </div>
        </div>

        <div class="kid-page-grid">
          <div class="panel glass-panel">
            <div class="panel-head"><h3>${icon('fa-clipboard-check')} Today</h3></div>
            ${missions || emptyHtml('fa-list-check', 'No missions today.')}
            ${wildcardSection}
          </div>
          <div class="stack-col">
            <div class="panel glass-panel">
              <div class="panel-head"><h3>${icon('fa-calendar-week')} Weekly &amp; monthly</h3></div>
              ${cadence('Weekly', 'fa-calendar-check', weekly, 'weekly')}
              ${cadence('Monthly', 'fa-calendar-days', monthly, 'monthly')}
            </div>
            <div class="panel glass-panel">
              <div class="panel-head"><h3>${icon('fa-clock-rotate-left')} Recent stars</h3></div>
              <div class="stack">${log}</div>
            </div>
          </div>
        </div>`;

      this.bindToolbar(container);
      this.bindChecks(container);
      container.querySelectorAll('[data-claim]').forEach(btn => {
        btn.addEventListener('click', () => {
          const r = this.ledger.claim(btn.dataset.claim, kidId);
          if (r) this.triggerStarPop(btn, `${icon('fa-star')} +${r.chore.points}`);
          this.render();
        });
      });
    }

    renderParentTacticalPage(parentId) {
      const container = document.getElementById('todos-parent-page-container');
      const member = stateManager.data.members.find(m => m.id === parentId);
      if (!container || !member) return;

      const tasks = this.tasks;
      const today = tasks.today();
      const b = tasks.board(parentId, this.taskGroup);
      const { open, done, recurring, group: g } = b;

      const dueTag = (t) => {
        if (!t.dueDate || t.completed) return '';
        const d = ParentTasks.daysUntil(t.dueDate, today);
        if (d < 0) return `<span class="tag tag--high">Overdue ${-d}d</span>`;
        if (d === 0) return '<span class="tag tag--medium">Due today</span>';
        return `<span class="tag">${icon('fa-regular fa-calendar')} ${d === 1 ? 'Tomorrow' : d <= 7 ? `In ${d} days` : esc(t.dueDate)}</span>`;
      };

      const card = (t) => `
        <article class="task-card${t.completed ? ' done' : ''}" data-task-id="${t.id}" draggable="true">
          <div class="task-card-top">
            <button type="button" class="check-box" role="checkbox" aria-checked="${!!t.completed}" aria-label="Done: ${esc(t.title)}">${icon('fa-check')}</button>
            <button type="button" class="task-title" data-edit-task>${esc(t.title)}</button>
            <button type="button" class="icon-quiet icon-quiet--danger" data-delete-task aria-label="Delete ${esc(t.title)}">${icon('fa-trash-can')}</button>
          </div>
          ${t.notes ? `<p class="check-meta task-notes">${esc(t.notes)}</p>` : ''}
          <div class="check-meta tag-line">
            ${g.hide !== 'priority' ? `<span class="tag tag--${t.priority || 'medium'}">${PRIORITY_LABEL[t.priority || 'medium']}</span>` : ''}
            ${g.hide !== 'category' ? `<span class="tag">${CATEGORY_LABEL[t.category] || esc(t.category || 'General')}</span>` : ''}
            ${g.hide !== 'due' ? dueTag(t) : ''}
            ${t.memberId === 'shared' ? '<span class="tag">Shared</span>' : ''}
          </div>
        </article>`;

      const column = (key, label, items, { drop = true, extra = '' } = {}) => `
        <section class="board-col" data-col="${key}" ${drop ? '' : 'data-nodrop'} aria-label="${label}">
          <header class="board-col-head"><h4>${label}</h4><span class="tag">${items.length}</span>${extra}</header>
          <div class="board-col-body">${items.map(card).join('') || '<p class="board-empty">Nothing here</p>'}</div>
        </section>`;

      const board = b.columns.map(c => column(c.key, c.label, c.tasks, { drop: c.droppable })).join('')
        + column('done', 'Done', done, { extra: done.length ? '<button type="button" class="link-btn board-clear" data-clear-done>Clear</button>' : '' });

      const repeatCard = (t) => `
        <div class="item-card" data-task-id="${t.id}">
          <div class="item-head"><span class="tag">${icon('fa-repeat')} ${FREQ_LABEL[t.frequency]}</span>${dueTag(t)}</div>
          <button type="button" class="task-title" data-edit-task>${esc(t.title)}</button>
          ${t.notes ? `<p class="check-meta">${esc(t.notes)}</p>` : ''}
          <div class="item-actions item-actions--between">
            <span class="check-meta">Last done: ${esc(t.lastCompletedDate || 'never')}</span>
            <span class="item-actions">
              <button type="button" class="btn-secondary btn-sm" data-complete>${icon('fa-circle-check')} Done</button>
              <button type="button" class="icon-quiet icon-quiet--danger" data-delete-task aria-label="Delete ${esc(t.title)}">${icon('fa-trash-can')}</button>
            </span>
          </div>
        </div>`;

      const monthStart = new Date(this.taskMonth);
      const monthLabel = monthStart.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
      const taskCalendar = () => {
        const lead = monthStart.getDay();
        const days = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 0).getDate();
        const cells = Math.ceil((lead + days) / 7) * 7;
        const chip = (t) => `<button type="button" class="tc-chip tc-${t.priority || 'medium'}" data-task-id="${t.id}" draggable="true" title="${esc(t.title)}">${ParentTasks.repeats(t) ? icon('fa-repeat') + ' ' : ''}<span>${esc(t.title)}</span></button>`;
        const grid = Array.from({ length: cells }, (_, i) => {
          const d = new Date(monthStart.getFullYear(), monthStart.getMonth(), 1 - lead + i);
          const ymd = toLocalYMD(d), list = b.scheduled[ymd] || [];
          const inMonth = d.getMonth() === monthStart.getMonth();
          return `<div class="tc-day${inMonth ? '' : ' tc-other'}${ymd === today ? ' tc-today' : ''}" data-date="${ymd}">
            <button type="button" class="tc-num" data-add-date="${ymd}" aria-label="Add task on ${d.toLocaleDateString('en-US', { month: 'long', day: 'numeric' })}">${d.getDate()}</button>
            ${list.slice(0, 3).map(chip).join('')}${list.length > 3 ? `<span class="tc-more">+${list.length - 3} more</span>` : ''}
          </div>`;
        }).join('');
        return `
          <div class="tc-head">
            <div class="item-actions">
              <button type="button" class="icon-quiet" data-month="-1" aria-label="Previous month">${icon('fa-chevron-left')}</button>
              <h4 class="tc-title">${monthLabel}</h4>
              <button type="button" class="icon-quiet" data-month="1" aria-label="Next month">${icon('fa-chevron-right')}</button>
            </div>
            <button type="button" class="btn-secondary btn-sm" data-month="0">Today</button>
          </div>
          <div class="tc-weekdays">${['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => `<span>${d}</span>`).join('')}</div>
          <div class="tc-grid">${grid}</div>
          <div class="tc-undated"><span class="card-meta">No date${b.undated.length ? ' · drag onto a day to schedule' : ''}</span>
            <div class="tag-line">${b.undated.map(chip).join('') || '<span class="card-meta">Everything has a date.</span>'}</div>
          </div>`;
      };

      container.innerHTML = `
        <div class="parent-hero-card glass-panel" style="--member-color: ${member.color};">
          <div class="hero-main">
            ${avatarHtml(member, 'avatar--lg')}
            <div>
              <h3 class="hero-title">${esc(member.name)}'s tasks</h3>
              <p class="card-meta">${open.length} open · ${recurring.length} repeating · ${done.length} done</p>
            </div>
          </div>
          <form class="quick-add hero-quick" id="tactical-quick-add-form">
            <input type="text" id="tactical-quick-title" placeholder="Quick add a task" aria-label="Quick add task" enterkeyhint="done" autocomplete="off" required />
          </form>
          <div class="hero-actions">
            <button type="button" class="btn-primary" id="btn-parent-new-task">${icon('fa-plus')} Add task</button>
          </div>
        </div>

        <div class="parent-layout">
          <div class="panel glass-panel">
            <div class="panel-head">
              <div class="seg" role="group" aria-label="View">${[['board', 'fa-table-columns', 'Board'], ['calendar', 'fa-calendar-days', 'Calendar']].map(([k, ic, label]) =>
                `<button type="button" class="seg-btn${this.taskView === k ? ' active' : ''}" data-taskview="${k}" aria-pressed="${this.taskView === k}">${icon(ic)} ${label}</button>`).join('')}</div>
              ${this.taskView === 'board' ? `<div class="group-by"><span class="card-meta">Group by</span>
                <div class="seg" role="group">${b.groups.map(({ key, label }) =>
                  `<button type="button" class="seg-btn${g.key === key ? ' active' : ''}" data-group="${key}" aria-pressed="${g.key === key}">${label}</button>`).join('')}</div>
              </div>` : ''}
            </div>
            ${this.taskView === 'board' ? `<div class="board">${board}</div>` : taskCalendar()}
          </div>

          <div class="panel glass-panel">
            <div class="panel-head"><h3>${icon('fa-repeat')} Repeating</h3></div>
            <div class="stack">${recurring.map(repeatCard).join('') || emptyHtml('fa-repeat', 'Nothing repeats yet. Add a task and set Repeats.')}</div>
          </div>
        </div>`;

      const toast = (message, undo) => this.toast(message, undo && { label: 'Undo', run: undo });
      container.querySelectorAll('[data-group]').forEach(b => b.addEventListener('click', () => { this.taskGroup = b.dataset.group; this.remember('taskGroup', this.taskGroup); this.render(); }));
      container.querySelectorAll('[data-taskview]').forEach(b => b.addEventListener('click', () => { this.taskView = b.dataset.taskview; this.remember('taskView', this.taskView); this.render(); }));
      container.querySelectorAll('[data-month]').forEach(b => b.addEventListener('click', () => {
        const n = +b.dataset.month, t = new Date();
        this.taskMonth = n === 0 ? new Date(t.getFullYear(), t.getMonth(), 1) : new Date(this.taskMonth.getFullYear(), this.taskMonth.getMonth() + n, 1);
        this.render();
      }));
      container.querySelectorAll('[data-add-date]').forEach(b => b.addEventListener('click', () => this.openParentTaskModal(parentId, null, { dueDate: b.dataset.addDate })));
      container.querySelectorAll('.tc-chip').forEach(c => c.addEventListener('click', () => this.openParentTaskModal(parentId, tasks.find(c.dataset.taskId))));

      container.querySelector('#tactical-quick-add-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        const title = document.getElementById('tactical-quick-title').value.trim();
        if (!title) return;
        tasks.add({ title, memberId: parentId, frequency: 'none', notes: '', priority: 'medium', category: 'general', dueDate: '' });
        this.render();
      });

      container.querySelectorAll('[data-task-id]').forEach(el => {
        const id = el.dataset.taskId;
        el.querySelector('[data-edit-task]')?.addEventListener('click', () => this.openParentTaskModal(parentId, tasks.find(id)));
        el.querySelector('.check-box')?.addEventListener('click', () => {
          tasks.toggle(id);
          this.render();
          container.querySelector(`[data-task-id="${id}"] .check-box`)?.focus();
        });
        el.querySelector('[data-complete]')?.addEventListener('click', () => {
          const r = tasks.toggle(id);
          this.render();
          if (r) toast(`Done. Next due ${r.task.dueDate}.`, r.undo);
        });
        el.querySelector('[data-delete-task]')?.addEventListener('click', () => {
          const undo = tasks.remove(id);
          this.render();
          if (undo) toast('Task deleted', undo);
        });
      });

      container.querySelector('[data-clear-done]')?.addEventListener('click', () => {
        const { count, undo } = tasks.clearDone(parentId);
        if (undo) toast(`Cleared ${count} done`, undo);
      });

      // Drag a card to another column to change its priority / theme / urgency (mouse; touch uses the edit dialog).
      container.querySelectorAll('.task-card, .tc-chip').forEach(c => {
        c.addEventListener('dragstart', (e) => { e.dataTransfer.setData('text/plain', c.dataset.taskId); e.dataTransfer.effectAllowed = 'move'; c.classList.add('dragging'); });
        c.addEventListener('dragend', () => c.classList.remove('dragging'));
      });
      const dropOn = (el, apply) => {
        el.addEventListener('dragover', (e) => { e.preventDefault(); el.classList.add('drop-over'); });
        el.addEventListener('dragleave', (e) => { if (!el.contains(e.relatedTarget)) el.classList.remove('drop-over'); });
        el.addEventListener('drop', (e) => {
          e.preventDefault();
          apply(e.dataTransfer.getData('text/plain'));
        });
      };
      container.querySelectorAll('.board-col:not([data-nodrop])').forEach(col => dropOn(col, (id) => tasks.dropOnColumn(id, g.key, col.dataset.col)));
      container.querySelectorAll('.tc-day').forEach(day => dropOn(day, (id) => tasks.schedule(id, day.dataset.date)));

      container.querySelector('#btn-parent-new-task')?.addEventListener('click', () => this.openParentTaskModal(parentId));
    }

    // Add a chore, or edit a chore/routine when `itemId` is given. `where` pre-fills { routine, freq }.
    openChoreModal(defaultKidId = null, itemId = null, where = {}) {
      const modal = document.getElementById('chore-modal');
      const select = document.getElementById('chore-member-select');
      if (!modal || !select) return;
      const found = itemId ? this.ledger.find(itemId) : null;
      const item = found?.item || null;
      const isRoutine = found?.kind === 'routine';
      this.editingChoreId = item ? item.id : null;

      const kids = this.ledger.kids();
      const selectedId = item ? item.memberId : (defaultKidId || (kids.some(k => k.id === this.activeTab) ? this.activeTab : kids[0]?.id));
      select.innerHTML = kids.map(m => `
        <option value="${m.id}" ${selectedId === m.id ? 'selected' : ''}>${esc(m.avatar)} ${esc(m.name)}</option>
      `).join('') + (isRoutine ? '' : `<option value="either" ${selectedId === 'either' ? 'selected' : ''}>⚡ Wildcard (any kid)</option>`)
        + (item ? '' : everyKidOption(kids.length));

      document.getElementById('chore-title-input').value = item ? item.title : '';
      document.getElementById('chore-points-select').value = String(item && !isRoutine ? item.points : 3);
      document.getElementById('chore-frequency-select').value = where.freq || item?.frequency || 'daily';
      document.getElementById('chore-routine-select').value = where.routine || item?.routineType || 'general';
      // Routines are always 1 star and daily, so those fields don't apply.
      ['chore-points-select', 'chore-frequency-select'].forEach(id => { document.getElementById(id).closest('.form-group').hidden = isRoutine; });
      document.getElementById('chore-modal-title').textContent = item ? 'Edit Chore' : 'Add Chore';
      document.getElementById('chore-modal-submit').textContent = item ? 'Save' : 'Add Chore';
      document.getElementById('chore-modal-delete').hidden = !item;
      modal.classList.add('active');
    }

    closeChoreModal() {
      document.getElementById('chore-modal')?.classList.remove('active');
      this.editingChoreId = null;
    }

    handleCreateChore() {
      const title = document.getElementById('chore-title-input').value.trim();
      if (!title) return;
      const memberId = document.getElementById('chore-member-select').value;
      const points = parseInt(document.getElementById('chore-points-select').value) || 3;
      const frequency = document.getElementById('chore-frequency-select')?.value || 'daily';
      const routineType = document.getElementById('chore-routine-select')?.value || 'general';

      const existing = this.editingChoreId && this.ledger.find(this.editingChoreId);
      if (existing) this.ledger.edit(this.editingChoreId, { title, memberId, points, routineType, frequency });
      else this.ledger.add({ title, kid: memberId, points, routineType, frequency });

      this.closeChoreModal();
      this.render();
      this.toast(`✓ Chore "${title}" ${existing ? 'saved' : 'added'}!`);
    }

    // Add a task, or edit one when `task` is given.
    openParentTaskModal(defaultMember = stateManager.data.members.find(m => m.role === 'parent')?.id, task = null, defaults = {}) {
      const modal = document.getElementById('parent-task-modal');
      const select = document.getElementById('parent-task-member-select');
      if (!modal || !select) return;
      const memberId = task ? task.memberId : defaultMember;

      const parents = stateManager.data.members.filter(m => m.role === 'parent');
      select.innerHTML = parents.map(p => `
        <option value="${p.id}" ${memberId === p.id ? 'selected' : ''}>${esc(p.avatar)} ${esc(p.name)}</option>
      `).join('') + `<option value="shared" ${memberId === 'shared' ? 'selected' : ''}>Shared / Both</option>`;

      const $ = (id) => document.getElementById(id);
      $('parent-task-id').value = task ? task.id : '';
      $('parent-task-modal-title').lastElementChild.textContent = task ? 'Edit task' : 'Add task';
      $('parent-task-submit').textContent = task ? 'Save' : 'Add task';
      $('parent-task-title-input').value = task ? task.title : '';
      $('parent-task-priority-select').value = task ? (task.priority || 'medium') : 'medium';
      $('parent-task-category-select').value = task ? (task.category || 'general') : 'general';
      $('parent-task-date-input').value = task ? (task.dueDate || '') : (defaults.dueDate || '');
      $('parent-task-frequency-select').value = task ? (task.frequency || 'none') : 'none';
      $('parent-task-notes-input').value = task ? (task.notes || '') : '';
      $('parent-task-calendar-check').checked = task ? !!task.showOnCalendar : false;
      modal.classList.add('active');
    }

    closeParentTaskModal() {
      document.getElementById('parent-task-modal')?.classList.remove('active');
    }

    handleCreateParentTask() {
      const $ = (id) => document.getElementById(id).value;
      const title = $('parent-task-title-input').trim();
      if (!title) return;
      const fields = {
        title,
        memberId: $('parent-task-member-select'),
        priority: $('parent-task-priority-select'),
        category: $('parent-task-category-select'),
        dueDate: $('parent-task-date-input'),
        frequency: $('parent-task-frequency-select'),
        notes: $('parent-task-notes-input').trim(),
        showOnCalendar: document.getElementById('parent-task-calendar-check').checked
      };
      const id = $('parent-task-id');
      const existing = id && this.tasks.find(id);
      if (existing) this.tasks.update(id, fields);
      else this.tasks.add(fields);

      this.closeParentTaskModal();
      this.render();
      this.toast(`✓ Task "${title}" ${existing ? 'saved' : 'added'}`);
    }
  }

/* --------------------------------------------------------------------------
     5. MEALS & GROCERIES MODULE
     -------------------------------------------------------------------------- */
  class MealsModule {
    constructor({ lists, toast }) {
      this.groceries = lists.groceries;
      this.ideas = lists.ideas;
      this.plan = lists.plan;
      this.toast = toast;
      this.initUI();
      this.load();
    }

    initUI() {
      // Grocery
      document.getElementById('grocery-add-btn')?.addEventListener('click', () => this.handleAddGrocery());
      document.getElementById('grocery-input')?.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') this.handleAddGrocery();
      });

      // Meal picker
      document.getElementById('meal-picker-close')?.addEventListener('click', () => this.closeMealPicker());
      document.getElementById('meal-picker-overlay')?.addEventListener('click', (e) => {
        if (e.target === document.getElementById('meal-picker-overlay')) this.closeMealPicker();
      });
      document.getElementById('meal-picker-add-btn')?.addEventListener('click', () => this.handlePickerAdd());
      document.getElementById('meal-picker-input')?.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') this.handlePickerAdd();
      });
      document.getElementById('meal-picker-input')?.addEventListener('input', (e) => {
        this.renderPickerList(e.target.value);
      });
    }

    load() {
      return Promise.all([this.ideas.load(), this.plan.load(), this.groceries.load()]);
    }

    render() {
      this.renderWeekGrid();
      this.renderGroceryList();
    }

    renderWeekGrid() {
      const grid = document.getElementById('meal-week-grid');
      if (!grid) return;
      const byDay = this.plan.byDay;

      const DAY_KEYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      const DAY_FULL = { Sun: 'Sunday', Mon: 'Monday', Tue: 'Tuesday', Wed: 'Wednesday', Thu: 'Thursday', Fri: 'Friday', Sat: 'Saturday' };
      // Rolling seven days starting today, so past days never crowd the list.
      const today = new Date();

      const days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        const key = DAY_KEYS[d.getDay()];
        const isToday = d.toDateString() === today.toDateString();
        return { key, date: d, isToday };
      });

      const hintDay = days.find(d => !byDay[d.key])?.key; // the hint once, on the first free day
      grid.innerHTML = days.map(({ key, date, isToday }) => {
        const meal = byDay[key] || '';
        const dateStr = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        return `
          <div class="meal-day-row ${meal ? 'has-meal' : 'empty'} ${isToday ? 'today' : ''}" data-day="${key}">
            <div class="meal-day-info">
              <span class="meal-day-label">${DAY_FULL[key]}</span>
              <span class="meal-day-date">${dateStr}</span>
            </div>
            <div class="meal-day-choice">
              ${meal
                ? `<span class="meal-day-meal-text">${esc(meal)}</span>`
                : key === hintDay ? `<span class="meal-day-empty">Tap to plan</span>` : ''
              }
            </div>
            ${meal ? `<button class="meal-day-clear" data-day="${key}" title="Clear" aria-label="Clear meal"><i class="fa-solid fa-xmark"></i></button>` : ''}
          </div>`;
      }).join('');

      grid.querySelectorAll('.meal-day-row').forEach(row => {
        row.addEventListener('click', (e) => {
          if (e.target.closest('.meal-day-clear')) return;
          this.openMealPicker(row.dataset.day);
        });
      });

      grid.querySelectorAll('.meal-day-clear').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          this.clearMeal(btn.dataset.day);
        });
      });
    }

    openMealPicker(day) {
      this._pickerDay = day;
      const DAY_FULL = { Sun: 'Sunday', Mon: 'Monday', Tue: 'Tuesday', Wed: 'Wednesday', Thu: 'Thursday', Fri: 'Friday', Sat: 'Saturday' };
      const title = document.getElementById('meal-picker-title');
      if (title) title.innerHTML = `<i class="fa-solid fa-utensils text-sky"></i> ${DAY_FULL[day] || day}`;
      const input = document.getElementById('meal-picker-input');
      if (input) input.value = '';
      this.renderPickerList('');
      document.getElementById('meal-picker-overlay')?.classList.add('active');
      setTimeout(() => input?.focus(), 50);
    }

    closeMealPicker() {
      document.getElementById('meal-picker-overlay')?.classList.remove('active');
      this._pickerDay = null;
    }

    renderPickerList(filter) {
      const list = document.getElementById('meal-picker-list');
      if (!list) return;
      const q = (filter || '').toLowerCase();
      const ideas = this.ideas.items.filter(i => !q || i.name.toLowerCase().includes(q));

      if (ideas.length === 0) {
        list.innerHTML = `<li class="picker-empty">${q ? `No saved idea matches "${esc(filter)}" — tap Add to use it as a new meal.` : 'No meal ideas yet — type a meal above and tap Add.'}</li>`;
        return;
      }

      list.innerHTML = ideas.map(idea => `
        <li><button type="button" class="picker-idea" data-name="${idea.name.replace(/"/g, '&quot;')}">
          <i class="fa-solid fa-utensils" aria-hidden="true"></i>
          <span>${esc(idea.name)}</span>
        </button></li>
      `).join('');

      list.querySelectorAll('.picker-idea').forEach(el => {
        el.addEventListener('click', () => {
          if (this._pickerDay) {
            this.assignMeal(this._pickerDay, el.dataset.name);
            this.closeMealPicker();
          }
        });
      });
    }

    async handlePickerAdd() {
      const input = document.getElementById('meal-picker-input');
      const name = input?.value.trim();
      if (!name || !this._pickerDay) return;
      await this.ideas.add(name);
      this.assignMeal(this._pickerDay, name);
      this.closeMealPicker();
    }

    assignMeal(day, meal) {
      if (!this.plan.configured) { this.toast('Set Meal Plan entity in Settings first'); return; }
      return this.plan.set(day, meal);
    }

    clearMeal(day) {
      return this.plan.clear(day);
    }

    renderGroceryList() {
      const container = document.getElementById('grocery-list-container');
      const countEl = document.getElementById('grocery-count');
      const openKeepBtn = document.getElementById('open-keep-btn');
      if (!container) return;

      const keepUrl = stateManager.data.settings.googleKeepUrl || 'https://keep.google.com';
      if (openKeepBtn) openKeepBtn.href = keepUrl;
      this.renderSyncStatus();

      const items = this.groceries.items.filter(g => !g.bought);

      if (countEl) countEl.textContent = `${items.length} item${items.length !== 1 ? 's' : ''}`;

      if (items.length === 0) {
        container.innerHTML = `<li style="color:var(--text-muted);font-size:0.85rem;padding:12px;text-align:center;">All clear</li>`;
        return;
      }

      container.innerHTML = items.map(g => `
        <li class="grocery-item" data-grocery-id="${g.id}">
          <div style="display:flex;align-items:center;gap:8px;">
            <i class="fa-regular fa-square"></i>
            <span>${esc(g.name)}</span>
          </div>
          <button class="icon-btn" aria-label="Remove item" style="width:24px;height:24px;font-size:0.7rem;border:none;background:none;color:var(--text-muted);">
            <i class="fa-solid fa-xmark"></i>
          </button>
        </li>
      `).join('');

      container.querySelectorAll('.grocery-item').forEach(el => {
        el.addEventListener('click', (e) => {
          const id = el.dataset.groceryId;
          if (e.target.closest('button')) this.groceries.remove(id);
          else this.groceries.toggle(id);
        });
      });
    }

    renderSyncStatus() {
      const status = this.groceries.status;
      const text = document.getElementById('keep-sync-status');
      if (text) text.textContent = {
        local: 'Not linked to a to-do list. Set one in Settings.',
        connecting: 'Connecting…',
        connected: 'Connected. Checks for changes every minute.',
        offline: 'Home Assistant unreachable. Showing the last saved list.',
        unsent: 'Last change not sent. Saved on this tablet only.'
      }[status];
      text?.closest('.keep-sync-banner')?.classList.toggle('warn', status === 'offline' || status === 'unsent');
    }

    handleAddGrocery() {
      const input = document.getElementById('grocery-input');
      if (!input?.value.trim()) return;
      const name = input.value.trim();
      input.value = '';
      this.groceries.add(name);
    }
  }

/* --------------------------------------------------------------------------
     5a. PARENT PIN GATE
     -------------------------------------------------------------------------- */
  // Every parent-only action asks here. The gate owns the PIN check and the new-PIN flow and talks to its dialog
  // through a view. A refusal (cancel, close, Escape, backdrop, dialog missing) resolves false, so callers fail closed.
  class ParentGate {
    constructor(store, view) {
      this.store = store;
      this.view = view;
      this.pending = null; // { resolve, newPin: null | { first } }
      this.pin = '';
      view.onKey((key) => this.press(key));
      view.onDismiss(() => this.settle(false));
    }

    ask(title = 'Parent Verification', desc = 'Enter your 4-digit parent PIN to continue.') {
      return this.start({ title, desc, newPin: null });
    }

    // Set a new PIN: enter it, then confirm. Resolves true once it is saved.
    setNewPin() {
      return this.start({ title: 'New PIN', desc: 'Enter a new 4-digit PIN.', newPin: { first: null } });
    }

    start({ title, desc, newPin }) {
      this.settle(false); // a newer request replaces an unanswered one
      return new Promise((resolve) => {
        this.pin = '';
        this.pending = { resolve, newPin };
        if (!this.view.open({ title, desc })) this.settle(false);
      });
    }

    settle(ok) {
      const p = this.pending;
      if (!p) return;
      this.pending = null;
      this.pin = '';
      p.resolve(ok);
      this.view.close();
    }

    press(key) {
      if (!this.pending) return;
      if (key === 'back') this.pin = this.pin.slice(0, -1);
      else if (this.pin.length < 4) this.pin += key;
      this.view.setError(null);
      this.view.digits(this.pin.length);
      if (this.pin.length === 4) this.submit();
    }

    submit() {
      const { newPin } = this.pending;
      const digits = this.pin;
      this.pin = '';
      this.view.digits(0);
      if (newPin) {
        if (!newPin.first) {
          newPin.first = digits;
          this.view.setDesc('Enter it again to confirm.');
        } else if (newPin.first === digits) {
          this.store.data.settings.parentPin = digits;
          this.store.save();
          this.settle(true);
        } else {
          newPin.first = null;
          this.view.setDesc('Enter a new 4-digit PIN.');
          this.view.setError('PINs did not match — start again.');
        }
      } else if (digits === (this.store.data.settings.parentPin || '1234')) {
        this.settle(true);
      } else {
        this.view.setError('Incorrect PIN — try again.');
      }
    }
  }

  // The PIN dialog in index.html: title, description, four digit boxes, an error line and a keypad.
  function pinDialogView() {
    const modal = () => document.getElementById('admin-pin-modal');
    const view = {
      open({ title, desc }) {
        if (!modal()) return false;
        const titleEl = document.getElementById('admin-pin-title');
        if (titleEl) { titleEl.innerHTML = '<i class="fa-solid fa-key text-sky"></i> '; titleEl.append(title); }
        view.setDesc(desc);
        view.digits(0);
        view.setError(null);
        modal().classList.add('active');
        return true;
      },
      close() { modal()?.classList.remove('active'); },
      digits(n) {
        document.querySelectorAll('.pin-digit').forEach((el, i) => {
          el.value = i < n ? '•' : '';
          el.toggleAttribute('data-filled', i < n);
        });
      },
      setDesc(text) {
        const el = document.getElementById('admin-pin-desc');
        if (el) el.textContent = text;
      },
      setError(text) {
        const el = document.getElementById('pin-error');
        if (!el) return;
        el.style.display = text ? '' : 'none';
        if (text) document.getElementById('pin-error-text').textContent = text;
      },
      // On-screen keypad and physical keyboard feed the same keys: '0'-'9' and 'back'.
      onKey(fn) {
        document.getElementById('pin-keypad')?.addEventListener('click', (e) => {
          const key = e.target.closest('[data-key]')?.dataset.key;
          if (key) fn(key);
        });
        document.addEventListener('keydown', (e) => {
          if (!modal()?.classList.contains('active')) return;
          if (/^\d$/.test(e.key)) fn(e.key);
          else if (e.key === 'Backspace') fn('back');
        });
      },
      // The X and Cancel keys, and anything else that hides the dialog (Escape, backdrop, the screensaver).
      onDismiss(fn) {
        document.getElementById('admin-pin-cancel')?.addEventListener('click', () => { view.close(); fn(); });
        const m = modal();
        if (m) new MutationObserver(() => { if (!m.classList.contains('active')) fn(); }).observe(m, { attributes: true, attributeFilter: ['class'] });
      }
    };
    return view;
  }

/* --------------------------------------------------------------------------
     5b. CHORES ADMIN MODULE
     -------------------------------------------------------------------------- */
  class ChoresAdminModule {
    constructor({ gate, ledger, editChore }) {
      this.gate = gate;
      this.ledger = ledger;
      this.editChore = editChore; // opens the chore dialog for a chore id
      this.activeTab = 'chores';
      this.initUI();
    }

    initUI() {
      document.getElementById('admin-lock-btn')?.addEventListener('click', async () => {
        if (await this.gate.ask()) this.openAdminPanel('chores');
      });
      document.getElementById('admin-panel-close')?.addEventListener('click', () => this.closeAdminPanel());

      // Admin tab switching
      document.querySelectorAll('.admin-tab').forEach(tab => {
        tab.addEventListener('click', () => {
          document.querySelectorAll('.admin-tab').forEach(t => t.classList.remove('active'));
          tab.classList.add('active');
          this.activeTab = tab.dataset.adminTab;
          this.renderAdminBody();
        });
      });
    }

    openAdminPanel(tab = 'chores') {
      this.activeTab = tab;
      document.querySelectorAll('.admin-tab').forEach(t => t.classList.toggle('active', t.dataset.adminTab === tab));
      this.renderAdminBody();
      document.getElementById('admin-panel-modal').classList.add('active');
    }

    closeAdminPanel() {
      document.getElementById('admin-panel-modal').classList.remove('active');
    }

    renderAdminBody() {
      const body = document.getElementById('admin-body');
      if (!body) return;
      if (this.activeTab === 'chores') body.innerHTML = this.buildChoresToHTML();
      else if (this.activeTab === 'wildcards') body.innerHTML = this.buildWildcardsHTML();
      else if (this.activeTab === 'stars') body.innerHTML = this.buildStarsHTML();
      else if (this.activeTab === 'pin') body.innerHTML = this.buildPinChangeHTML();
      this.bindAdminBodyEvents();
    }

    buildChoresToHTML() {
      const kids = this.ledger.kids();
      const chores = (stateManager.data.chores || []).filter(c => c.memberId !== 'either');
      const rows = chores.map(c => {
        const member = stateManager.data.members.find(m => m.id === c.memberId);
        const statusBadge = c.status === 'completed'
          ? `<span style="font-size:0.72rem;color:var(--color-success-text);font-weight:700;">Done</span>`
          : `<span style="font-size:0.72rem;color:var(--text-muted);">Pending</span>`;
        const freqLabel = c.frequency === 'weekly' ? 'Weekly' : c.frequency === 'monthly' ? 'Monthly' : 'Daily';
        const freqBadge = `<span style="font-size:0.68rem;padding:2px 8px;border-radius:100px;background:var(--card-bg);border:1px solid var(--panel-border);color:var(--text-muted);">${freqLabel}</span>`;
        return `
          <div class="admin-chore-row">
            <span style="font-size:1.1rem;">${esc(member?.avatar)}</span>
            <span class="admin-chore-title">${esc(c.title)}</span>
            <span class="admin-chore-pts">+${c.points} stars</span>
            ${freqBadge}
            ${statusBadge}
            ${c.status === 'completed'
              ? `<button class="btn-success-sm" data-action="reset-chore" data-id="${c.id}"><i class="fa-solid fa-rotate-left" aria-hidden="true"></i> Reset</button>`
              : ''}
            <button class="btn-secondary-sm" data-action="edit-chore" data-id="${c.id}"><i class="fa-solid fa-pen" aria-hidden="true"></i> Edit</button>
            <button class="btn-danger-sm" data-action="delete-chore" data-id="${c.id}"><i class="fa-solid fa-xmark" aria-hidden="true"></i> Remove</button>
          </div>
        `;
      }).join('') || `<div style="color:var(--text-muted);text-align:center;padding:16px;">No kid chores yet.</div>`;

      const assignOpts = kids.map(k => `<option value="${k.id}">${esc(k.avatar)} ${esc(k.name)}</option>`).join('') + everyKidOption(kids.length);
      return `
        <div class="admin-section-title">Kid Chores &amp; Routines</div>
        ${rows}
        <div class="admin-add-form" data-form="add-chore">
          <input type="text" id="admin-chore-title" placeholder="Chore name…" style="flex:2;" />
          <select id="admin-chore-member">${assignOpts}</select>
          <select id="admin-chore-pts">
            <option value="1">1 stars</option><option value="2">2 stars</option>
            <option value="3" selected>3 stars</option><option value="5">5 stars</option><option value="8">8 stars</option><option value="10">10 stars</option>
          </select>
          <select id="admin-chore-freq">
            <option value="daily" selected>Daily</option>
            <option value="weekly">Weekly</option>
            <option value="monthly">Monthly</option>
          </select>
          <select id="admin-chore-type">
            <option value="general">General</option>
            <option value="morning">Morning</option>
            <option value="afterschool">After School</option>
            <option value="bedtime">Bedtime</option>
          </select>
          <button class="btn-primary" data-action="add-chore" style="flex-shrink:0;">+ Add</button>
        </div>
      `;
    }

    buildWildcardsHTML() {
      const wildcards = this.ledger.wildcards();
      const rows = wildcards.map(c => {
        const claimedBy = c.completedBy ? stateManager.data.members.find(m => m.id === c.completedBy) : null;
        return `
          <div class="admin-chore-row" id="admin-wc-row-${c.id}">
            <i class="fa-solid fa-bolt" aria-hidden="true"></i>
            <span class="admin-chore-title">${esc(c.title)}</span>
            <span class="admin-chore-pts">+${c.points} stars</span>
            ${c.status === 'completed'
              ? `<span style="font-size:0.72rem;color:var(--color-success-text);font-weight:700;">${claimedBy ? esc(claimedBy.name) : 'Done'}</span>
                 <button class="btn-success-sm" data-action="reset-chore" data-id="${c.id}"><i class="fa-solid fa-rotate-left" aria-hidden="true"></i> Reset</button>`
              : `<span style="font-size:0.72rem;color:var(--text-muted);">Available</span>`}
            <button class="btn-secondary-sm" data-action="edit-wildcard" data-id="${c.id}"><i class="fa-solid fa-pen" aria-hidden="true"></i> Edit</button>
            <button class="btn-danger-sm" data-action="delete-chore" data-id="${c.id}"><i class="fa-solid fa-xmark" aria-hidden="true"></i> Remove</button>
          </div>
        `;
      }).join('') || `<div style="color:var(--text-muted);text-align:center;padding:16px;">No wildcard chores yet.</div>`;

      return `
        <div class="admin-section-title">Wildcard Chores & Rewards</div>
        <p style="font-size:0.8rem;color:var(--text-secondary);margin:-6px 0 14px 0;">Only parents can create or edit wildcard rewards. Kids can claim available wildcards on their board.</p>
        ${rows}
        <div class="admin-add-form" data-form="add-wildcard" style="margin-top:14px;">
          <input type="text" id="admin-wc-title" placeholder="New wildcard chore name…" style="flex:2;" />
          <select id="admin-wc-pts">
            <option value="3">3 stars</option><option value="4">4 stars</option>
            <option value="5">5 stars</option><option value="6">6 stars</option>
            <option value="8" selected>8 stars</option><option value="10">10 stars</option>
            <option value="12">12 stars</option><option value="15">15 stars</option>
            <option value="20">20 stars</option>
          </select>
          <button class="btn-primary" data-action="add-wildcard" style="flex-shrink:0;">+ Add Wildcard</button>
        </div>
      `;
    }

    buildStarsHTML() {
      const kids = this.ledger.kids();
      return kids.map(k => `
        <div class="admin-star-row" style="border-left: 4px solid ${k.color};">
          <span class="admin-star-name" style="color:${k.color}">${esc(k.avatar)} ${esc(k.name)}</span>
          <span class="admin-star-count" id="star-count-${k.id}">${k.stars} stars</span>
          <div class="admin-star-btns">
            <button class="admin-adj-btn" data-action="adj-stars" data-member="${k.id}" data-delta="-5">−5</button>
            <button class="admin-adj-btn" data-action="adj-stars" data-member="${k.id}" data-delta="-1">−1</button>
            <button class="admin-adj-btn" data-action="adj-stars" data-member="${k.id}" data-delta="1">+1</button>
            <button class="admin-adj-btn" data-action="adj-stars" data-member="${k.id}" data-delta="5">+5</button>
            <button class="admin-adj-btn" data-action="adj-stars" data-member="${k.id}" data-delta="10">+10</button>
          </div>
        </div>
      `).join('');
    }

    buildPinChangeHTML() {
      return `
        <div class="admin-section-title">Change Parent PIN</div>
        <div style="display:flex;flex-direction:column;gap:12px;max-width:320px;">
          <div id="pin-change-msg" style="font-size:0.85rem;display:none;"></div>
          <button class="btn-primary" data-action="change-pin" style="align-self:flex-start;">Set New PIN</button>
        </div>
      `;
    }

    bindAdminBodyEvents() {
      const body = document.getElementById('admin-body');
      if (!body) return;

      // Delete / reset chores
      body.querySelectorAll('[data-action="delete-chore"]').forEach(btn => {
        btn.addEventListener('click', () => {
          this.ledger.remove(btn.dataset.id);
          this.renderAdminBody();
        });
      });

      body.querySelectorAll('[data-action="edit-chore"]').forEach(btn => {
        btn.addEventListener('click', () => this.editChore(btn.dataset.id));
      });

      body.querySelectorAll('[data-action="reset-chore"]').forEach(btn => {
        btn.addEventListener('click', () => {
          this.ledger.reset(btn.dataset.id);
          this.renderAdminBody();
        });
      });

      // Edit wildcard inline
      body.querySelectorAll('[data-action="edit-wildcard"]').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.dataset.id;
          const chore = this.ledger.find(id)?.item;
          if (!chore) return;
          const rowEl = document.getElementById(`admin-wc-row-${id}`);
          if (!rowEl) return;

          const starOptions = [1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20].map(pt =>
            `<option value="${pt}" ${chore.points === pt ? 'selected' : ''}>${pt} stars</option>`
          ).join('');

          rowEl.innerHTML = `
            <div style="display:flex;align-items:center;gap:8px;width:100%;flex-wrap:wrap;">
              <input type="text" id="edit-wc-title-${id}" value="${chore.title.replace(/"/g, '&quot;')}" style="flex:2;min-width:140px;padding:5px 8px;background:var(--input-bg);border:1px solid var(--panel-border);border-radius:6px;color:var(--text-primary);font-size:0.85rem;" />
              <select id="edit-wc-pts-${id}" style="padding:5px 8px;background:var(--input-bg);border:1px solid var(--panel-border);border-radius:6px;color:var(--text-primary);font-size:0.85rem;">
                ${starOptions}
              </select>
              <button class="btn-primary" data-action="save-wildcard" data-id="${id}" style="padding:5px 12px;font-size:0.8rem;">Save</button>
              <button class="btn-secondary-sm" data-action="cancel-wildcard" style="padding:5px 10px;">Cancel</button>
            </div>
          `;

          rowEl.querySelector('[data-action="save-wildcard"]')?.addEventListener('click', () => {
            const newTitle = document.getElementById(`edit-wc-title-${id}`)?.value.trim();
            const newPts = parseInt(document.getElementById(`edit-wc-pts-${id}`)?.value) || chore.points;
            if (!newTitle) return;
            this.ledger.edit(id, { title: newTitle, points: newPts });
            this.renderAdminBody();
          });

          rowEl.querySelector('[data-action="cancel-wildcard"]')?.addEventListener('click', () => {
            this.renderAdminBody();
          });
        });
      });

      // Add kid chore
      body.querySelector('[data-action="add-chore"]')?.addEventListener('click', () => {
        const title = document.getElementById('admin-chore-title')?.value.trim();
        const memberId = document.getElementById('admin-chore-member')?.value;
        const points = parseInt(document.getElementById('admin-chore-pts')?.value) || 3;
        const frequency = document.getElementById('admin-chore-freq')?.value || 'daily';
        const routineType = document.getElementById('admin-chore-type')?.value || 'general';
        if (!title) return;
        this.ledger.add({ title, kid: memberId, points, routineType, frequency });
        this.renderAdminBody();
      });

      // Add wildcard
      body.querySelector('[data-action="add-wildcard"]')?.addEventListener('click', () => {
        const title = document.getElementById('admin-wc-title')?.value.trim();
        const points = parseInt(document.getElementById('admin-wc-pts')?.value) || 8;
        if (!title) return;
        this.ledger.add({ title, kid: 'either', points, routineType: 'general', frequency: 'weekly' });
        this.renderAdminBody();
      });

      // Star adjustments
      body.querySelectorAll('[data-action="adj-stars"]').forEach(btn => {
        btn.addEventListener('click', () => {
          const memberId = btn.dataset.member;
          const delta = parseInt(btn.dataset.delta);
          const balance = this.ledger.adjustStars(memberId, delta);
          const el = document.getElementById(`star-count-${memberId}`);
          if (balance !== null && el) el.textContent = `${balance} stars`;
        });
      });

      // Change PIN
      body.querySelector('[data-action="change-pin"]')?.addEventListener('click', async () => {
        if (!(await this.gate.setNewPin())) return;
        const msg = document.getElementById('pin-change-msg');
        msg.textContent = 'PIN updated successfully!';
        msg.style.color = 'var(--color-success)';
        msg.style.display = '';
      });
    }
  }

/* --------------------------------------------------------------------------
     7. AMBIENT PHOTO FRAME SAVER MODULE
     -------------------------------------------------------------------------- */
  class PhotoFrameModule {
    constructor({ feed, beforeStart }) {
      this.feed = feed;
      this.beforeStart = beforeStart; // clears anything that should not linger over the screensaver
      this.overlay = document.getElementById('photo-frame-overlay');
      this.bgEl = document.getElementById('photo-slide-bg');
      this.timeEl = document.getElementById('photo-time');
      this.dateEl = document.getElementById('photo-date');
      this.captionEl = document.getElementById('photo-caption');
      this.eventsEl = document.getElementById('photo-events');

      this.photos = [
        {
          url: 'https://images.unsplash.com/photo-1511895426328-dc8714191300?auto=format&fit=crop&w=1600&q=80',
          caption: 'Summer vacation'
        },
        {
          url: 'https://images.unsplash.com/photo-1542037104857-ffbb0b915767?auto=format&fit=crop&w=1600&q=80',
          caption: 'Family hike'
        },
        {
          url: 'https://images.unsplash.com/photo-1475503572774-15a45e5d60b9?auto=format&fit=crop&w=1600&q=80',
          caption: 'Golden hour at the park'
        },
        {
          url: 'https://images.unsplash.com/photo-1536640712-4d4c36ff0e4e?auto=format&fit=crop&w=1600&q=80',
          caption: 'Weekend picnic'
        }
      ];

      this.currentIndex = 0;
      this.intervalId = null;
      this.init();
    }

    init() {
      document.getElementById('photo-frame-btn')?.addEventListener('click', () => {
        this.start();
      });

      if (this.overlay) {
        this.overlay.addEventListener('click', () => {
          this.stop();
        });
      }

      let idleTimer;
      const resetIdleTimer = () => {
        clearTimeout(idleTimer);
        idleTimer = setTimeout(() => {
          if (this.overlay && !this.overlay.classList.contains('active')) {
            this.start();
          }
        }, (stateManager.data.settings.idleSaverMinutes || 3) * 60 * 1000);
      };

      ['pointerdown', 'mousemove', 'keydown', 'touchstart'].forEach(evt => {
        window.addEventListener(evt, resetIdleTimer, { passive: true });
      });
      resetIdleTimer();
    }

    async start() {
      if (!this.overlay) return;
      clearInterval(this.intervalId);
      // Nothing should linger over the screensaver: event popover and any open dialogs.
      this.beforeStart?.();
      document.querySelectorAll('.modal-overlay.active').forEach(m => m.classList.remove('active'));
      this.overlay.classList.add('active');
      this.updateClock();

      try {
        await this.fetchImmichPhotos();
      } catch (e) {
        console.warn('Error fetching Immich photos:', e);
      }

      // Woken during the fetch: don't start a timer nothing will ever clear.
      if (!this.overlay.classList.contains('active')) return;
      this.showSlide(0);

      this.intervalId = setInterval(async () => {
        await this.advanceSlide();
        this.updateClock();
      }, (stateManager.data.settings.photoIntervalSeconds || 30) * 1000);
    }

    _immichCaption(state) {
      const exif = state.attributes?.media_exif || {};
      if (exif.city && exif.dateTimeOriginal) {
        const d = new Date(exif.dateTimeOriginal);
        const dateStr = d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
        return `${exif.city}${exif.state ? ', ' + exif.state : ''} · ${dateStr}`;
      }
      if (exif.dateTimeOriginal) {
        return new Date(exif.dateTimeOriginal).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
      }
      const fname = state.attributes?.media_filename;
      return fname ? fname.replace(/\.[^.]+$/, '').replace(/[_-]/g, ' ') : 'Family memory';
    }

    async fetchImmichPhotos() {
      try {
        const haUrl = haBase();
        const state = await haWS.getEntityState(stateManager.data.settings.photoEntity);
        if (state?.attributes?.entity_picture) {
          this.photos = [{ url: `${haUrl}${state.attributes.entity_picture}`, caption: this._immichCaption(state) }];
          return;
        }
      } catch (e) {
        console.warn('Could not fetch Immich photo via WebSocket:', e);
      }
      // Fallback: keep the built-in Unsplash photos
    }

    async advanceSlide() {
      try {
        const haUrl = haBase();
        const entity = stateManager.data.settings.photoEntity;
        const before = (await haWS.getEntityState(entity))?.state;
        await haWS.updateEntity(entity);
        // Poll until HA reports the new image (state = last-updated stamp) instead of a blind sleep.
        let state;
        for (let i = 0; i < 10; i++) {
          state = await haWS.getEntityState(entity);
          if (state?.state !== before) break;
          await new Promise(r => setTimeout(r, 500));
        }
        if (state?.attributes?.entity_picture) {
          this.photos[0] = { url: `${haUrl}${state.attributes.entity_picture}`, caption: this._immichCaption(state) };
          this.currentIndex = 0;
          this.showSlide(0);
          return;
        }
      } catch (e) {
        console.warn('Could not refresh Immich photo:', e);
      }
      this.currentIndex = (this.currentIndex + 1) % this.photos.length;
      this.showSlide(this.currentIndex);
    }

    stop() {
      if (!this.overlay) return;
      this.overlay.classList.remove('active');
      clearInterval(this.intervalId);
    }

    // Preload so the photo and its caption change together (caption used to lead the image).
    showSlide(index) {
      const photo = this.photos[index];
      if (!photo) return;
      const token = this.slideToken = (this.slideToken || 0) + 1;
      const apply = () => {
        if (token !== this.slideToken) return; // a newer slide superseded this one
        if (this.bgEl) this.bgEl.style.setProperty('--photo', `url('${photo.url}')`);
        if (this.captionEl) this.captionEl.textContent = photo.caption;
      };
      const img = new Image();
      img.onload = img.onerror = apply;
      img.src = photo.url;
    }

    // Timed events still to come (or in progress) today, as small title + time cards.
    renderEvents(now) {
      if (!this.eventsEl) return;
      const left = this.feed.remaining(now);
      const MAX = 4;
      this.eventsEl.hidden = !left.length;
      this.eventsEl.innerHTML = left.slice(0, MAX).map((e) =>
        `<div class="photo-event"><span class="photo-event-title">${esc(e.title)}</span><span class="photo-event-time">${esc(e.time)}</span></div>`
      ).join('') + (left.length > MAX ? `<div class="photo-event photo-event-more">+${left.length - MAX} more</div>` : '');
    }

    updateClock() {
      const now = new Date();
      // The clock and the slideshow matter more than the list of events beside them.
      try { this.renderEvents(now); } catch (e) { console.warn('Screensaver events failed:', e); }
      let hours = now.getHours();
      const minutes = String(now.getMinutes()).padStart(2, '0');
      const ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12 || 12;

      if (this.timeEl) this.timeEl.textContent = `${hours}:${minutes} ${ampm}`;
      if (this.dateEl) {
        this.dateEl.textContent = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
      }
    }
  }

// Pops up the doorbell camera when settings.doorbellEntity fires (settings read live, no reload needed).
  class DoorbellModule {
    constructor() {
      this.overlay = document.getElementById('doorbell-overlay');
      this.img = document.getElementById('doorbell-img');
      this.timer = null;
      this.overlay.addEventListener('click', () => this.hide());
      // A header button shows the camera on demand whenever one is set (a doorbell press is only detected with Home Assistant).
      const button = document.getElementById('doorbell-btn');
      const syncButton = () => { if (button) button.hidden = !stateManager.data.settings.doorbellCamera; };
      button?.addEventListener('click', () => this.show({ ring: false }));
      document.addEventListener('settings-saved', syncButton);
      syncButton();
      // Browsers only allow sound after a touch; unlock the audio context on the first one.
      const unlock = () => { this.audio().resume?.(); };
      window.addEventListener('pointerdown', unlock, { once: true, passive: true });
      haWS.subscribe('state_changed', ev => {
        const { entity_id, old_state, new_state } = ev.data;
        if (entity_id !== stateManager.data.settings.doorbellEntity || !old_state || !new_state) return;
        if (old_state.state === new_state.state) return;
        if (['off', 'unavailable', 'unknown'].includes(new_state.state)) return;
        this.show();
      });
    }

    audio() {
      const AC = window.AudioContext || window.webkitAudioContext;
      return this.ctx || (this.ctx = AC ? new AC() : {});
    }

    // Two-note "ding-dong", played twice. Synthesized, so there is no sound file to host.
    chime() {
      const ctx = this.audio();
      if (!ctx.createOscillator) return;
      ctx.resume?.();
      [[0, 784], [0.55, 622], [1.5, 784], [2.05, 622]].forEach(([at, freq]) => {
        const t = ctx.currentTime + at;
        const osc = ctx.createOscillator(), gain = ctx.createGain();
        osc.type = 'sine'; osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.0001, t);
        gain.gain.exponentialRampToValueAtTime(0.5, t + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, t + 1.2);
        osc.connect(gain).connect(ctx.destination);
        osc.start(t); osc.stop(t + 1.3);
      });
    }

    async show({ ring = true } = {}) {
      if (ring) this.chime(); // ring even if the camera feed fails
      const cam = stateManager.data.settings.doorbellCamera;
      if (!cam) return;
      const state = await haWS.getEntityState(cam);
      const token = state?.attributes?.access_token;
      if (!token) return;
      // MJPEG proxy stream: plain <img>, no auth header; token rotates so fetch fresh each ring
      this.img.src = `${haBase()}/api/camera_proxy_stream/${cam}?token=${token}`;
      this.overlay.classList.add('active');
      clearTimeout(this.timer);
      this.timer = setTimeout(() => this.hide(), (stateManager.data.settings.doorbellSeconds || 30) * 1000);
    }

    hide() {
      clearTimeout(this.timer);
      this.overlay.classList.remove('active');
      this.img.removeAttribute('src'); // closes the stream
    }
  }

/* --------------------------------------------------------------------------
     6a. RENDERER
     -------------------------------------------------------------------------- */
  // Re-rendering rebuilds the DOM, which drops an in-progress touch scroll and snaps scrollers back to the top.
  // Remember each scroller's offset (keyed by id, or class + index) and put it back afterwards.
  function keepScrollPositions(render) {
    const scrollers = [...document.querySelectorAll('.dashboard-main, .dashboard-main *, .modal-overlay.active *')].filter(e => e.scrollTop > 0);
    const saved = scrollers.map(e => [e.id || e.className.split(' ')[0], e.id ? 0 : [...document.getElementsByClassName(e.className.split(' ')[0])].indexOf(e), e.scrollTop]);
    const result = render();
    saved.forEach(([name, idx, top]) => {
      const el = document.getElementById(name) || document.getElementsByClassName(name)[idx];
      if (el) el.scrollTop = top;
    });
    return result;
  }

  // The one owner of when and what re-renders. A change invalidates views; those on screen render once, after the
  // current work; views that are not showing wait until they are shown; and every render keeps the scroll positions.
  class Renderer {
    constructor({ preserve = (render) => render(), schedule = (fn) => { Promise.resolve().then(fn); } } = {}) {
      this.preserve = preserve; // runs a render and restores scroll positions around it
      this.schedule = schedule;
      this.views = new Map();   // name -> { render, visible }
      this.dirty = new Set();
      this.queued = false;
    }

    // Registers owner[method] (render by default) as a view. Its render is wrapped, so direct calls keep scroll too
    // and count as the render a pending change was waiting for.
    add(name, owner, { method = 'render', visible = () => true } = {}) {
      const original = owner[method].bind(owner);
      const render = (...args) => {
        this.dirty.delete(name);
        return this.preserve(() => original(...args));
      };
      owner[method] = render;
      this.views.set(name, { render, visible });
    }

    // Marks views stale (all of them when none are named).
    invalidate(...names) {
      (names.length ? names : [...this.views.keys()]).forEach(name => this.dirty.add(name));
      if (this.queued) return;
      this.queued = true;
      this.schedule(() => { this.queued = false; this.flush(); });
    }

    flush() {
      this.views.forEach((view, name) => {
        if (!this.dirty.has(name) || !view.visible()) return;
        try { view.render(); } catch (e) { console.error(`Rendering ${name} failed:`, e); }
      });
    }

    show(name) { this.views.get(name)?.render(); }
  }

/* --------------------------------------------------------------------------
     7. MAIN FAMILY DASHBOARD APP
     -------------------------------------------------------------------------- */
  class FamilyDashboardApp {
    constructor() {
      window.familyDashboard = this;
      this.calendarModule = null;
      this.choresModule = null;
      this.choresAdminModule = null;
      this.mealsModule = null;
      this.photoFrameModule = null;
      this.init();
    }

    init() {
      this.parentGate = new ParentGate(stateManager, pinDialogView());
      this.calendarFeed = new CalendarFeed({ store: stateManager, tasks: parentTasks, cache: localCache('family_dashboard_calendar_v1'), ha: haWS });
      const settings = () => stateManager.data.settings;
      const onError = (e, what) => {
        console.warn(`Home Assistant list ${what} failed:`, e);
        if (what !== 'load') this.showToast('⚠ Home Assistant is unreachable. Saved on this tablet only.');
      };
      this.lists = {
        groceries: new HaList({ ha: haWS, entity: () => settings().haGroceryTodoEntity, local: storeList(stateManager, 'groceries'), onError }),
        ideas: new HaList({ ha: haWS, entity: () => settings().haMealIdeasEntity, local: storeList(stateManager, 'mealIdeas'), addAt: 'start', onError }),
        plan: new MealPlan(new HaList({ ha: haWS, entity: () => settings().haMealPlanEntity, local: memoryList(), onError }))
      };
      this.lists.ideas.subscribe(() => this.renderSettingsMealIdeas(document.getElementById('filter-meal-ideas-input')?.value || ''));

      // 1. Clock & Weather
      try {
        initClockAndWeather((message) => this.showToast(message));
      } catch (e) {
        console.warn('Clock/Weather init error:', e);
      }

      // 2. UI Controls (Navigation, Filters, Theme, Settings)
      try {
        this.renderFamilyFilterBar();
        this.initNavigation();
        this.initTheme();
        this.initNightMode();
        this.initSettingsModal();
      } catch (e) {
        console.warn('UI controls init error:', e);
      }

      // 3. Sub-modules
      try {
        this.calendarModule = new CalendarModule({ feed: this.calendarFeed, mealPlan: this.lists.plan });
      } catch (e) {
        console.error('CalendarModule init error:', e);
      }

      try {
        this.choresModule = new ChoresModule({ gate: this.parentGate, tasks: parentTasks, ledger, toast: (message, action) => this.showToast(message, action) });
      } catch (e) {
        console.error('ChoresModule init error:', e);
      }

      try {
        this.choresAdminModule = new ChoresAdminModule({ gate: this.parentGate, ledger, editChore: (id) => this.choresModule.openChoreModal(null, id) });
      } catch (e) {
        console.error('ChoresAdminModule init error:', e);
      }

      try {
        this.mealsModule = new MealsModule({ lists: this.lists, toast: (message) => this.showToast(message) });
      } catch (e) {
        console.error('MealsModule init error:', e);
      }

      try {
        this.photoFrameModule = new PhotoFrameModule({ feed: this.calendarFeed, beforeStart: () => this.calendarModule?.closeEventPopover() });
      } catch (e) {
        console.error('PhotoFrameModule init error:', e);
      }

      // One owner decides what re-renders when: the household document, the calendar feed and the lists invalidate
      // views, and a view that is not showing waits until it is shown.
      const renderer = this.renderer = new Renderer({ preserve: keepScrollPositions });
      const showing = (id) => () => !!document.getElementById(id)?.classList.contains('active');
      const view = (name, owner, options) => { if (owner) renderer.add(name, owner, options); };
      view('calendar', this.calendarModule, { visible: showing('view-calendar') });
      view('chores', this.choresModule, { visible: showing('view-chores') });
      view('meals', this.mealsModule, { visible: showing('view-meals') });
      view('prize-store', this.choresModule, { method: 'renderStore', visible: showing('store-modal') });
      view('manage-panel', this.choresAdminModule, { method: 'renderAdminBody', visible: showing('admin-panel-modal') });
      view('member-bar', this, { method: 'renderFamilyFilterBar' });
      stateManager.subscribe(() => renderer.invalidate());
      this.calendarFeed.onChange = () => renderer.invalidate('calendar');
      this.lists.groceries.subscribe(() => renderer.invalidate('meals'));
      this.lists.plan.subscribe(() => renderer.invalidate('calendar', 'meals'));

      // Home Assistant calendars every 5 minutes (an ambient display), and the "now" line every minute.
      this.calendarFeed.sync();
      setInterval(() => this.calendarFeed.sync(), 5 * 60 * 1000);
      // The shopping list also changes from phones (through Google Keep), so a wall tablet must keep re-reading it.
      setInterval(() => this.lists.groceries.poll(), 60 * 1000);
      setInterval(() => this.calendarModule?.placeTimeLine(), 60 * 1000);

    }

    renderFamilyFilterBar() {
      const container = document.getElementById('family-filter-bar');
      if (!container) return;

      const activeMemberId = stateManager.data.activeMemberId || 'all';
      const members = stateManager.data.members || [];

      const kids = members.filter(m => m.role === 'kid');
      const parents = members.filter(m => m.role === 'parent');

      let html = `
        <div class="member-pill ${activeMemberId === 'all' ? 'active' : ''}" data-member-id="all" role="button" tabindex="0" aria-pressed="${activeMemberId === 'all'}" aria-label="${this.currentViewId === 'chores' ? 'Kids' : 'Everyone'}" style="--pill-accent: var(--color-primary); color: var(--color-primary-text);">
          <div class="member-avatar" style="background: var(--color-primary)"><i class="fa-solid fa-users" aria-hidden="true"></i></div>
          <div class="member-info">
            <span class="member-name">${this.currentViewId === 'chores' ? 'Kids' : 'Everyone'}</span>
          </div>
        </div>
      `;

      if (kids.length > 0) {
        html += `<div class="family-bar-divider"></div>`;
        kids.forEach(k => {
          const isActive = activeMemberId === k.id;
          html += `
            <div class="member-pill ${isActive ? 'active' : ''}" data-member-id="${k.id}" role="button" tabindex="0" aria-pressed="${isActive}" aria-label="${esc(k.name)}" style="--pill-accent: ${k.color}; color: ${k.color};">
              <div class="member-avatar" style="background: ${k.color}">${esc(k.avatar)}</div>
              <div class="member-info">
                <span class="member-name">${esc(k.name)}</span>
              </div>
            </div>
          `;
        });
      }

      if (parents.length > 0) {
        html += `<div class="family-bar-divider"></div>`;
        parents.forEach(p => {
          const isActive = activeMemberId === p.id;
          html += `
            <div class="member-pill ${isActive ? 'active' : ''}" data-member-id="${p.id}" role="button" tabindex="0" aria-pressed="${isActive}" aria-label="${esc(p.name)}" style="--pill-accent: ${p.color}; color: ${p.color};">
              <div class="member-avatar" style="background: ${p.color}">${esc(p.avatar)}</div>
              <div class="member-info">
                <span class="member-name">${esc(p.name)}</span>
              </div>
            </div>
          `;
        });
      }

      container.innerHTML = html;

      const pick = (root) => root.querySelectorAll('.member-pill').forEach(pill => {
        pill.addEventListener('click', () => stateManager.setActiveMember(pill.dataset.memberId));
      });
      pick(container);

      // Calendar: the bar isn't there; show just the current selection, tap to open the full list.
      const picker = document.getElementById('cal-member-picker');
      if (picker) {
        const current = container.querySelector('.member-pill.active');
        const open = picker.classList.contains('open');
        picker.innerHTML = `
          <button type="button" class="member-pill active picker-current" aria-haspopup="true" aria-expanded="${open}" style="${current?.getAttribute('style') || ''}">
            ${current?.querySelector('.member-avatar')?.outerHTML || ''}
            <span class="member-name">${esc(current?.querySelector('.member-name')?.textContent || 'Everyone')}</span>
            <i class="fa-solid fa-chevron-down picker-caret" aria-hidden="true"></i>
          </button>
          <div class="picker-menu" role="menu">${html}</div>`;
        pick(picker.querySelector('.picker-menu'));
        picker.querySelector('.picker-current').addEventListener('click', (e) => {
          e.stopPropagation();
          document.getElementById('cal-view-picker')?.classList.remove('open');
          e.currentTarget.setAttribute('aria-expanded', picker.classList.toggle('open'));
        });
        if (!this._pickerCloser) {
          this._pickerCloser = true;
          document.addEventListener('click', () => document.getElementById('cal-member-picker')?.classList.remove('open'));
        }
      }
    }

    _handleViewActivation(viewId) {
      this.currentViewId = viewId;
      this.renderFamilyFilterBar(); // the first pill reads "Kids" on Chores, "Everyone" elsewhere
    }

    switchView(viewId, updateHash = true) {
      const validViews = ['calendar', 'chores', 'meals'];
      if (!validViews.includes(viewId)) viewId = 'calendar';

      document.querySelectorAll('.nav-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.view === viewId);
      });
      document.querySelectorAll('.view-panel').forEach(panel => {
        panel.classList.toggle('active', panel.id === `view-${viewId}`);
      });

      this._handleViewActivation(viewId);

      if (viewId === 'calendar') this.calendarModule?.render();
      if (viewId === 'chores') this.choresModule?.render();
      if (viewId === 'meals') this.mealsModule?.render();

      if (updateHash && window.location.hash !== `#${viewId}`) {
        history.replaceState(null, '', `#${viewId}`);
      }
    }

    initNavigation() {
      document.querySelectorAll('.nav-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          this.switchView(btn.dataset.view, true);
        });
      });

      // Restore view from URL hash if valid
      const initialHash = window.location.hash.replace('#', '');
      if (['calendar', 'chores', 'meals'].includes(initialHash)) {
        this.switchView(initialHash, false);
      } else {
        this.switchView('calendar', false);
      }

      window.addEventListener('hashchange', () => {
        const hash = window.location.hash.replace('#', '');
        if (['calendar', 'chores', 'meals'].includes(hash)) {
          this.switchView(hash, false);
        }
      });
    }

    initTheme() {
      const themeMode = stateManager.data.themeMode || 'auto';
      this._applyThemeMode(themeMode);
      this._startSunsetTimer();

      // Wire settings modal toggle buttons
      const syncModeButtons = () => {
        const mode = stateManager.data.themeMode || 'auto';
        document.querySelectorAll('.theme-mode-btn').forEach(btn => {
          btn.classList.toggle('active', btn.dataset.mode === mode);
        });
      };

      document.querySelectorAll('.theme-mode-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const mode = btn.dataset.mode;
          stateManager.data.themeMode = mode;
          stateManager.save();
          this._applyThemeMode(mode);
          syncModeButtons();
        });
      });

      // Sync button states when settings modal opens
      const settingsBtn = document.getElementById('settings-btn');
      if (settingsBtn) {
        settingsBtn.addEventListener('click', () => setTimeout(syncModeButtons, 50));
      }
    }

    _applyThemeMode(mode) {
      if (mode === 'auto') {
        this._applyAutoTheme();
      } else {
        document.documentElement.setAttribute('data-theme', mode);
      }
    }

    _applyAutoTheme() {
      const now = new Date();
      const hour = now.getHours();
      const fallbackDaytime = hour >= 7 && hour < 20;

      const applyResult = (isDaytime) => {
        const theme = isDaytime ? 'light' : 'dark';
        document.documentElement.setAttribute('data-theme', theme);
      };

      if (haWS && typeof haWS.getEntityState === 'function') {
        haWS.getEntityState('sun.sun').then(state => {
          applyResult(state ? state.state === 'above_horizon' : fallbackDaytime); // no sun.sun without Home Assistant
        }).catch(() => applyResult(fallbackDaytime));
      } else {
        applyResult(fallbackDaytime);
      }
    }

    _startSunsetTimer() {
      setInterval(() => {
        if ((stateManager.data.themeMode || 'auto') === 'auto') {
          this._applyAutoTheme();
        }
      }, 10 * 60 * 1000);
    }


    // A black layer over everything but the doorbell popup: a web page cannot reach the tablet's backlight (ADR 0014).
    initNightMode() {
      const dim = document.getElementById('night-dim');
      const modeSelect = document.getElementById('night-mode-select');
      const brightness = document.getElementById('night-brightness-input');
      let wakeTimer = null;    // set while a tap has lifted the dimming
      let previewLevel = null; // the slider's value while a parent is dragging it
      let previewTimer = null;

      const apply = () => {
        const s = stateManager.data.settings;
        const night = !wakeTimer && NightMode.isNight(s, new Date(), weatherCache.data?.sun);
        const level = previewLevel ?? (night ? s.nightBrightness : 100);
        dim.style.opacity = String(1 - level / 100);
        dim.classList.toggle('active', night && previewLevel === null); // only catches taps when really dimmed
      };

      const keepAwake = () => {
        clearTimeout(wakeTimer);
        wakeTimer = setTimeout(() => { wakeTimer = null; apply(); }, (stateManager.data.settings.idleSaverMinutes || 2) * 60 * 1000);
      };

      // The first tap only wakes the screen, so nothing hidden gets pressed in the dark.
      dim.addEventListener('click', () => { keepAwake(); apply(); });
      ['pointerdown', 'keydown'].forEach(evt => window.addEventListener(evt, () => { if (wakeTimer) keepAwake(); }, { passive: true }));

      const syncFields = () => {
        document.getElementById('night-times').hidden = modeSelect.value !== 'schedule';
        document.getElementById('night-brightness-group').hidden = modeSelect.value === 'off';
        document.getElementById('night-brightness-value').textContent = `${brightness.value}%`;
      };
      modeSelect.addEventListener('change', syncFields);
      brightness.addEventListener('input', () => {
        syncFields();
        previewLevel = Number(brightness.value);
        apply();
        clearTimeout(previewTimer);
        previewTimer = setTimeout(() => { previewLevel = null; apply(); }, 1500);
      });
      document.addEventListener('settings-opened', syncFields);
      document.addEventListener('settings-saved', apply);

      apply();
      setInterval(apply, 30 * 1000); // also picks up the sun times once the weather has loaded
    }

    initSettingsModal() {
      const modal = document.getElementById('settings-modal');
      const openBtn = document.getElementById('settings-btn');
      const closeBtn = document.getElementById('settings-modal-close');
      const cancelBtn = document.getElementById('settings-modal-cancel');
      const resetBtn = document.getElementById('reset-data-btn');
      const haTestBtn = document.getElementById('ha-test-btn');
      const syncHABtn = document.getElementById('sync-ha-calendars-btn') || document.getElementById('sync-ical-btn');
      const addMealIdeaBtn = document.getElementById('add-meal-idea-btn');
      const newMealIdeaInput = document.getElementById('new-meal-idea-input');
      const filterMealIdeasInput = document.getElementById('filter-meal-ideas-input');

      this.activeSettingsTab = 'calendar';
      this.editingMealIdeaId = null;

      // Tab switcher helper
      this.switchSettingsTab = (tabName) => {
        this.activeSettingsTab = tabName;
        const tabs = modal?.querySelectorAll('.settings-tab') || [];
        const panels = modal?.querySelectorAll('.settings-tab-panel') || [];

        tabs.forEach(tab => {
          const isCurrent = tab.dataset.settingsTab === tabName;
          tab.classList.toggle('active', isCurrent);
          tab.setAttribute('aria-selected', isCurrent ? 'true' : 'false');
          tab.setAttribute('tabindex', isCurrent ? '0' : '-1');
        });

        panels.forEach(panel => {
          const isCurrent = panel.id === `settings-tab-${tabName}`;
          if (isCurrent) {
            panel.removeAttribute('hidden');
            panel.classList.add('active');
          } else {
            panel.setAttribute('hidden', '');
            panel.classList.remove('active');
          }
        });

        if (tabName === 'calendar') {
          this.renderHACalendarSettingsInputs();
        } else if (tabName === 'todos') {
          this.renderMemberSettingsInputs();
        } else if (tabName === 'meals') {
          this.renderSettingsMealIdeas(filterMealIdeasInput?.value || '');
        }
      };

      // Settings tabs click & keyboard navigation
      const tabButtons = modal?.querySelectorAll('.settings-tab') || [];
      tabButtons.forEach((tab, index) => {
        tab.addEventListener('click', () => {
          const tabName = tab.dataset.settingsTab;
          if (tabName) this.switchSettingsTab(tabName);
        });

        tab.addEventListener('keydown', (e) => {
          let targetIndex = -1;
          if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
            targetIndex = (index + 1) % tabButtons.length;
          } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
            targetIndex = (index - 1 + tabButtons.length) % tabButtons.length;
          } else if (e.key === 'Home') {
            targetIndex = 0;
          } else if (e.key === 'End') {
            targetIndex = tabButtons.length - 1;
          }

          if (targetIndex !== -1) {
            e.preventDefault();
            const targetTab = tabButtons[targetIndex];
            targetTab.focus();
            const tabName = targetTab.dataset.settingsTab;
            if (tabName) this.switchSettingsTab(tabName);
          }
        });
      });

      // Meal ideas add & filter listeners in Settings
      if (addMealIdeaBtn && newMealIdeaInput) {
        addMealIdeaBtn.addEventListener('click', () => this.handleAddSettingsMealIdea());
        newMealIdeaInput.addEventListener('keypress', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            this.handleAddSettingsMealIdea();
          }
        });
      }

      if (filterMealIdeasInput) {
        filterMealIdeasInput.addEventListener('input', (e) => {
          this.renderSettingsMealIdeas(e.target.value);
        });
      }

      if (openBtn && modal) {
        openBtn.addEventListener('click', async () => {
          if (!(await this.parentGate.ask('Parent Settings', 'Enter your 4-digit parent PIN to open settings.'))) return;
          const s = stateManager.data.settings;
          Object.entries(SettingsSchema.toForm(s)).forEach(([id, value]) => {
            const input = document.getElementById(id);
            if (input) {
              if (input.type === 'checkbox') input.checked = (value === 'true');
              else input.value = value;
            }
          });
          document.dispatchEvent(new Event('settings-opened'));

          const latInput = document.getElementById('weather-lat-input');
          const lonInput = document.getElementById('weather-lon-input');
          const locNameInput = document.getElementById('weather-location-name-input');
          if (latInput) latInput.value = s.weather?.lat ?? '';
          if (lonInput) lonInput.value = s.weather?.lon ?? '';
          if (locNameInput) locNameInput.value = s.weather?.locationName ?? '';

          this.switchSettingsTab(this.activeSettingsTab || 'calendar');
          this.renderHACalendarSettingsInputs();
          this.renderMemberSettingsInputs();
          this.renderSettingsMealIdeas();
          modal.classList.add('active');
        });
      }
      if (closeBtn && modal) {
        closeBtn.addEventListener('click', () => modal.classList.remove('active'));
      }
      if (cancelBtn && modal) {
        cancelBtn.addEventListener('click', () => modal.classList.remove('active'));
      }

      // Data Export / Import / Reset to Baseline
      const exportDataBtn = document.getElementById('export-data-btn');
      const importDataBtn = document.getElementById('import-data-btn');
      const importFileInput = document.getElementById('import-data-file-input');

      if (exportDataBtn) {
        exportDataBtn.addEventListener('click', () => {
          try {
            stateManager.exportData();
            this.showToast('✅ Exported dashboard-data.json successfully!');
          } catch (err) {
            console.error('Export error:', err);
            this.showToast('❌ Failed to export data backup: ' + err.message);
          }
        });
      }

      if (importDataBtn && importFileInput) {
        importDataBtn.addEventListener('click', () => {
          importFileInput.click();
        });

        importFileInput.addEventListener('change', (e) => {
          const file = e.target.files?.[0];
          if (!file) return;

          const reader = new FileReader();
          reader.onload = (event) => {
            try {
              const content = event.target?.result;
              if (typeof content !== 'string') throw new Error('File read failed');
              const res = stateManager.importData(content);
              if (res.success) {
                this.showToast('✅ Dashboard data restored successfully! Refreshing...');
                setTimeout(() => {
                  location.reload();
                }, 800);
              } else {
                this.showToast('❌ Import error: ' + res.error);
              }
            } catch (err) {
              this.showToast('❌ Invalid JSON backup file');
            } finally {
              importFileInput.value = '';
            }
          };
          reader.onerror = () => {
            this.showToast('❌ Error reading file');
            importFileInput.value = '';
          };
          reader.readAsText(file);
        });
      }

      if (resetBtn) {
        resetBtn.addEventListener('click', async () => {
          if (confirm('Are you sure you want to reset all dashboard data back to baseline? Any local customizations will be reverted to data/dashboard-data.json.')) {
            this.showToast('🔄 Resetting data to baseline...');
            if (await stateManager.resetToBaseline()) location.reload();
            else this.showToast('⚠️ Could not load data/dashboard-data.json. Data left unchanged.');
          }
        });
      }

      if (haTestBtn) {
        haTestBtn.addEventListener('click', async () => {
          const urlInput = document.getElementById('ha-url-input');
          const tokenInput = document.getElementById('ha-token-input');
          const badge = document.getElementById('ha-status-badge');

          if (haWS?.isNative?.()) {
            this.showToast('Testing native Home Assistant connection...');
            if (badge) {
              badge.className = 'ha-status-badge';
              badge.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Testing connection...';
            }
            try {
              await haWS.send({ type: 'get_config' });
              if (badge) {
                badge.className = 'ha-status-badge success';
                badge.innerHTML = '<i class="fa-solid fa-check"></i> Connected via Home Assistant Session';
              }
              this.showToast('✅ Home Assistant session is active and operational!');
              await this.populateHACalendarsDropdown();
            } catch (err) {
              if (badge) {
                badge.className = 'ha-status-badge error';
                badge.innerHTML = '<i class="fa-solid fa-circle-xmark"></i> Native Session Error';
              }
              this.showToast('❌ Native connection error: ' + err.message);
            }
            return;
          }

          const testUrl = (urlInput?.value || stateManager.data.settings.haUrl || 'http://homeassistant.local:8123').trim();
          const testToken = (tokenInput?.value || stateManager.data.settings.haToken || '').trim();

          this.showToast(`Testing connection to Home Assistant (${testUrl})...`);
          if (badge) {
            badge.className = 'ha-status-badge';
            badge.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Testing connection...';
          }

          try {
            const res = await fetch(`${testUrl}/api/`, {
              headers: { 'Authorization': `Bearer ${testToken}` }
            });
            if (res.ok) {
              if (badge) {
                badge.className = 'ha-status-badge success';
                badge.innerHTML = `<i class="fa-solid fa-check"></i> Connected (${testUrl})`;
              }
              this.showToast('✅ Home Assistant is connected and operational!');
              await this.populateHACalendarsDropdown();
            } else if (res.status === 401) {
              if (badge) {
                badge.className = 'ha-status-badge error';
                badge.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> 401 Unauthorized: Invalid Token';
              }
              this.showToast('❌ 401 Unauthorized: Invalid token. Generate a new Long-Lived Access Token in HA.');
            } else {
              if (badge) {
                badge.className = 'ha-status-badge error';
                badge.innerHTML = `<i class="fa-solid fa-circle-xmark"></i> HTTP Error ${res.status}`;
              }
              this.showToast(`❌ Connection error: HTTP ${res.status}`);
            }
          } catch (err) {
            console.error('HA connection test failed:', err);
            if (badge) {
              badge.className = 'ha-status-badge error';
              badge.innerHTML = `<i class="fa-solid fa-circle-xmark"></i> Cannot Reach ${testUrl}`;
            }
            this.showToast(`❌ Cannot connect to ${testUrl}. Check network/CORS.`);
          }
        });
      }

      if (syncHABtn) {
        syncHABtn.addEventListener('click', async () => {
          this.saveHACalendarInputs();
          stateManager.save();
          this.showToast('📡 Syncing Home Assistant calendars...');
          const count = await this.calendarFeed.sync();
          if (count > 0) {
            this.showToast(`✅ Synced ${count} events from Home Assistant!`);
          } else {
            this.showToast('⚠️ No events found. Check calendar entity IDs and token.');
          }
        });
      }

      const weatherDetectBtn = document.getElementById('weather-detect-location-btn');
      if (weatherDetectBtn) {
        weatherDetectBtn.addEventListener('click', async () => {
          const statusEl = document.getElementById('weather-detect-status');
          if (statusEl) statusEl.textContent = 'Detecting location...';

          const s = stateManager.data.settings;
          if (haWS.isNative() || (s.haUrl && s.haToken)) {
            try {
              let cfg = null;
              if (haWS.isNative()) cfg = await haWS.send({ type: 'get_config' });
              else {
                const res = await fetch(`${s.haUrl}/api/config`, { headers: { 'Authorization': `Bearer ${s.haToken}` } });
                if (res.ok) cfg = await res.json();
              }
              if (cfg) {
                if (cfg.latitude && cfg.longitude) {
                  const latIn = document.getElementById('weather-lat-input');
                  const lonIn = document.getElementById('weather-lon-input');
                  const nameIn = document.getElementById('weather-location-name-input');
                  if (latIn) latIn.value = cfg.latitude;
                  if (lonIn) lonIn.value = cfg.longitude;
                  if (nameIn) nameIn.value = cfg.location_name || 'Home';
                  if (statusEl) statusEl.textContent = `Found via Home Assistant: ${cfg.location_name || 'Home'}`;
                  return;
                }
              }
            } catch (e) {}
          }

          if ('geolocation' in navigator) {
            navigator.geolocation.getCurrentPosition(
              (pos) => {
                const latIn = document.getElementById('weather-lat-input');
                const lonIn = document.getElementById('weather-lon-input');
                const nameIn = document.getElementById('weather-location-name-input');
                if (latIn) latIn.value = pos.coords.latitude.toFixed(4);
                if (lonIn) lonIn.value = pos.coords.longitude.toFixed(4);
                if (nameIn) nameIn.value = 'Local';
                if (statusEl) statusEl.textContent = 'Found via GPS / Browser.';
              },
              () => {
                if (statusEl) statusEl.textContent = 'Could not detect automatically. Enter coordinates manually.';
              }
            );
          } else {
            if (statusEl) statusEl.textContent = 'Geolocation not supported by browser.';
          }
        });
      }

      document.getElementById('save-settings-btn')?.addEventListener('click', async () => {
        const typed = Object.fromEntries(SettingsSchema.fields().map(id => {
          const el = document.getElementById(id);
          if (!el) return [id, undefined];
          if (el.type === 'checkbox') return [id, el.checked ? 'true' : 'false'];
          return [id, el.value?.trim()];
        }));
        Object.assign(stateManager.data.settings, SettingsSchema.fromForm(typed));

        const weatherLat = parseFloat(document.getElementById('weather-lat-input')?.value);
        const weatherLon = parseFloat(document.getElementById('weather-lon-input')?.value);
        const weatherLocName = document.getElementById('weather-location-name-input')?.value?.trim();
        if (!isNaN(weatherLat) && !isNaN(weatherLon)) {
          if (!stateManager.data.settings.weather) stateManager.data.settings.weather = {};
          stateManager.data.settings.weather.lat = weatherLat;
          stateManager.data.settings.weather.lon = weatherLon;
          if (weatherLocName) stateManager.data.settings.weather.locationName = weatherLocName;
          fetchLiveWeatherData(true).then(renderWeatherUI);
        }
        
        this.saveHACalendarInputs();
        this.saveMemberSettingsInputs();
        stateManager.save();
        document.dispatchEvent(new Event('settings-saved'));
        
        modal?.classList.remove('active');
        this.showToast('💾 Settings saved! Syncing Home Assistant calendars...');
        // Switching kiosk mode reloads the page, so let the save above reach Home Assistant first.
        setTimeout(() => setHaKioskMode(!!stateManager.data.settings.haKioskMode), 1500);

        const count = await this.calendarFeed.sync();
        if (count > 0) {
          this.showToast(`✅ Synced ${count} events from Home Assistant!`);
        }
      });
    }

    async handleAddSettingsMealIdea() {
      const input = document.getElementById('new-meal-idea-input');
      const name = input?.value?.trim();
      if (!name) return;

      const added = await this.lists.ideas.add(name);
      if (added) {
        input.value = '';
        this.showToast(`✓ Added "${name}" to meal ideas`);
      }
    }

    renderSettingsMealIdeas(filterQuery = '') {
      const list = document.getElementById('settings-meal-ideas-list');
      const badge = document.getElementById('meal-ideas-count-badge');
      if (!list) return;

      const allIdeas = this.lists.ideas.items;

      const q = (filterQuery || '').trim().toLowerCase();
      const filtered = allIdeas.filter(item => !q || item.name.toLowerCase().includes(q));

      if (badge) {
        badge.textContent = `${allIdeas.length} idea${allIdeas.length !== 1 ? 's' : ''}`;
      }

      if (filtered.length === 0) {
        list.innerHTML = `<li class="meal-ideas-empty">${q ? `No meal ideas matching "${esc(filterQuery)}"` : 'No meal ideas yet. Add your favorite dinners above!'}</li>`;
        return;
      }

      list.innerHTML = filtered.map(idea => {
        const isEditing = this.editingMealIdeaId === idea.id;
        const safeName = esc(idea.name);
        if (isEditing) {
          return `
            <li class="settings-meal-idea-item editing" data-idea-id="${idea.id}">
              <div class="idea-edit-row">
                <input type="text" class="idea-edit-input" id="edit-meal-input-${idea.id}" value="${safeName}" aria-label="Edit meal idea" />
                <button type="button" class="idea-action-btn btn-save" data-action="save" data-id="${idea.id}" title="Save changes" aria-label="Save">
                  <i class="fa-solid fa-check"></i>
                </button>
                <button type="button" class="idea-action-btn btn-cancel" data-action="cancel" data-id="${idea.id}" title="Cancel" aria-label="Cancel">
                  <i class="fa-solid fa-xmark"></i>
                </button>
              </div>
            </li>
          `;
        }

        return `
          <li class="settings-meal-idea-item" data-idea-id="${idea.id}">
            <div class="idea-content">
              <i class="fa-solid fa-bowl-food idea-icon"></i>
              <span class="idea-name" title="${safeName}">${esc(idea.name)}</span>
            </div>
            <div class="idea-actions">
              <button type="button" class="idea-action-btn btn-edit" data-action="edit" data-id="${idea.id}" title="Modify meal idea" aria-label="Modify idea">
                <i class="fa-solid fa-pen"></i>
              </button>
              <button type="button" class="idea-action-btn btn-delete" data-action="delete" data-id="${idea.id}" title="Remove meal idea" aria-label="Remove idea">
                <i class="fa-solid fa-trash-can"></i>
              </button>
            </div>
          </li>
        `;
      }).join('');

      // Wire up action buttons
      list.querySelectorAll('.idea-action-btn').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const action = btn.dataset.action;
          const id = btn.dataset.id;
          if (!id) return;

          if (action === 'edit') {
            this.editingMealIdeaId = id;
            this.renderSettingsMealIdeas(filterQuery);
            const editInput = document.getElementById(`edit-meal-input-${id}`);
            if (editInput) {
              editInput.focus();
              editInput.select();
            }
          } else if (action === 'cancel') {
            this.editingMealIdeaId = null;
            this.renderSettingsMealIdeas(filterQuery);
          } else if (action === 'save') {
            const editInput = document.getElementById(`edit-meal-input-${id}`);
            const newName = editInput?.value?.trim();
            if (newName) {
              await this.lists.ideas.rename(id, newName);
              this.editingMealIdeaId = null;
              this.renderSettingsMealIdeas(filterQuery);
              this.showToast('✓ Meal idea updated!');
            }
          } else if (action === 'delete') {
            await this.lists.ideas.remove(id);
            this.renderSettingsMealIdeas(filterQuery);
            this.showToast('✓ Removed meal idea');
          }
        });
      });

      // Wire up Enter / Escape in edit mode
      list.querySelectorAll('.idea-edit-input').forEach(input => {
        input.addEventListener('keydown', async (e) => {
          const id = input.id.replace('edit-meal-input-', '');
          if (e.key === 'Enter') {
            e.preventDefault();
            const newName = input.value.trim();
            if (newName) {
              await this.lists.ideas.rename(id, newName);
              this.editingMealIdeaId = null;
              this.renderSettingsMealIdeas(filterQuery);
              this.showToast('✓ Meal idea updated!');
            }
          } else if (e.key === 'Escape') {
            e.preventDefault();
            this.editingMealIdeaId = null;
            this.renderSettingsMealIdeas(filterQuery);
          }
        });
      });
    }

    renderMemberSettingsInputs() {
      const container = document.getElementById('member-settings-container');
      if (!container) return;

      const members = stateManager.data.members || [];
      container.innerHTML = members.map(m => {
        const isKid = m.role === 'kid';
        return `
          <div class="member-setting-card" data-member-id="${m.id}">
            <div class="member-setting-profile">
              <input type="text" class="member-setting-avatar" id="member-avatar-${m.id}" value="${esc(m.avatar || '')}" maxlength="4" aria-label="${esc(m.name)} icon" style="width:56px;text-align:center;padding:0;" />
              <div>
                <div class="member-setting-name">${esc(m.name)}</div>
                <span class="member-setting-role-badge">${m.role}</span>
              </div>
            </div>
            ${isKid ? `
              <div class="member-setting-inputs">
                <div class="member-setting-field">
                  <label for="member-target-stars-${m.id}">Target Stars:</label>
                  <input type="number" id="member-target-stars-${m.id}" value="${m.targetStars || 50}" min="1" max="500" />
                </div>
                <div class="member-setting-field" style="flex:1;">
                  <label for="member-target-reward-${m.id}">Reward:</label>
                  <input type="text" id="member-target-reward-${m.id}" value="${(m.targetReward || '').replace(/"/g, '&quot;')}" placeholder="e.g. Lego Set..." style="width:100%;" />
                </div>
              </div>
            ` : `
              <div class="member-setting-inputs">
                <span style="font-size:0.8rem; color:var(--text-secondary);"><i class="fa-solid fa-shield"></i> Parent Admin</span>
              </div>
            `}
          </div>
        `;
      }).join('');
    }

    saveMemberSettingsInputs() {
      const members = stateManager.data.members || [];
      members.forEach(m => {
        const avatarInput = document.getElementById(`member-avatar-${m.id}`);
        if (avatarInput?.value.trim()) m.avatar = avatarInput.value.trim();
        if (m.role === 'kid') {
          const starsInput = document.getElementById(`member-target-stars-${m.id}`);
          const rewardInput = document.getElementById(`member-target-reward-${m.id}`);
          if (starsInput && starsInput.value) {
            m.targetStars = parseInt(starsInput.value, 10) || m.targetStars;
          }
          if (rewardInput) {
            m.targetReward = rewardInput.value.trim() || m.targetReward;
          }
        }
      });
    }

    renderHACalendarSettingsInputs() {
      const container = document.getElementById('ha-calendar-entities-container') || document.getElementById('ical-feeds-inputs-container');
      if (!container) return;

      const members = stateManager.data.members;
      container.innerHTML = members.map(m => `
        <div class="form-group" style="margin-bottom: 12px;">
          <label style="display: flex; align-items: center; gap: 8px; font-weight: 600;">
            <span style="font-size: 1.2rem;">${esc(m.avatar)}</span>
            <span>${esc(m.name)}</span>
            <span style="font-size: 0.75rem; color: var(--text-secondary); font-weight: normal;">(${m.role})</span>
          </label>
          <input 
            type="text" 
            id="ha-cal-entity-${m.id}" 
            list="ha-calendars-datalist" 
            value="${m.haCalendarEntity || ''}" 
            placeholder="calendar.${m.id.toLowerCase()}..." 
            style="width: 100%; font-family: monospace; font-size: 0.9rem;"
          />
        </div>
      `).join('');

      this.populateHACalendarsDropdown();
    }

    saveHACalendarInputs() {
      const members = stateManager.data.members;
      members.forEach(m => {
        const input = document.getElementById(`ha-cal-entity-${m.id}`);
        if (input) {
          m.haCalendarEntity = input.value.trim();
        }
      });
    }

    async populateHACalendarsDropdown() {
      const datalist = document.getElementById('ha-calendars-datalist');
      if (!datalist) return;

      if (haWS.isNative()) {
        try {
          const states = await haWS.send({ type: 'get_states' });
          datalist.innerHTML = states.filter(e => e.entity_id.startsWith('calendar.')).map(e => `
            <option value="${esc(e.entity_id)}">${esc(e.attributes?.friendly_name || e.entity_id)}</option>
          `).join('');
        } catch (err) {
          console.warn('Could not fetch calendar entities for autocomplete:', err);
        }
        return;
      }

      let haUrl = stateManager.data.settings.haUrl || 'http://homeassistant.local:8123';
      if (window.location.pathname.includes('/local/') || window.location.port === '8123') {
        haUrl = window.location.origin;
      }
      const token = stateManager.data.settings.haToken;
      if (!token) return;

      try {
        const res = await fetch(`${haUrl}/api/calendars`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (res.ok) {
          const calendars = await res.json();
          datalist.innerHTML = calendars.map(c => `
            <option value="${esc(c.entity_id)}">${esc(c.name || c.entity_id)}</option>
          `).join('');
        }
      } catch (err) {
        console.warn('Could not fetch calendar entities for autocomplete:', err);
      }
    }

    // Leading emoji in a message picks the icon (error / success / info) and is not displayed.
    showToast(message, action) {
      const container = document.getElementById('toast-container');
      if (!container) return;

      const kind = /^(❌|⚠)/u.test(message) ? 'fa-circle-exclamation' : /^(✅|✓)/u.test(message) ? 'fa-circle-check' : 'fa-circle-info';
      const toast = document.createElement('div');
      toast.className = 'toast';
      toast.innerHTML = `${icon(kind)}<span></span>`;
      toast.lastElementChild.textContent = message.replace(/^[^\p{L}\p{N}]+/u, '');
      if (action) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'toast-action';
        btn.textContent = action.label;
        btn.addEventListener('click', () => { action.run(); toast.remove(); });
        toast.appendChild(btn);
      }
      container.appendChild(toast);

      setTimeout(() => {
        toast.classList.add('leaving');
        setTimeout(() => toast.remove(), 300);
      }, action ? 6000 : 3500);
    }
  }

  /* --------------------------------------------------------------------------
     ACCESSIBILITY: GLOBAL MODAL KEYBOARD MANAGEMENT & FOCUS TRAPPING
     -------------------------------------------------------------------------- */
  function initAccessibleModals() {
    let lastActiveElement = null;

    document.querySelectorAll('.modal-overlay, .meal-picker-overlay').forEach(m => {
      m.setAttribute('role', 'dialog');
      m.setAttribute('aria-modal', 'true');
      const heading = m.querySelector('h3[id], h4[id]') || m.querySelector('h3, h4');
      if (heading) {
        if (!heading.id) heading.id = `${m.id}-title`;
        m.setAttribute('aria-labelledby', heading.id);
      }
    });

    function getFocusableElements(container) {
      if (!container) return [];
      return Array.from(container.querySelectorAll(
        'button:not([disabled]):not([aria-hidden="true"]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
      )).filter(el => el.offsetParent !== null);
    }

    // Capture triggering element before modal opens
    document.addEventListener('click', (e) => {
      const trigger = e.target.closest('button, [role="button"], .clickable');
      if (trigger) {
        lastActiveElement = trigger;
      }
    }, true);

    // Watch for modals opening / closing
    // Mirror the visual `.active` state of toggle-style buttons into ARIA.
    const syncPressed = (t) => {
      const on = t.classList.contains('active');
      if (t.matches('.nav-btn')) { on ? t.setAttribute('aria-current', 'page') : t.removeAttribute('aria-current'); }
      else if (t.matches('.switch-btn, .theme-mode-btn, .layer-toggle-btn, .admin-tab')) t.setAttribute('aria-pressed', on);
    };
    document.querySelectorAll('.nav-btn, .switch-btn, .theme-mode-btn, .layer-toggle-btn, .admin-tab').forEach(syncPressed);

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'attributes' && mutation.target.matches?.('.nav-btn, .switch-btn, .theme-mode-btn, .layer-toggle-btn, .admin-tab')) syncPressed(mutation.target);
        if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
          const target = mutation.target;
          if (target.classList && (target.classList.contains('modal-overlay') || target.classList.contains('meal-picker-overlay'))) {
            if (target.classList.contains('active')) {
              requestAnimationFrame(() => {
                const card = target.querySelector('.modal-card') || target;
                card.tabIndex = -1;
                card.focus({ preventScroll: true });
              });
            } else {
              if (lastActiveElement && typeof lastActiveElement.focus === 'function') {
                lastActiveElement.focus();
              }
            }
          }
        }
      });
    });

    observer.observe(document.body, {
      attributes: true,
      subtree: true,
      attributeFilter: ['class']
    });

    // Enter/Space activates non-<button> controls (role=button/checkbox) and keeps focus across re-renders.
    document.addEventListener('keydown', (e) => {
      const el = e.target.closest?.('[role="button"], [role="checkbox"]');
      if (!el || (e.key !== 'Enter' && e.key !== ' ')) return;
      e.preventDefault();
      const id = ['data-item-id', 'data-member-id', 'data-kid-tab'].map(a => [a, el.getAttribute(a)]).find(([, v]) => v);
      el.click();
      if (id) setTimeout(() => [...document.querySelectorAll(`[${id[0]}="${id[1]}"]`)].find(n => n.offsetParent)?.focus(), 0);
    });

    // Keyboard handlers: Escape to close, Tab to trap focus
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const activeModals = document.querySelectorAll('.modal-overlay.active, .meal-picker-overlay.active');
        if (activeModals.length > 0) {
          e.preventDefault();
          const topModal = activeModals[activeModals.length - 1];
          topModal.classList.remove('active');
          if (lastActiveElement && typeof lastActiveElement.focus === 'function') {
            lastActiveElement.focus();
          }
          return;
        }

        const popover = document.getElementById('event-details-popover');
        if (popover && popover.classList.contains('active')) {
          e.preventDefault();
          popover.classList.remove('active');
          if (lastActiveElement && typeof lastActiveElement.focus === 'function') {
            lastActiveElement.focus();
          }
          return;
        }

        const photoSaver = document.getElementById('photo-frame-overlay');
        if (photoSaver && photoSaver.classList.contains('active')) {
          e.preventDefault();
          photoSaver.classList.remove('active');
          return;
        }
      }

      if (e.key === 'Tab') {
        const activeModal = document.querySelector('.modal-overlay.active, .meal-picker-overlay.active');
        if (!activeModal) return;

        const focusable = getFocusableElements(activeModal);
        if (focusable.length === 0) return;

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (e.shiftKey) {
          if (document.activeElement === first || !focusable.includes(document.activeElement)) {
            e.preventDefault();
            last.focus();
          }
        } else {
          if (document.activeElement === last || !activeModal.contains(document.activeElement)) {
            e.preventDefault();
            first.focus();
          }
        }
      }
    });

    // Global backdrop click dismissal for modals
    document.addEventListener('click', (e) => {
      if (e.target && e.target.classList && e.target.classList.contains('modal-overlay') && e.target.classList.contains('active')) {
        e.target.classList.remove('active');
        if (lastActiveElement && typeof lastActiveElement.focus === 'function') {
          lastActiveElement.focus();
        }
      }
    });
  }

// JS fallback for touch scrolling. Embedded web views (the Home Assistant iPad app) can swallow the native
  // swipe for nested overflow areas; handling the drag ourselves works wherever touch events arrive.
  function enableTouchScroll() {
    if (!('ontouchstart' in window)) return;
    let el = null, startX = 0, startY = 0, startTop = 0, lastY = 0, lastT = 0, vel = 0, dir = null, raf = 0;
    const scrollerOf = (node) => {
      for (; node && node !== document.body; node = node.parentElement) {
        const oy = getComputedStyle(node).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && node.scrollHeight > node.clientHeight + 1) return node;
      }
      return null;
    };
    document.addEventListener('touchstart', (e) => {
      cancelAnimationFrame(raf);
      el = null; dir = null;
      if (e.touches.length !== 1 || e.target.closest('input, select, textarea, [draggable="true"], iframe')) return;
      el = scrollerOf(e.target);
      if (!el) return;
      startX = e.touches[0].clientX; startY = lastY = e.touches[0].clientY; startTop = el.scrollTop; lastT = e.timeStamp; vel = 0;
    }, { passive: true });
    document.addEventListener('touchmove', (e) => {
      if (!el) return;
      const t = e.touches[0];
      const dx = t.clientX - startX, dy = t.clientY - startY;
      if (!dir) {
        if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
        dir = Math.abs(dy) >= Math.abs(dx) ? 'v' : 'h';
      }
      if (dir === 'h') { el = null; return; } // leave sideways swipes to the browser
      const dt = Math.max(1, e.timeStamp - lastT);
      vel = (lastY - t.clientY) / dt; // px per ms, positive = scrolling down
      lastY = t.clientY; lastT = e.timeStamp;
      el.scrollTop = startTop - dy;
      if (e.cancelable) e.preventDefault();
    }, { passive: false });
    const end = () => {
      const node = el; el = null;
      if (!node || dir !== 'v' || Math.abs(vel) < 0.15) return;
      let v = vel * 16, last = performance.now();
      const step = (now) => {
        const f = Math.min(3, (now - last) / 16); last = now;
        node.scrollTop += v * f;
        v *= Math.pow(0.95, f);
        if (Math.abs(v) > 0.5) raf = requestAnimationFrame(step);
      };
      raf = requestAnimationFrame(step);
    };
    document.addEventListener('touchend', end, { passive: true });
    document.addEventListener('touchcancel', end, { passive: true });
  }

  async function initApp() {
    if (!window.familyDashboard) {
      if (typeof stateManager !== 'undefined' && stateManager.loadBaselineIfEmpty) {
        try {
          await stateManager.loadBaselineIfEmpty();
        } catch (e) {
          console.warn('Baseline hydration warning:', e);
        }
      }
      // Pull HA's copy before the first render, but never block startup on an unreachable HA.
      await Promise.race([stateManager.syncRemote(), new Promise(r => setTimeout(r, 3000))]);
      // The bundled Docker server stands in for Home Assistant: no URL, token or WallPanel kiosk to set up.
      if (window.FAMILY_DASHBOARD_CONFIG?.backend === 'server') document.getElementById('ha-section').style.display = 'none';
      if (inHA()) { // the HA login is reused, so there is nothing to type
        document.getElementById('ha-credentials')?.setAttribute('hidden', '');
        document.getElementById('ha-embedded-note')?.removeAttribute('hidden');
      }
      ledger.init();
      ledger.resetPeriodic();
      setInterval(() => ledger.resetPeriodic(), 60 * 1000);
      setInterval(() => stateManager.syncRemote(), 60 * 1000);
      new FamilyDashboardApp();
      new DoorbellModule();
      enableTouchScroll();
      initAccessibleModals();

      watchHaViewport();
      if (stateManager?.data?.settings?.haKioskMode) {
        setHaKioskMode(true);
      }
    }
  }

  // Test seam: tests/ run the bundle without a DOM, take the modules from here and skip booting.
  if (window.__FD_TEST__) { window.__FD_TEST__.api = { ParentGate, ParentTasks, MissionLedger, CalendarFeed, HaList, MealPlan, storeList, SettingsSchema, NightMode, StateManager, HAWebSocket, Renderer, kioskSearch, setHaKioskMode }; return; }

  window.initFamilyDashboardApp = initApp;

  if (!window.__FD_DEFER_BOOT__) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initApp);
    } else {
      initApp();
    }
  }
})();
